import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { listTemplates } from "./api/calibrator";
import { InferenceSettings } from "./components/InferenceSettings";
import { KindPicker } from "./components/KindPicker";
import { preparationLabel, marigoldMapsReady } from "./components/preparationLabel";
import { RendererPanel } from "./components/RendererPanel";
import { TemplateRail } from "./components/TemplateRail";
import { ColourMatrixEditor } from "./editors/ColourMatrixEditor";
import { MARIGOLD_DEFAULTS } from "./editors/marigoldDefaults";
import { MarigoldEditor } from "./editors/MarigoldEditor";
import { MultipleEditor } from "./editors/MultipleEditor";
import { SingleEditor } from "./editors/SingleEditor";
import { usePreparationQueue } from "./hooks/usePreparationQueue";
import { useTemplateReadiness } from "./hooks/useTemplateReadiness";
import { useTemplateSession } from "./hooks/useTemplateSession";
import { SavedAgo } from "./pages/editor/SavedAgo";
import type { Renderer, TemplateKind, TemplateSummary } from "./types";

/** A thin router: picks the template, hands it to an authoring session
 * (`useTemplateSession`, which reads, saves and prepares it) and picks an
 * editor by `kind` -- a template.yaml is exactly one of three shapes, never a
 * mix.
 *
 * Wireframe 2a turns the page into a workbench: the rail on the left picks the
 * template (replacing the dropdown that used to sit in the header), and the
 * header becomes a breadcrumb saying what is open, whether it is finished, and
 * what it holds. */

const KIND_LABELS: Record<TemplateKind, string> = {
  "colour-matrix": "Colour Matrix",
  multiple: "Multiple",
  single: "Single",
};

export function App() {
  const preparationJobs = usePreparationQueue();
  const rendererCache = useRef<Record<string, Partial<Record<Renderer["type"], Renderer>>>>({});
  const [templates, setTemplates] = useState<TemplateSummary[]>([]);
  const [catalogState, setCatalogState] = useState<"loading" | "ready" | "error">("loading");
  const [templateName, setTemplateName] = useState<string | null>(null);
  // Which test artwork the previews render with. A way of looking at a
  // template rather than a property of one, so it lives here and never enters
  // template.yaml -- and it deliberately survives switching template, since
  // "show me all of these against my real artwork" is the point of changing it.
  const [design, setDesign] = useState("bundled-grid");

  // Refreshes overlap: assigning a kind fires one and saving fires another
  // moments later. They are separate requests, so the *older* can resolve
  // last -- putting the pre-assignment list back and reverting the template to
  // "no kind set" on screen while the file on disk says otherwise. The
  // sequence number makes a late response a no-op instead.
  const refreshSeq = useRef(0);
  const currentTemplate = useRef<string | null>(templateName);

  useEffect(() => {
    currentTemplate.current = templateName;
  }, [templateName]);

  const refreshTemplates = useCallback((selectName?: string) => {
    const seq = ++refreshSeq.current;
    const selectionAtRequest = currentTemplate.current;
    listTemplates()
      .then((loaded) => {
        if (seq !== refreshSeq.current) return;
        setCatalogState("ready");
        setTemplates(loaded);
        // A save may finish its catalog refresh after the user has moved on.
        setTemplateName(
          (current) =>
            (current === selectionAtRequest ? selectName : undefined) ??
            current ??
            loaded[0]?.name ??
            null,
        );
      })
      .catch(() => {
        if (seq !== refreshSeq.current) return;
        setCatalogState("error");
      });
  }, []);

  useEffect(() => {
    refreshTemplates();
  }, [refreshTemplates]);

  const session = useTemplateSession(templateName, { onCatalogChanged: refreshTemplates });
  const { config, preparation, preparing, save, update: setConfig, reloadPreparation } = session;

  const mapState = preparation?.maps.state;
  useEffect(() => {
    if (mapState) refreshTemplates();
  }, [mapState, refreshTemplates]);

  const switchRenderer = (type: Renderer["type"]) => {
    if (!config || !templateName || type === config.renderer.type) return;
    const cache = rendererCache.current[templateName] ?? {};
    cache[config.renderer.type] = config.renderer;
    rendererCache.current[templateName] = cache;
    const stored = preparation?.renderer_settings[type];
    const renderer =
      cache[type] ??
      (stored
        ? ({ type, config: stored } as Renderer)
        : type === "marigold"
          ? MARIGOLD_DEFAULTS
          : {
              type: "photo-warp",
              config: {
                displace: { enabled: false, strength: 0 },
                shade: { enabled: true, opacity: 0.6, blend: "soft-light" },
              },
            });
    setConfig({ ...config, renderer });
  };
  const queueKey = preparationJobs
    .filter((job) => job.template === templateName)
    .map((job) => job.id + job.phase)
    .join(",");
  const previousQueueKey = useRef(queueKey);
  useEffect(() => {
    if (previousQueueKey.current !== queueKey) reloadPreparation();
    previousQueueKey.current = queueKey;
  }, [queueKey, reloadPreparation]);
  const railFacts = useTemplateReadiness(templates, templateName, preparationJobs);
  const railTemplates = useMemo(
    () =>
      templates.map((template) =>
        preparation?.template === template.name
          ? { ...template, maps: preparation.maps }
          : { ...template, maps: railFacts[template.name] ?? template.maps ?? null },
      ),
    [templates, preparation, railFacts],
  );
  const selected = templates.find((t) => t.name === templateName);
  const rendererControls =
    config && templateName ? (
      <RendererPanel
        renderer={config.renderer}
        onRendererChange={switchRenderer}
        preparation={preparation}
        onPrepare={(action, recovery) => void session.prepare(action, recovery)}
        onCancel={() => void session.cancelPreparation()}
        pending={preparing}
        error={session.preparationError}
        settings={(runtime) =>
          config.renderer.type === "marigold" ? (
            <InferenceSettings
              templateName={templateName}
              value={config.renderer.config.inference}
              capabilityKnown={Boolean(runtime)}
              {...(runtime
                ? {
                    limits: {
                      num_inference_steps: runtime.max_num_inference_steps,
                      ensemble_size: runtime.max_ensemble_size,
                    },
                  }
                : {})}
              onSave={(inference) => {
                if (config.renderer.type === "marigold")
                  setConfig({
                    ...config,
                    renderer: {
                      ...config.renderer,
                      config: { ...config.renderer.config, inference },
                    },
                  });
              }}
            />
          ) : null
        }
      />
    ) : null;

  // Every colour already in use anywhere in the workspace, for the box
  // colour field's suggestions. Suggestions rather than a closed list: a
  // chart's colours are whatever the listing sells, and nothing here knows
  // that -- wiring in the Printify catalog would be a much larger dependency.
  const knownColours = useMemo(
    () => [...new Set(templates.flatMap((t) => t.colours))].filter(Boolean).sort(),
    [templates],
  );
  const kindLabel = selected?.kind ? KIND_LABELS[selected.kind] : null;

  // The photo's true pixel size, which is the coordinate space every bounding
  // box in template.yaml is written in. It has to come from the API: the
  // editors' canvas renders a downscale now, so measuring the image on screen
  // would put the boxes in the preview's space and save them several times too
  // small. `null` for a directory with no readable photo -- there is nothing
  // to calibrate against, and the editors say so rather than guessing.
  const space: [number, number] | null =
    selected?.width && selected.height ? [selected.width, selected.height] : null;

  return (
    <div className={config?.renderer.type === "marigold" ? "app mg-frame mg-app" : "app mg-frame"}>
      <header className="app__header">
        <h1 className="app__title">Mockup Templates</h1>
        {selected && (
          <>
            <span className="app__crumb-sep">/</span>
            <span className="app__crumb">{selected.name}</span>
            {config && config.renderer.type !== "marigold" && (
              <span
                className={selected.status === "calibrated" ? "tag tag-accent-2" : "tag tag-accent"}
              >
                {selected.status === "calibrated" ? "calibrated" : "needs calibration"}
              </span>
            )}
            {config?.renderer.type === "marigold" && (
              <span
                className={
                  "tag mg-status" +
                  (!preparing && marigoldMapsReady(preparation?.maps)
                    ? " mg-status--ready"
                    : preparation?.latest_job?.phase === "failed"
                      ? " mg-status--failed"
                      : "")
                }
              >
                {preparing ? "Preparing" : preparationLabel(preparation)}
              </span>
            )}
            <span className="app__meta">
              {config?.kind === "multiple"
                ? "Multiple · " + config.placements.length + " placements"
                : selected.status === "calibrated"
                  ? `${kindLabel ?? "Unknown"} · ${selected.colours.length} colour${
                      selected.colours.length === 1 ? "" : "s"
                    }`
                  : (selected.status_reason ?? "not calibrated")}
            </span>
          </>
        )}

        <div className="app__actions">
          <p className="app__status" role="status">
            {save.kind === "saved" ? (
              <span className="page-head__saved">
                <span className="page-head__dot" aria-hidden="true" />
                <SavedAgo savedAt={save.savedAt} />
              </span>
            ) : save.kind === "saving" ? (
              "Saving…"
            ) : save.kind === "failed" || save.kind === "conflict" ? (
              save.message
            ) : session.load === "error" ? (
              "failed to load template config"
            ) : catalogState === "error" ? (
              "failed to load templates"
            ) : (
              ""
            )}
          </p>
          {save.kind === "conflict" && <button onClick={session.reload}>Reload template</button>}
        </div>
      </header>

      <div className="app__workbench">
        <TemplateRail
          templates={railTemplates}
          selectedPreparationStatus={
            config?.renderer.type === "marigold"
              ? preparing
                ? "Preparing"
                : preparationLabel(preparation)
              : null
          }
          selected={templateName}
          onSelect={setTemplateName}
          jobs={preparationJobs}
        />

        <div className="app__workspace">
          {/* 2a: an uncalibrated template replaces the workspace with a single
              choice, so nothing else can be touched yet. Kind decides the
              whole shape of template.yaml (ADR-0014) -- every other control is
              meaningless or wrong until it is answered. */}
          {templateName && session.load !== "ready" ? (
            <p role={session.load === "error" ? "alert" : "status"}>
              {session.load === "error"
                ? "Could not load template configuration. Reload to try again."
                : "Loading template..."}
            </p>
          ) : templateName && !config ? (
            <KindPicker
              key={templateName}
              templateName={templateName}
              onAssigned={() => {
                session.reload();
                refreshTemplates(templateName);
              }}
            />
          ) : (
            <>
              {templateName && config?.renderer.type === "marigold" && (
                <MarigoldEditor
                  key={templateName}
                  templateName={templateName}
                  config={{ ...config, renderer: config.renderer }}
                  space={space}
                  colours={selected?.colours ?? []}
                  knownColours={knownColours}
                  design={design}
                  onDesignChange={setDesign}
                  onChange={setConfig}
                  preparation={preparation}
                  rendererControls={rendererControls}
                  calibrationRevision={session.calibrationRevision}
                  maskEdits={session.maskEdits}
                  onMaskEdits={session.setMaskEdits}
                  onPreviewPending={session.setPreviewPending}
                  savedConfig={session.saved}
                  onPrepare={() =>
                    void session.prepare(
                      preparation?.maps.reason === "photo_changed" ? "prepare_again" : "prepare",
                      preparation?.maps.reason === "photo_changed",
                    )
                  }
                />
              )}
              {templateName &&
                config?.renderer.type === "photo-warp" &&
                config?.kind === "colour-matrix" && (
                  <ColourMatrixEditor
                    key={templateName}
                    rendererControls={rendererControls}
                    templateName={templateName}
                    config={config}
                    space={space}
                    colours={selected?.colours ?? []}
                    onChange={setConfig}
                    design={design}
                    onDesignChange={setDesign}
                    onApprove={() => void session.approve()}
                  />
                )}
              {templateName &&
                config?.renderer.type === "photo-warp" &&
                config?.kind === "multiple" && (
                  <MultipleEditor
                    key={templateName}
                    rendererControls={rendererControls}
                    templateName={templateName}
                    config={config}
                    space={space}
                    onChange={setConfig}
                    design={design}
                    onDesignChange={setDesign}
                    knownColours={knownColours}
                  />
                )}
              {templateName &&
                config?.renderer.type === "photo-warp" &&
                config?.kind === "single" && (
                  <SingleEditor
                    key={templateName}
                    rendererControls={rendererControls}
                    templateName={templateName}
                    config={config}
                    space={space}
                    onChange={setConfig}
                    design={design}
                    onDesignChange={setDesign}
                  />
                )}
              {/* Templates are folders in the workspace, not something this
                  page creates: the calibrator calibrates. */}
              {!templateName &&
                (catalogState === "loading" ? (
                  <p role="status">Loading templates...</p>
                ) : catalogState === "error" ? (
                  <p role="alert">Could not load templates. Reload to try again.</p>
                ) : (
                  <p>No templates yet -- add a folder of photos under mockup-templates/.</p>
                ))}
            </>
          )}
        </div>
      </div>
    </div>
  );
}

import { afterEach, expect, it, vi } from "vitest";
import type { Middleware } from "openapi-fetch";
import { api } from "./client";
import { getTemplateConfig } from "./calibrator";
import { getMaskHistory, getPreparation } from "./preparation";
import { READY, SINGLE } from "../test/marigold";

// Node requires absolute Request URLs; browsers resolve the app's relative paths.
vi.hoisted(() => {
  class BrowserRequest extends Request {
    constructor(input: RequestInfo | URL, init?: RequestInit) {
      super(typeof input === "string" ? new URL(input, "http://localhost") : input, init);
    }
  }
  vi.stubGlobal("Request", BrowserRequest);
});
const requests: Request[] = [];
const transport: Middleware = {
  onRequest({ request }) {
    requests.push(request);
    const body = request.url.endsWith("/config")
      ? SINGLE
      : request.url.endsWith("/preparation")
        ? READY
        : { checksum: "mask", undo_count: 0, strokes: [] };
    return Response.json(body, {
      headers: {
        ETag: '"current"',
        "Last-Modified": "Wed, 17 Sep 2026 18:30:00 GMT",
      },
    });
  },
};
afterEach(() => {
  api.eject(transport);
  requests.length = 0;
  vi.unstubAllGlobals();
});

it("bypasses previously cached calibration documents and mutable preparation state", async () => {
  api.use(transport);
  const name = "tee";
  // openapi-fetch's generated paths are relative in production. Its transport
  // hook receives the Request before it reaches the browser's HTTP cache.
  await getTemplateConfig(name);
  await getPreparation(name);
  await getMaskHistory(name, null);
  await getMaskHistory(name, "front");
  expect(requests).toHaveLength(4);
  expect(requests.every((request) => request.cache === "no-store")).toBe(true);
});

import type { components } from "./schema";
import { api } from "./client";
import { openEventStream, type EventStreamOptions } from "./sse";
export type Preparation = components["schemas"]["PreparationResponse"];
export type PreparationJob = components["schemas"]["PreparationJobResponse"];
export type MaskEdit = components["schemas"]["MaskEdit"];
export type MaskOperation = MaskEdit["operations"][number];
export type Runtime = components["schemas"]["MarigoldRuntimeResponse"];
export async function getPreparation(name: string, signal?: AbortSignal): Promise<Preparation> {
  const { data, error } = await api.GET("/api/templates/{name}/preparation", {
    cache: "no-store",
    params: { path: { name } },
    ...(signal ? { signal } : {}),
  });
  if (error || !data) throw new Error("Could not read template map status. Try again.");
  return data;
}
export async function getRuntime(): Promise<Runtime> {
  const { data, error } = await api.GET("/api/marigold/runtime");
  if (error || !data) throw new Error("Could not check the Marigold runtime.");
  return data;
}
export async function listPreparationJobs(): Promise<PreparationJob[]> {
  const { data, error } = await api.GET("/api/preparation/jobs");
  if (error || !data) throw new Error("Could not read the preparation queue.");
  return data;
}
export async function prepareTemplate(
  body: components["schemas"]["CreatePreparationRequest"],
): Promise<PreparationJob> {
  const { data, error } = await api.POST("/api/preparation/jobs", { body });
  if (error || !data) {
    const detail: unknown = error?.detail;
    const message =
      typeof detail === "string"
        ? detail
        : detail &&
            typeof detail === "object" &&
            "message" in detail &&
            typeof detail.message === "string"
          ? detail.message
          : "Preparation could not start. Try again.";
    throw new Error(message);
  }
  return data;
}
export async function cancelPreparation(identity: string): Promise<PreparationJob> {
  const { data, error } = await api.DELETE("/api/preparation/jobs/{identity}", {
    params: { path: { identity } },
  });
  if (error || !data) throw new Error("Could not cancel preparation. Try again.");
  return data;
}
export type PreparationEvent =
  | components["schemas"]["Event"]
  | PreparationJob
  | components["schemas"]["PreparationResyncResponse"];
export function followPreparation(id: string, options: EventStreamOptions<PreparationEvent>) {
  return openEventStream(`/api/preparation/jobs/${encodeURIComponent(id)}/events`, options);
}
export function maskUrl(
  name: string,
  placementId: string | null,
  automatic = false,
  revision = "",
) {
  const placement = placementId === null ? "" : `/placements/${encodeURIComponent(placementId)}`;
  return `/api/templates/${encodeURIComponent(name)}${placement}/mask?source=${automatic ? "automatic" : "edited"}&revision=${encodeURIComponent(revision)}`;
}
export type MaskHistory = components["schemas"]["MaskHistoryResponse"];
export async function getMaskHistory(
  name: string,
  placementId: string | null,
): Promise<MaskHistory> {
  const result =
    placementId === null
      ? await api.GET("/api/templates/{name}/mask-history", {
          cache: "no-store",
          params: { path: { name } },
        })
      : await api.GET("/api/templates/{name}/placements/{placement_id}/mask-history", {
          cache: "no-store",
          params: { path: { name, placement_id: placementId } },
        });
  if (result.error || !result.data)
    throw new Error("Could not read brush history. Saved masks remain available.");
  // openapi-fetch widens nested coordinate tuples. The response contract validates pairs.
  return result.data as unknown as MaskHistory;
}

/**
 * A typed `text/event-stream` reader over `fetch`, shared by the two run
 * resources: plan/apply runs (`pages/deploy/runStream.ts`) and AI runs
 * (`api/aiRuns.ts`). Both servers write the same frame,
 * `id: <n>\nevent: <type>\ndata: <json>\n\n`, and both end the stream after
 * the run's last event.
 *
 * **Why a hand-rolled `fetch` reader and not the browser's `EventSource`.**
 * `EventSource`'s constructor takes a URL and nothing else -- there is no way
 * to set a request header on its first connection, only on the *automatic*
 * reconnect after a drop, which the UA does on its own using whatever `id` it
 * last saw. Reattaching needs the header on the *first* request this page
 * ever makes to a run it did not start (a reload, or *View progress*), and
 * the servers read exactly that header (`Last-Event-ID`). `EventSource`
 * cannot ask for it; a plain `fetch` with a header can.
 *
 * No reconnect-on-drop logic is implemented here -- a run belongs to the
 * server regardless of who is watching, so a dropped connection loses
 * nothing a page reload (which reattaches) does not already recover.
 */

export interface EventStreamOptions<Event> {
  /** The last event id already known -- `undefined` asks the server for
   * everything, which is what a caller that has seen nothing wants. */
  lastEventId?: number | undefined;
  onEvent: (event: Event) => void;
  /** The stream closed because the run reached its last event -- there is
   * nothing more to read. */
  onDone?: () => void;
  /** The request itself failed (network, or a non-200 status) -- distinct
   * from `onDone`, which means the run finished normally. */
  onError?: (error: unknown) => void;
}

export interface EventStreamHandle {
  /** Stops reading and aborts the underlying request. Safe to call more than
   * once, and safe to call after the stream has already finished on its
   * own. */
  close: () => void;
}

function parseFrame<Event>(block: string): Event | null {
  let data: string | null = null;
  for (const line of block.split("\n")) {
    if (line.startsWith("data: ")) data = line.slice("data: ".length);
  }
  if (data === null) return null;
  return JSON.parse(data) as Event;
}

export function openEventStream<Event>(
  url: string,
  options: EventStreamOptions<Event>,
): EventStreamHandle {
  const controller = new AbortController();
  const headers =
    options.lastEventId !== undefined ? { "Last-Event-ID": String(options.lastEventId) } : {};

  async function read(): Promise<void> {
    let response: Response;
    try {
      response = await fetch(url, { headers, signal: controller.signal });
    } catch (error) {
      if (!controller.signal.aborted) options.onError?.(error);
      return;
    }
    if (!response.ok || response.body === null) {
      if (!controller.signal.aborted)
        options.onError?.(new Error(`event stream: HTTP ${response.status}`));
      return;
    }

    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let buffer = "";
    try {
      for (;;) {
        const { value, done } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        const frames = buffer.split("\n\n");
        // The last element is either "" (the buffer ended exactly on a frame
        // boundary) or a partial frame still waiting on more bytes -- either
        // way it is not parsed yet, only kept for the next chunk.
        buffer = frames.pop() ?? "";
        for (const block of frames) {
          const event = parseFrame<Event>(block);
          if (event !== null) options.onEvent(event);
        }
      }
      options.onDone?.();
    } catch (error) {
      if (!controller.signal.aborted) options.onError?.(error);
    }
  }

  void read();

  return {
    close: () => controller.abort(),
  };
}

import { fireEvent, render, screen, waitFor } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import * as calibrator from "../api/calibrator";
import type { ColourReportRow } from "../types";
import { KindPicker } from "./KindPicker";

const CLEAN: ColourReportRow[] = [
  { filename: "sand.png", colour: "sand", clean: true },
  { filename: "black.png", colour: "black", clean: true },
];

const MESSY: ColourReportRow[] = [
  ...CLEAN,
  { filename: "Heather Grey.png", colour: "heather-grey", clean: false },
];

afterEach(() => vi.restoreAllMocks());
beforeEach(() => {
  vi.spyOn(calibrator, "getColourReport").mockResolvedValue(CLEAN);
});

function renderPicker(over: Partial<Parameters<typeof KindPicker>[0]> = {}) {
  const onAssigned = vi.fn();
  render(<KindPicker templateName="boxy-tee" onAssigned={onAssigned} {...over} />);
  return { onAssigned };
}

const ONE_PHOTO: ColourReportRow[] = [{ filename: "photo.png", colour: "photo", clean: true }];

describe("the default kind follows the photo count", () => {
  it("defaults to colour matrix when there are several photos", async () => {
    renderPicker();
    await waitFor(() => expect(screen.getByRole("radio", { name: /Colour Matrix/ })).toBeChecked());
  });

  it("defaults to single, and disables colour matrix, for one photo", async () => {
    /* "One photo per colour" over a single file is a matrix of one -- which is
     * what `single` already is. Worse, accepting it names the colour after the
     * filename, so `photo.png` became a garment colour called "photo". */
    vi.spyOn(calibrator, "getColourReport").mockResolvedValue(ONE_PHOTO);
    renderPicker();

    await waitFor(() => expect(screen.getByRole("radio", { name: /Single/ })).toBeChecked());
    expect(screen.getByRole("radio", { name: /Colour Matrix/ })).toBeDisabled();
    expect(screen.getByText("needs more than one photo")).toBeInTheDocument();
  });

  it("multiple stays available for one photo", async () => {
    // A chart is one photo with several garments in it -- exactly the
    // single-photo case, so this must not be disabled alongside colour matrix.
    vi.spyOn(calibrator, "getColourReport").mockResolvedValue(ONE_PHOTO);
    renderPicker();
    await waitFor(() => expect(screen.getByRole("radio", { name: /Single/ })).toBeChecked());
    expect(screen.getByRole("radio", { name: /Multiple/ })).toBeEnabled();
  });

  it("assigns single for a one-photo template without anyone touching a radio", async () => {
    vi.spyOn(calibrator, "getColourReport").mockResolvedValue(ONE_PHOTO);
    const assignSpy = vi.spyOn(calibrator, "assignKind").mockResolvedValue({
      kind: "single",
      colour: null,
      bounding_box: [
        { x: 0, y: 0 },
        { x: 1, y: 0 },
        { x: 1, y: 1 },
        { x: 0, y: 1 },
      ],
      renderer: {
        type: "photo-warp",
        config: {
          displace: { enabled: false, strength: 0 },
          shade: { enabled: true, opacity: 0.6, blend: "soft-light" },
        },
      },
    });
    renderPicker();
    await waitFor(() => expect(screen.getByRole("radio", { name: /Single/ })).toBeChecked());

    fireEvent.click(screen.getByRole("button", { name: /Start calibrating/ }));
    await waitFor(() => expect(assignSpy).toHaveBeenCalledWith("boxy-tee", "single"));
  });

  it("a colour-matrix pick made before the report lands falls back to single", async () => {
    /* The report is fetched, so the count arrives after the first paint. A
     * choice that is no longer available has to give way rather than be
     * submitted. */
    let resolveReport: (rows: ColourReportRow[]) => void = () => {};
    vi.spyOn(calibrator, "getColourReport").mockReturnValue(
      new Promise<ColourReportRow[]>((resolve) => {
        resolveReport = resolve;
      }),
    );
    renderPicker();

    fireEvent.click(screen.getByRole("radio", { name: /Colour Matrix/ }));
    expect(screen.getByRole("radio", { name: /Colour Matrix/ })).toBeChecked();

    resolveReport(ONE_PHOTO);
    await waitFor(() => expect(screen.getByRole("radio", { name: /Single/ })).toBeChecked());
  });
});

