import { maskDraft } from "./maskDraft";
import { useEffect, useEffectEvent, useId, useRef, useState } from "react";
import type { MaskOperation } from "../api/preparation";
import type { BoundingBox } from "../types";
import { artworkTransform } from "./artworkTransform";

export type Stroke = Extract<MaskOperation, { type: "stroke" }>;
/** Mask pixels and strokes use original photo coordinates. The separate SVG
 * input layer captures a complete gesture so moving a placement cannot move
 * a saved exclusion and Undo never removes only part of a stroke. */
export function PlacementOverlay({
  box,
  designUrl,
  maskUrl,
  automaticMaskUrl,
  undoBases,
  operations,
  space,
  editing,
  mode,
  diameter,
  onStroke,
  showArtwork = true,
}: {
  showArtwork?: boolean;
  box: BoundingBox;
  designUrl: string;
  maskUrl: string | null;
  automaticMaskUrl: string | null;
  undoBases: string[];
  operations: MaskOperation[];
  space: [number, number];
  editing: boolean;
  mode: "mask" | "unmask";
  diameter: number;
  onStroke: (stroke: Stroke) => void;
}) {
  const id = useId().replaceAll(":", "");
  const [stroke, setStroke] = useState<Stroke | null>(null);
  const current = useRef<Stroke | null>(null);
  const cursor = useRef<SVGGElement>(null);
  function hideCursor() {
    cursor.current?.setAttribute("visibility", "hidden");
  }
  const { automatic, strokes, undoSaved } = maskDraft(operations);
  const base = automatic
    ? automaticMaskUrl
    : undoSaved
      ? undoBases[undoBases.length - undoSaved]
        ? `data:image/png;base64,${undoBases[undoBases.length - undoSaved]}`
        : maskUrl
      : maskUrl;
  function point(event: React.PointerEvent<SVGRectElement>): [number, number] | null {
    const svg = event.currentTarget.ownerSVGElement;
    const ctm = svg?.getScreenCTM();
    if (!svg || !ctm) return null;
    const p = svg.createSVGPoint();
    p.x = event.clientX;
    p.y = event.clientY;
    const result = p.matrixTransform(ctm.inverse());
    if (result.x >= 0 && result.x < space[0] && result.y >= 0 && result.y < space[1]) {
      cursor.current?.setAttribute("transform", `translate(${result.x} ${result.y})`);
      cursor.current?.setAttribute("visibility", "visible");
    } else hideCursor();
    return [
      Math.max(0, Math.min(space[0] - 1, result.x)),
      Math.max(0, Math.min(space[1] - 1, result.y)),
    ];
  }
  function finish() {
    const next = current.current;
    current.current = null;
    setStroke(null);
    if (next) onStroke(next);
  }
  // Leaving mask mode commits an active gesture once, including Escape while
  // the pointer is still held. The effect event uses the latest draft callback.
  const finishGesture = useEffectEvent(finish);
  useEffect(() => {
    if (editing) return () => finishGesture();
  }, [editing]);
  const all = stroke ? [...strokes, stroke] : strokes;
  const paths = all.map((s, i) => (
    <path
      key={i}
      d={
        s.points.map((p, j) => `${j ? "L" : "M"}${p[0]},${p[1]}`).join(" ") +
        (s.points.length === 1 ? ` l0.001,0` : "")
      }
      stroke={s.mode === "mask" ? "black" : "white"}
      strokeWidth={s.diameter_px}
      strokeLinecap="round"
      strokeLinejoin="round"
      fill="none"
    />
  ));
  return (
    <g>
      <defs>
        <mask
          id={`cloth-${id}`}
          maskUnits="userSpaceOnUse"
          x={0}
          y={0}
          width={space[0]}
          height={space[1]}
        >
          <rect width={space[0]} height={space[1]} fill="white" />
          {base && <image href={base} width={space[0]} height={space[1]} />} {paths}
        </mask>
        <filter id={`invert-${id}`}>
          <feComponentTransfer>
            <feFuncR type="table" tableValues="1 0" />
            <feFuncG type="table" tableValues="1 0" />
            <feFuncB type="table" tableValues="1 0" />
          </feComponentTransfer>
        </filter>
        <mask
          id={`hidden-${id}`}
          maskUnits="userSpaceOnUse"
          x={0}
          y={0}
          width={space[0]}
          height={space[1]}
        >
          <g filter={`url(#invert-${id})`}>
            <rect width={space[0]} height={space[1]} fill="white" />
            {base && <image href={base} width={space[0]} height={space[1]} />} {paths}
          </g>
        </mask>
      </defs>
      {showArtwork && (
        <g mask={`url(#cloth-${id})`} pointerEvents="none">
          <foreignObject
            x={0}
            y={0}
            width={space[0]}
            height={space[1]}
            style={{ overflow: "visible" }}
          >
            <img
              src={designUrl}
              alt=""
              style={{
                width: 1,
                height: 1,
                position: "absolute",
                transformOrigin: "0 0",
                transform: artworkTransform(box),
                pointerEvents: "none",
              }}
            />
          </foreignObject>
        </g>
      )}
      {editing && (
        <>
          <rect
            width={space[0]}
            height={space[1]}
            fill="#e43737"
            opacity={0.32}
            mask={`url(#hidden-${id})`}
            pointerEvents="none"
          />
          <rect
            aria-label="Mask drawing area"
            width={space[0]}
            height={space[1]}
            fill="transparent"
            style={{ touchAction: "none", cursor: "none" }}
            onPointerEnter={point}
            onPointerLeave={hideCursor}
            onPointerDown={(event) => {
              if (event.button !== 0) return;
              event.stopPropagation();
              const p = point(event);
              if (!p) return;
              event.currentTarget.setPointerCapture(event.pointerId);
              const next: Stroke = { type: "stroke", mode, diameter_px: diameter, points: [p] };
              current.current = next;
              setStroke(next);
            }}
            onPointerMove={(event) => {
              const p = point(event);
              if (!current.current) return;
              event.stopPropagation();
              if (p) {
                const next = { ...current.current, points: [...current.current.points, p] };
                current.current = next;
                setStroke(next);
              }
            }}
            onPointerUp={(event) => {
              event.stopPropagation();
              finish();
            }}
            onPointerCancel={() => {
              finish();
              hideCursor();
            }}
            onLostPointerCapture={finish}
          />
          <g
            ref={cursor}
            aria-label="Brush footprint"
            visibility="hidden"
            pointerEvents="none"
            fill="none"
          >
            {/* SVG photo units match the stroke, including resize and DPR.
                  Non-scaling outlines stay legible on light and dark photos. */}
            <circle
              cx={0}
              cy={0}
              r={(stroke?.diameter_px ?? diameter) / 2}
              stroke="black"
              strokeWidth={3}
              vectorEffect="non-scaling-stroke"
            />
            <circle
              cx={0}
              cy={0}
              r={(stroke?.diameter_px ?? diameter) / 2}
              stroke="white"
              strokeWidth={1}
              vectorEffect="non-scaling-stroke"
            />
          </g>
        </>
      )}
    </g>
  );
}

import { useEffect, useState } from "react";
import { CheckCircleIcon } from "@phosphor-icons/react/dist/csr/CheckCircle";
import { ClockIcon } from "@phosphor-icons/react/dist/csr/Clock";
import type { PreparationJob } from "../api/preparation";
const stepLabels: Record<string, string> = {
  loading_models: "Loading models",
  normals: "Estimating surface direction",
  lighting: "Estimating garment lighting",
  depth: "Estimating depth",
  cpu_queued: "Waiting to build maps",
  building_maps: "Building maps",
  publication: "Publishing maps",
};
export function PreparationProgress({ job }: { job: PreparationJob }) {
  const [ticks, setTicks] = useState(0);
  const [base, setBase] = useState({ elapsed: job.elapsed, ticks });
  if (base.elapsed !== job.elapsed) setBase({ elapsed: job.elapsed, ticks });
  useEffect(() => {
    if (job.phase !== "running" && job.phase !== "cancelling") return;
    const timer = setInterval(() => setTicks((n) => n + 1), 1000);
    return () => clearInterval(timer);
  }, [job.phase]);
  const step = job.step.toLowerCase();
  const active = step.includes("normal")
    ? 0
    : step.includes("lighting")
      ? 1
      : step.includes("depth")
        ? 2
        : step.includes("build") || step.includes("bake")
          ? 3
          : -1;
  return (
    <>
      <p className="mg-row">
        <strong>
          {job.phase === "queued"
            ? `Waiting in queue${job.queue_position ? ` · ${job.queue_position}` : ""}`
            : (stepLabels[job.step] ?? job.step.replaceAll("_", " "))}
        </strong>
        <span>{Math.floor(job.elapsed + ticks - base.ticks)}s</span>
      </p>
      <p className="mg-help">
        {job.placements_completed} / {job.placements_total} placements
      </p>
      <ol className="mg-steps">
        {["Surface direction", "Garment lighting", "Depth", "Build maps"].map((label, i) => (
          <li
            key={label}
            className={i === active ? "mg-step--active" : i < active ? "mg-step--done" : ""}
          >
            {i < active ? <CheckCircleIcon /> : <ClockIcon />}
            {label}
          </li>
        ))}
      </ol>
    </>
  );
}

import { useCallback, useEffect, useRef, useState } from "react";
import { renderPreview } from "../api/calibrator";
import { Lightbox } from "./Lightbox";

/**
 * The Preview tab, for every template kind.
 *
 * The split it completes: the Calibrate tab renders *small* so that dragging
 * is instant, and this one renders at the photo's real size so there is
 * somewhere to actually judge the result. Both go through the same server-side
 * pipeline `apply` uses -- what changes between them is only how many pixels
 * the server is asked to spend.
 *
 * **Opening the tab renders; changing a box does not.** A full-size render of
 * a twelve-colour set is a lot of work, and it used to be kicked off by any
 * change to the config at all -- so nudging a box by a pixel re-rendered the
 * lot. Worse, the tiles could quietly become a picture of an older box than
 * the one on screen, which is the one thing a view you approve from must never
 * do. So the first look renders, and after that a changed config turns
 * Re-render red rather than silently re-running.
 *
 * The panel stays mounted while the Calibrate tab is in front, hidden rather
 * than unmounted. Otherwise every flick between tabs would throw the renders
 * away and start the set again -- and "there is none, so render" would fire on
 * a set that had just been rendered.
 *
 * Renders **sequentially**. Firing every colour at once does not make the set
 * arrive sooner -- the server runs the real pipeline for each -- it only makes
 * the *first* one arrive later, and buries the progress count.
 */

type PreviewBody = Parameters<typeof renderPreview>[1];

export interface PreviewJob {
  /** Stable across renders; also the lightbox's key. A colour name for a
   * colour matrix, the template name for the kinds with one output. */
  id: string;
  label: string;
  body: PreviewBody;
}

interface Props {
  fullQuality?: boolean;
  reference?: string;
  blocked?: string | null;
  prepareLabel?: string;
  onPrepare?: () => void;
  identity?: string;
  templateName: string;
  jobs: PreviewJob[];
  design: string;
  /** Whether this tab is the one in front. Mounted either way -- see the note
   * about tab flicks above -- so this both hides the panel and is what a first
   * look keys off. */
  active: boolean;
  /** Colour-matrix's "Approve & mark calibrated", which is a save. Omitted by
   * the kinds whose only save is the header's -- there is nothing extra to
   * approve when the tab shows one image. */
  onApprove?: () => void;
}

/** What one press of Render asked for. Set once and never mutated, so the
 * render loop's dependency on it is honest: a later edit produces a *new*
 * request, it does not redirect the one in flight. */
interface Request {
  key: string;
  templateName: string;
  design: string;
  jobs: PreviewJob[];
}

/** What has come back for a request. Stamped with the request's key so a
 * count from this run can never appear beside tiles from the last one. */
interface Result {
  key: string;
  rendered: Record<string, string>;
  done: number;
  failed: number;
}

function requestKey(templateName: string, design: string, jobs: PreviewJob[]): string {
  return `${templateName}|${design}|${JSON.stringify(jobs)}`;
}

export function PreviewPanel({
  fullQuality,
  reference,
  templateName,
  jobs,
  design,
  active,
  onApprove,
  blocked = null,
  prepareLabel = "Prepare template",
  onPrepare,
  identity = "",
}: Props) {
  const key = requestKey(templateName, design, jobs) + identity;
  const [request, setRequest] = useState<Request | null>(null);
  const [result, setResult] = useState<Result | null>(null);
  const [open, setOpen] = useState<string | null>(null);
  const [actualSize, setActualSize] = useState(false);
  const urlsRef = useRef<string[]>([]);

  // Every blob this panel has made. Revoked wholesale when a run is replaced
  // or the tab goes away -- never per tile, which would pull an image out from
  // under one still on screen.
  const revokeAll = useCallback(() => {
    for (const url of urlsRef.current) URL.revokeObjectURL(url);
    urlsRef.current = [];
  }, []);
  useEffect(() => revokeAll, [revokeAll]);

  const start = useCallback(() => {
    revokeAll();
    setOpen(null);
    setResult({ key, rendered: {}, done: 0, failed: 0 });
    setRequest({ key, templateName, design, jobs });
  }, [key, templateName, design, jobs, revokeAll]);

  // The first look renders itself. Only ever the *first*: once a request
  // exists this is inert, so returning to the tab shows what was rendered
  // rather than spending the set again.
  //
  // Adjusted during render rather than from an effect. React re-renders
  // immediately and throws the intermediate output away, so the panel never
  // paints a "nothing yet" state it is about to replace -- where an effect
  // would both paint it and cost the cascading render that
  // `react-hooks/set-state-in-effect` exists to prevent. Nothing to revoke
  // here either: `request` only ever goes from null to set, so there cannot
  // be an earlier run's blobs to clean up. That is why this is not `start()`.
  if (active && request === null && !blocked) {
    setRequest({ key, templateName, design, jobs });
    setResult({ key, rendered: {}, done: 0, failed: 0 });
  }

  useEffect(() => {
    if (request === null || request.key !== key || blocked) return;
    let cancelled = false;

    void (async () => {
      for (const job of request.jobs) {
        if (cancelled) return;
        try {
          const url = await renderPreview(request.templateName, job.body, request.design, "full");
          if (cancelled) {
            URL.revokeObjectURL(url);
            return;
          }
          urlsRef.current.push(url);
          setResult((current) =>
            current === null || current.key !== request.key
              ? current
              : {
                  ...current,
                  rendered: { ...current.rendered, [job.id]: url },
                  done: current.done + 1,
                },
          );
        } catch {
          // One unreadable photo costs you that tile, not the whole tab.
          if (cancelled) return;
          setResult((current) =>
            current === null || current.key !== request.key
              ? current
              : { ...current, failed: current.failed + 1 },
          );
        }
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [request, key, blocked]);

  const rendered = result?.key === request?.key ? (result?.rendered ?? {}) : {};
  const done = result?.done ?? 0;
  const failed = result?.failed ?? 0;
  // A run for an older config. Its images are still the last full-size renders
  // there are, and worth looking at -- they are just no longer of what the
  // editor is holding, and saying so is this banner's whole job.
  const stale = request !== null && request.key !== key;
  const complete = request !== null && done + failed >= request.jobs.length;
  // Everything asked for has come back, and it is a picture of what the editor
  // currently holds -- the only state in which approving means anything.
  const approvable = complete && !stale && failed === 0;

  const items = (request?.jobs ?? [])
    .map((job) => ({ id: job.id, label: job.label, url: rendered[job.id] }))
    .filter((item): item is { id: string; label: string; url: string } => Boolean(item.url));
  const openIndex = open === null ? -1 : items.findIndex((item) => item.id === open);

  return (
    <section
      className={jobs.length === 1 ? "preview-grid preview-grid--single" : "preview-grid"}
      hidden={!active}
    >
      {blocked && (
        <div className="mg-empty-preview">
          <p role="status">{blocked}</p>
          {onPrepare && (
            <button type="button" className="btn btn-primary" onClick={onPrepare}>
              {prepareLabel}
            </button>
          )}
        </div>
      )}
      <div className="preview-grid__head">
        {request === null ? (
          <span className="preview-grid__status">
            {jobs.length === 1 ? "not rendered yet" : `${jobs.length} colours, not rendered yet`}
          </span>
        ) : (
          <span className="preview-grid__count">{`${done} / ${request.jobs.length}`}</span>
        )}
        {request !== null && !complete && !stale && !blocked && (
          <span className="preview-grid__status">rendering at full size…</span>
        )}
        {fullQuality && complete && <span className="preview-grid__status">Full quality</span>}
        {failed > 0 && (
          <span className="preview-grid__failed">
            {`${failed} ${failed === 1 ? "preview" : "previews"} failed to render`}
          </span>
        )}
        {/* Which button is the loud one follows what there is to do. A config
            that has moved on since the render makes Re-render *red*: that is
            the one state where what you are looking at is not what you would
            be approving, and it is worth more than a line of prose beside the
            progress count, which is what it replaced. `.btn` alone is
            transparent in this design system, so the quiet one is explicitly
            `btn-secondary` rather than bare. */}
        <div className="preview-grid__actions">
          <button
            type="button"
            className={
              stale ? "btn btn-danger" : approvable ? "btn btn-secondary" : "btn btn-primary"
            }
            disabled={!!blocked}
            onClick={start}
          >
            {request === null ? "Render preview" : "Re-render"}
          </button>
          {onApprove && (
            <button
              type="button"
              className={approvable ? "btn btn-primary" : "btn btn-secondary"}
              onClick={onApprove}
            >
              Approve &amp; mark calibrated
            </button>
          )}
        </div>
      </div>

      {request === null ? (
        <p className="preview-grid__empty">
          Full-size renders, through the same pipeline <code>apply</code> uses — a few seconds each,
          which is why they are asked for rather than assumed. Click one to see it large.
        </p>
      ) : (
        <div className="preview-grid__tiles">
          {request.jobs.map((job) => {
            const url = rendered[job.id];
            return (
              <figure key={job.id} className="gallery__item preview-grid__tile">
                {url ? (
                  <button
                    type="button"
                    className="preview-grid__open"
                    onClick={() => setOpen(job.id)}
                    title="Open at full size"
                  >
                    <img src={url} alt={job.label} />
                  </button>
                ) : (
                  <div className="gallery__placeholder" />
                )}
                <figcaption>{job.label}</figcaption>
              </figure>
            );
          })}
        </div>
      )}

      {fullQuality && request !== null && (
        <>
          <p className="mg-help">Full-size renders. Click an image to see it large.</p>
          {reference && <p className="mg-help">{reference}</p>}
        </>
      )}

      {openIndex >= 0 && (
        <Lightbox
          items={items}
          index={openIndex}
          actualSize={actualSize}
          onActualSizeChange={setActualSize}
          onIndexChange={(next) => setOpen(items[next]?.id ?? null)}
          onClose={() => setOpen(null)}
        />
      )}
    </section>
  );
}

import { fireEvent, render, screen } from "@testing-library/react";
import { useState } from "react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { must } from "../test/helpers";
import type { BoundingBox } from "../types";
import { QuadEditor } from "./QuadEditor";

/** The template photo's true pixel size. `loadImage()` stubs the *displayed*
 * image at the same size, so every geometric expectation below reads the same
 * as it did when the overlay measured the image instead of being told. */
const SPACE: [number, number] = [400, 200];

const BOX_A: BoundingBox = [
  { x: 0, y: 0 },
  { x: 100, y: 0 },
  { x: 100, y: 100 },
  { x: 0, y: 100 },
];
const BOX_B: BoundingBox = [
  { x: 200, y: 0 },
  { x: 300, y: 0 },
  { x: 300, y: 100 },
  { x: 200, y: 100 },
];

function loadImage() {
  const img = screen.getByAltText("Rendered preview");
  Object.defineProperty(img, "naturalWidth", { value: 400, configurable: true });
  Object.defineProperty(img, "naturalHeight", { value: 200, configurable: true });
  fireEvent.load(img);
}

describe("QuadEditor", () => {
  it("renders no overlay until the image has loaded", () => {
    const { container } = render(
