    expect(must(container.querySelector(".quad-editor__overlay")).getAttribute("viewBox")).toBe(
      "0 0 4000 5000",
    );
  });

  it("renders one box group per box, once loaded", () => {
    const { container } = render(
      <QuadEditor
        imageUrl="preview.png"
        space={SPACE}
        boxes={[BOX_A, BOX_B]}
        selectedIndex={0}
        onSelect={vi.fn()}
        onChangeBox={vi.fn()}
      />,
    );
