describe("resizing a box from a corner", () => {
  let restore = () => {};
  beforeEach(() => {
    restore = stubSvgGeometry();
  });
  afterEach(() => restore());

  /** BOX_A is the unit square scaled to 100 -- corners at (0,0), (100,0),
   * (100,100), (0,100) -- so a factor of `f` about the opposite corner lands
   * on numbers you can read straight off the assertion. */
  function renderResizable(onChangeBox = vi.fn()) {
    const { container } = render(
      <QuadEditor
        imageUrl="preview.png"
        space={SPACE}
        boxes={[BOX_A]}
        selectedIndex={0}
        onSelect={vi.fn()}
        onChangeBox={onChangeBox}
      />,
    );
    loadImage();
    return container;
  }

  const overlay = (container: HTMLElement) =>
    must(container.querySelector(".quad-editor__overlay"));

  /** Grabs the bottom-right handle, whose opposite corner is the origin. */
  const grabBottomRight = (container: HTMLElement) =>
    fireEvent.pointerDown(must(container.querySelectorAll(".quad-editor__handle")[2]), {
      button: 0,
      clientX: 100,
      clientY: 100,
      pointerId: 1,
    });

  it("plain-drags one corner and leaves the other three alone", () => {
    const onChangeBox = vi.fn();
    const container = renderResizable(onChangeBox);
    grabBottomRight(container);
    fireEvent.pointerMove(overlay(container), { clientX: 160, clientY: 40 });

    expect(onChangeBox).toHaveBeenLastCalledWith(0, [
      { x: 0, y: 0 },
      { x: 100, y: 0 },
      { x: 160, y: 40 },
      { x: 0, y: 100 },
    ]);
  });

  it("shift-drag scales the whole box about the opposite corner", () => {
    const onChangeBox = vi.fn();
    const container = renderResizable(onChangeBox);
    grabBottomRight(container);
    // Straight out along the diagonal to (200, 200): twice as far from the
    // anchor at the origin, so every corner doubles.
    fireEvent.pointerMove(overlay(container), { clientX: 200, clientY: 200, shiftKey: true });

    expect(onChangeBox).toHaveBeenLastCalledWith(0, [
      { x: 0, y: 0 },
      { x: 200, y: 0 },
      { x: 200, y: 200 },
      { x: 0, y: 200 },
    ]);
  });

  it("alt-drag scales about the box's own centre", () => {
    const onChangeBox = vi.fn();
    const container = renderResizable(onChangeBox);
    grabBottomRight(container);
    // The centre is (50,50) and the grabbed corner is 50 away on each axis;
    // dragging to (150,150) doubles that distance, so the box doubles around
    // the centre and its top-left goes negative.
    fireEvent.pointerMove(overlay(container), { clientX: 150, clientY: 150, altKey: true });

    expect(onChangeBox).toHaveBeenLastCalledWith(0, [
      { x: -50, y: -50 },
      { x: 150, y: -50 },
      { x: 150, y: 150 },
      { x: -50, y: 150 },
    ]);
  });

  it("scales from the box as it was when the gesture started, not compounding", () => {
    const onChangeBox = vi.fn();
    // A parent that applies each change, as the calibrator does, so the
    // second move sees the already-doubled box in props.
    function Controlled() {
      const [box, setBox] = useState(BOX_A);
      return (
        <QuadEditor
          imageUrl="preview.png"
          space={SPACE}
          boxes={[box]}
          selectedIndex={0}
          onSelect={vi.fn()}
          onChangeBox={(index, next) => {
            onChangeBox(index, next);
            setBox(next);
          }}
        />
      );
    }
    const { container } = render(<Controlled />);
    loadImage();
    grabBottomRight(container);
    fireEvent.pointerMove(overlay(container), { clientX: 200, clientY: 200, shiftKey: true });
    fireEvent.pointerMove(overlay(container), { clientX: 200, clientY: 200, shiftKey: true });

    // Same pointer position twice means the same doubled box twice. A
    // projection about a fixed anchor happens to land in the same place from
    // the live box too, so the sliding case above is the one that catches a
    // gesture reading live props; this one pins the callback sequence.
    const doubled = [
      { x: 0, y: 0 },
      { x: 200, y: 0 },
      { x: 200, y: 200 },
      { x: 0, y: 200 },
    ];
    expect(onChangeBox.mock.calls).toEqual([
      [0, doubled],
      [0, doubled],
    ]);
  });
});

import { PreparationProgress } from "./PreparationProgress";
import { preparationLabel, marigoldMapsReady } from "./preparationLabel";
import { useEffect, useState } from "react";
import type { ReactNode } from "react";
import { getRuntime, type Preparation, type Runtime } from "../api/preparation";
import type { Renderer } from "../types";
export function RendererPanel({
  settings,
  renderer,
  onRendererChange,
  preparation,
  onPrepare,
  onCancel,
  pending,
  error,
}: {
  settings: (runtime: Runtime | null) => ReactNode;
  renderer: Renderer;
  onRendererChange: (renderer: Renderer["type"]) => void;
  preparation: Preparation | null;
  onPrepare: (action: "prepare" | "prepare_again" | "retry", resetMasksForPhoto?: boolean) => void;
  onCancel: () => void;
  pending: boolean;
  error: string;
}) {
  const [runtime, setRuntime] = useState<Runtime | null>(null);
  const [runtimeError, setRuntimeError] = useState("");
  useEffect(() => {
    if (renderer.type !== "marigold") return;
    let active = true;
    getRuntime()
      .then((value) => {
        if (active) setRuntime(value);
      })
      .catch((e) => {
        if (active) setRuntimeError(e instanceof Error ? e.message : "Could not check runtime");
      });
    return () => {
      active = false;
    };
  }, [renderer.type]);
  const job = preparation?.active_job;
  // A CPU rebuild reuses saved predictions and takes seconds, so it gets a
  // spinner where the stages go -- not the GPU run's steps, timer and Cancel.
  const rebuilding = job?.kind === "rebuild";
  const label = pending ? "Preparing" : preparationLabel(preparation);
  const recovery = preparation?.maps.reason === "photo_changed";
  const action =
    preparation?.latest_job?.phase === "failed"
      ? "retry"
      : recovery
        ? "prepare_again"
        : marigoldMapsReady(preparation?.maps)
          ? "prepare_again"
          : "prepare";
  return (
    <section className="realism mg-preparation">
      <h3 className="realism__heading">Renderer</h3>
      <select
        id="template-renderer"
        aria-label="Renderer"
        value={renderer.type}
        onChange={(e) => onRendererChange(e.target.value as Renderer["type"])}
      >
        <option value="photo-warp">Photo warp</option>
        <option value="marigold">Marigold</option>
      </select>
      {renderer.type === "marigold" && (
        <>
          <div className="mg-row">
            <strong>Template maps</strong>
            <span
              className={`tag mg-status${label === "Ready" ? " mg-status--ready" : label === "Failed" ? " mg-status--failed" : ""}`}
            >
              {label}
            </span>
          </div>
          {!job && preparation?.maps.state === "out_of_date" && preparation.maps.reason && (
            <p className="mg-help">{preparation.maps.message}</p>
          )}
          {rebuilding ? (
            <div className="mg-progress mg-rebuild" role="status">
              <span className="dv-spinner" aria-hidden="true" />
              Rebuilding maps
            </div>
          ) : job ? (
            <div className="mg-progress">
              <PreparationProgress job={job} />
              <button
                className="btn btn-secondary mg-wide"
                disabled={pending || job.phase === "cancelling"}
                onClick={onCancel}
              >
                {job.phase === "cancelling" ? "Cancelling…" : "Cancel preparation"}
              </button>
            </div>
          ) : (
            <button
              type="button"
              className={
                "btn mg-wide " +
                (action === "prepare_again" && !recovery ? "btn-secondary" : "btn-primary")
              }
              disabled={pending || !preparation || !runtime?.available}
              onClick={() => onPrepare(action, recovery && action !== "retry")}
            >
              {action === "retry"
                ? "Retry preparation"
                : recovery
                  ? "Reset masks and prepare"
                  : action === "prepare_again"
                    ? "Prepare again"
                    : "Prepare template"}
            </button>
          )}
          {(preparation?.latest_job?.error || error) && (
            <p role="alert" className="mg-error">
              {error || preparation?.latest_job?.error}
            </p>
          )}
          {(!runtime?.available || runtimeError) && (
            <p className="mg-help" role="status">
              {runtimeError || runtime?.problem || "Checking Marigold runtime…"}
            </p>
          )}
          {preparation &&
            marigoldMapsReady(preparation.maps) &&
            preparation.prepared_engine &&
            runtime?.engine_version &&
            preparation.prepared_engine !== runtime.engine_version && (
              <p className="mg-help">
                These maps were prepared with {preparation.prepared_engine}. They remain usable.
                Prepare again to use {runtime.engine_version}.
              </p>
            )}
          {job && !rebuilding ? (
            <p className="mg-help">You can close this browser. Preparation will continue.</p>
          ) : (
            !job && action === "retry" && <p className="mg-help">Completed steps will be reused.</p>
          )}
          {settings(runtime)}
        </>
      )}
    </section>
  );
}

import { marigoldMapsReady } from "./preparationLabel";
import type { PreparationJob } from "../api/preparation";
import { useMemo, useState } from "react";
import { templateThumbnailUrl } from "../api/calibrator";
import type { TemplateKind, TemplateSummary } from "../types";

/**
 * The template picker, as a rail rather than a dropdown (wireframe 2a).
 *
 * The point of the change is ordering: a dropdown presents 34 templates as an
 * undifferentiated list you have to already know your way around, while the
 * rail leads with the ones that are not finished and says what each is missing.
 * "Which do I open next?" stops being a question the user has to answer from
 * memory.
 *
 * Status is server-derived (`TemplateSummary.status`), so this component never
 * decides what "calibrated" means -- it only arranges what it is told.
 */

const KIND_LABELS: Record<TemplateKind, string> = {
  "colour-matrix": "Colour Matrix",
  multiple: "Multiple",
  single: "Single",
};

const VISIBLE_LIMIT = 5;
/** Rows shown per group before "+ N more". The rail is a sidebar, not the
 * page: a 34-template workspace should not push the calibrate button off
 * screen. */

type StatusFilter = "needs" | "all" | "done";

function needsCalibration(t: TemplateSummary): boolean {
  return t.renderer === "marigold"
    ? Boolean(t.maps && !marigoldMapsReady(t.maps))
    : t.status === "needs-calibration";
}

function countLabel(n: number, noun: string): string {
  return `${n} ${noun}${n === 1 ? "" : "s"}`;
}

/** What the row says under the name: what is missing, or what it holds. */
function describe(t: TemplateSummary): string {
  const kind = t.kind ? KIND_LABELS[t.kind] : null;
  if (t.renderer === "marigold") return kind ?? "Unknown";
  if (needsCalibration(t)) {
    const reason = t.status_reason ?? "not calibrated";
    return kind ? `${kind} · ${reason}` : reason;
  }
  return `${kind ?? "Unknown"} · ${countLabel(t.colours.length, "colour")}`;
}

/** The row's photo, or a blank tile when there isn't one.
 *
 * A template directory can exist before any photo is in it -- an interrupted
 * upload, or a folder made by hand -- and `/thumbnail` 404s for those. Without
 * this the browser draws its own broken-image icon, which reads as the rail
 * being broken rather than as the template being empty. */
function Thumb({ name }: { name: string }) {
  const [failed, setFailed] = useState(false);
  if (failed) return <span className="template-rail__thumb template-rail__thumb--empty" />;
  return (
    <img
      className="template-rail__thumb"
      src={templateThumbnailUrl(name)}
      alt=""
      loading="lazy"
      onError={() => setFailed(true)}
    />
  );
}

interface RowProps {
  preparationStatus?: string | null;
  template: TemplateSummary;
  selected: boolean;
  onSelect: (name: string) => void;
}

function Row({ template, selected, onSelect, preparationStatus }: RowProps) {
  const classes = ["template-rail__item"];
  if (selected) classes.push("template-rail__item--active");
  if (needsCalibration(template)) classes.push("template-rail__item--needs");
  return (
    <button
      type="button"
      className={classes.join(" ")}
      data-template={template.name}
      aria-current={selected ? "true" : undefined}
      onClick={() => onSelect(template.name)}
    >
      <Thumb name={template.name} />
      <span className="template-rail__text">
        <span className="template-rail__name">{template.name}</span>
        <span className="template-rail__meta">{describe(template)}</span>
        {template.renderer === "marigold" && (
          <span
            className={`mg-rail-state${marigoldMapsReady(template.maps) ? " mg-rail-state--ready" : ""}`}
          >
            {preparationStatus ||
              (template.maps
                ? marigoldMapsReady(template.maps)
                  ? "Ready"
                  : "Needs maps"
                : "Checking maps")}
          </span>
        )}
      </span>
    </button>
  );
}

interface GroupProps {
  jobs?: PreparationJob[];
  selectedPreparationStatus?: string | null;
  heading: string;
  templates: TemplateSummary[];
  selected: string | null;
  onSelect: (name: string) => void;
}

function Group({
  heading,
  templates,
  selected,
  onSelect,
  jobs = [],
  selectedPreparationStatus,
}: GroupProps) {
  const [expanded, setExpanded] = useState(false);
  if (templates.length === 0) return null;

  const hidden = expanded ? 0 : Math.max(0, templates.length - VISIBLE_LIMIT);
  const visible = expanded ? templates : templates.slice(0, VISIBLE_LIMIT);

  return (
    <section className="template-rail__group">
      <h2 className="template-rail__heading">{`${heading} · ${templates.length}`}</h2>
      {visible.map((t) => (
        <Row
          key={t.name}
          template={t}
          selected={t.name === selected}
          onSelect={onSelect}
          preparationStatus={
            t.name === selected
              ? (selectedPreparationStatus ?? null)
              : jobs.find((job) => job.template === t.name)?.phase === "queued"
                ? "Queued"
                : jobs.some((job) => job.template === t.name)
                  ? "Preparing"
                  : null
          }
        />
      ))}
      {hidden > 0 && (
        <button type="button" className="template-rail__more" onClick={() => setExpanded(true)}>
          {`+ ${hidden} more`}
        </button>
      )}
    </section>
  );
}

interface TemplateRailProps {
  selectedPreparationStatus?: string | null;
  jobs?: PreparationJob[];
  templates: TemplateSummary[];
  selected: string | null;
  onSelect: (name: string) => void;
}

export function TemplateRail({
  templates,
  selected,
  onSelect,
  jobs = [],
  selectedPreparationStatus,
}: TemplateRailProps) {
  const marigold = templates.some((t) => t.renderer === "marigold");
  const [search, setSearch] = useState("");
  const [status, setStatus] = useState<StatusFilter>("all");
  const [kind, setKind] = useState<TemplateKind | null>(null);

  const outstanding = useMemo(() => templates.filter(needsCalibration), [templates]);
  const isReady = (t: TemplateSummary) =>
    t.renderer === "marigold" ? marigoldMapsReady(t.maps) : !needsCalibration(t);
  const doneCount = templates.filter(isReady).length;
  // Held separately so the banner's callback has something TypeScript can
  // narrow -- `outstanding.length > 0` in JSX does not narrow `outstanding[0]`.
  const nextUp = outstanding.find((template) => template.renderer !== "marigold") ?? null;

  const shown = useMemo(() => {
    const term = search.trim().toLowerCase();
    return templates.filter((t) => {
      if (term && !t.name.toLowerCase().includes(term)) return false;
      if (status === "needs" && !needsCalibration(t)) return false;
      if (status === "done" && !isReady(t)) return false;
      if (kind && t.kind !== kind) return false;
      return true;
    });
  }, [templates, search, status, kind]);

  const pending = shown.filter(needsCalibration);
  const finished = shown.filter((t) => !needsCalibration(t));

  return (
    <nav className="template-rail" aria-label="Templates">
      {nextUp && (
        <div className="template-rail__banner">
          <p className="template-rail__banner-text">
            {`${countLabel(outstanding.length, "template")} need${
              outstanding.length === 1 ? "s" : ""
            } calibration`}
          </p>
          <button type="button" className="btn btn-primary" onClick={() => onSelect(nextUp.name)}>
            Calibrate next →
          </button>
        </div>
      )}

      <input
        className="input template-rail__search"
        type="search"
        aria-label="Search templates"
        placeholder="Search templates…"
        value={search}
        onChange={(e) => setSearch(e.target.value)}
      />

      <div className="template-rail__filters">
        {(
          [
            ["all", `All ${templates.length}`],
            ["needs", `${marigold ? "Needs maps" : "Needs calibration"} ${outstanding.length}`],
            ["done", `${marigold ? "Ready" : "Done"} ${doneCount}`],
          ] as const
        ).map(([value, label]) => (
          <button
            key={value}
            type="button"
            className={`tag template-rail__pill${status === value ? " template-rail__pill--on" : ""}`}
            aria-pressed={status === value}
            onClick={() => setStatus(value)}
          >
            {label}
          </button>
        ))}
      </div>

      <div className="template-rail__filters">
        {(Object.keys(KIND_LABELS) as TemplateKind[]).map((value) => (
          <button
            key={value}
            type="button"
            className={`tag template-rail__pill${kind === value ? " template-rail__pill--on" : ""}`}
            aria-pressed={kind === value}
            onClick={() => setKind((current) => (current === value ? null : value))}
          >
            {KIND_LABELS[value]}
          </button>
        ))}
      </div>

      {shown.length === 0 ? (
        <p className="template-rail__empty">No templates match.</p>
      ) : marigold ? (
        <Group
          heading="Templates"
          templates={shown}
          selected={selected}
          onSelect={onSelect}
          jobs={jobs}
          selectedPreparationStatus={selectedPreparationStatus ?? null}
        />
      ) : (
        <>
          <Group
            heading="Needs calibration"
            templates={pending}
            selected={selected}
            onSelect={onSelect}
          />
          <Group
            heading="Calibrated"
            templates={finished}
            selected={selected}
            onSelect={onSelect}
          />
        </>
      )}
      {jobs.length > 0 && (
        <section className="mg-queue">
          <h2 className="template-rail__heading">Preparation queue</h2>
          {jobs.map((job) => (
            <button
              className="mg-queue-entry"
              type="button"
              key={job.id}
              onClick={() => onSelect(job.template)}
            >
              <span>{job.template}</span>
              <span>
                {job.phase === "queued"
                  ? "Queued"
                  : job.kind === "rebuild"
                    ? "Rebuilding maps"
                    : "Preparing"}
              </span>
            </button>
          ))}
        </section>
      )}
    </nav>
  );
}

import { fireEvent, render, screen, waitFor } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";
import * as calibrator from "../api/calibrator";
import type { DesignSummary } from "../types";
