  it("says so when the upload is rejected, rather than failing silently", async () => {
    vi.spyOn(calibrator, "listDesigns").mockResolvedValue(BUNDLED);
    vi.spyOn(calibrator, "uploadDesign").mockRejectedValue(new Error("not an image"));
    render(<TestDesignPicker value="bundled-grid" onChange={vi.fn()} />);
    await screen.findByLabelText("Test design");

    fireEvent.change(screen.getByLabelText(/Upload a PNG/), {
      target: { files: [new File(["x"], "notes.txt")] },
    });
    await screen.findByText("upload failed");
  });

  it("survives the library failing to load", async () => {
    vi.spyOn(calibrator, "listDesigns").mockRejectedValue(new Error("network"));
    render(<TestDesignPicker value="bundled-grid" onChange={vi.fn()} />);
    await screen.findByText("could not load test designs");
  });
});

import type { Preparation } from "../api/preparation";
export function marigoldMapsReady(maps: Preparation["maps"] | null | undefined): boolean {
  return maps?.state === "ready" && maps.can_render;
}
export function preparationLabel(value: Preparation | null): string {
  if (!value) return "Checking maps";
  if (value.active_job)
    return value.active_job.kind === "rebuild"
      ? "Rebuilding maps"
      : value.active_job.phase === "queued"
        ? "Queued"
        : "Preparing";
  if (marigoldMapsReady(value.maps)) return "Ready";
  if (value.latest_job?.phase === "failed") return "Failed";
  return value.maps.state === "out_of_date" ? "Out of date" : "Needs preparation";
}

import { ColourPicker } from "./ColourPicker";
import { useEffect, useMemo, useState, type ReactNode } from "react";
import {
  getMaskHistory,
  type MaskHistory,
  maskUrl,
  type MaskEdit,
  type MaskOperation,
  type Preparation,
} from "../api/preparation";
import { usePreview } from "../hooks/usePreview";
import { templatePhotoUrl } from "../api/calibrator";
import { PreviewPanel, type PreviewJob } from "../components/PreviewPanel";
import { MarigoldRealismPanel } from "../components/MarigoldRealismPanel";
import { BoxToggle } from "../components/BoxToggle";
import { MaskBrushDock, type MaskControls } from "../components/MaskToolbar";
import { PlacementOverlay } from "../components/PlacementOverlay";
import { marigoldMapsReady } from "../components/preparationLabel";
import { maskDraft } from "../components/maskDraft";
import { QuadEditor } from "../components/QuadEditor";
import { TestDesignPicker } from "../components/TestDesignPicker";
import { ViewTabs, type View } from "../components/ViewTabs";
import type { BoundingBox, Renderer, TemplateConfigState, Placement } from "../types";
import "../components/marigold.css";

interface Props {
  templateName: string;
  config: TemplateConfigState & { renderer: Extract<Renderer, { type: "marigold" }> };
  space: [number, number] | null;
  colours: string[];
  knownColours: string[];
  design: string;
  onDesignChange: (design: string) => void;
  onChange: (config: TemplateConfigState) => void;
  preparation: Preparation | null;
  rendererControls: ReactNode;
  calibrationRevision?: string;
  maskEdits: MaskEdit[];
  onMaskEdits: (edits: MaskEdit[]) => void;
  savedConfig: TemplateConfigState | null;
  onPrepare: () => void;
  onPreviewPending?: (pending: boolean) => void;
}
export function MarigoldEditor({
  templateName,
  config,
  space,
  colours,
  knownColours,
  design,
  onDesignChange,
  onChange,
  preparation,
  rendererControls,
  calibrationRevision,
  maskEdits,
  onMaskEdits,
  savedConfig,
  onPrepare,
  onPreviewPending,
}: Props) {
  const [histories, setHistories] = useState<{
    revision: string;
    values: Record<string, MaskHistory>;
  }>({ revision: "", values: {} });
  const [tab, setTab] = useState<View>("calibrate");
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [selectedColour, setSelectedColour] = useState<string | null>(null);
  const colour =
    selectedColour && colours.includes(selectedColour) ? selectedColour : (colours[0] ?? "");

  const [editing, setEditing] = useState(false);
  useEffect(() => {
    if (!editing) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape" && !event.defaultPrevented) setEditing(false);
    };
    document.addEventListener("keydown", onKeyDown);
    return () => document.removeEventListener("keydown", onKeyDown);
  }, [editing]);
  const [showBox, setShowBox] = useState(true);
  const [mode, setMode] = useState<"mask" | "unmask">("mask");
  const [diameter, setDiameter] = useState(24);
  const placements: Placement[] =
    config.kind === "multiple"
      ? config.placements
      : [
          {
            id: "implicit",
            colour: config.kind === "single" ? (config.colour ?? "") : (colours[0] ?? ""),
            bounding_box: config.bounding_box,
          },
        ];
  const index = Math.max(
    0,
    placements.findIndex((p) => p.id === selectedId),
  );
  const selected = placements[index];
  const placementId = config.kind === "multiple" ? (selected?.id ?? null) : null;
  const edit = maskEdits.find((e) => e.placement_id === placementId);
  const operations = edit?.operations ?? [];
  function append(operation: MaskOperation, id = placementId) {
    const existing = maskEdits.find((e) => e.placement_id === id)?.operations ?? [];
    onMaskEdits([
      ...maskEdits.filter((e) => e.placement_id !== id),
      { placement_id: id, operations: [...existing, operation] },
    ]);
  }
  const placementState = preparation?.placements.find((p) => p.placement_id === placementId);
  const draft = maskDraft(operations);
  const draftUndo = draft.strokes.length;
  const historyUndos = draft.undoSaved;
  const controls: MaskControls = {
    editing,
    setEditing,
    mode,
    setMode,
    diameter,
    setDiameter,
    canEdit: !!selected && !!placementState?.mask_available,
    canUndo:
      draftUndo > 0 || (!draft.automatic && (placementState?.undo_count ?? 0) > historyUndos),
    undo: () => append({ type: "undo" }),
    reset: () => append({ type: "reset" }),
  };
  function changeBox(i: number, bounding_box: BoundingBox) {
    if (config.kind === "multiple")
      onChange({
        ...config,
        placements: config.placements.map((p, n) => (n === i ? { ...p, bounding_box } : p)),
      });
    else onChange({ ...config, bounding_box });
  }
  function mutate(next: Placement[], select: string | null) {
    if (config.kind !== "multiple") return;
    onChange({ ...config, placements: next });
    setSelectedId(select);
    setEditing(false);
  }
  function add() {
    const bounding_box: BoundingBox = selected
      ? (selected.bounding_box.map((p) => ({ x: p.x + 40, y: p.y + 20 })) as BoundingBox)
      : [
          { x: 200, y: 150 },
          { x: 400, y: 150 },
          { x: 400, y: 350 },
          { x: 200, y: 350 },
        ];
    const p: Placement = { id: crypto.randomUUID(), colour: "", bounding_box };
    mutate([...placements, p], p.id);
  }
  function duplicate() {
    if (!selected) return;
    const copy = {
      ...selected,
      id: crypto.randomUUID(),
      bounding_box: selected.bounding_box.map((p) => ({ x: p.x + 40, y: p.y + 20 })) as BoundingBox,
    };
    const next = [...placements];
    next.splice(index + 1, 0, copy);
    mutate(next, copy.id);
  }
  const jobs: PreviewJob[] = useMemo(
    () =>
      config.kind === "colour-matrix"
        ? colours.map((c) => ({
            id: c,
            label: c,
            body: { colour: c, bounding_box: config.bounding_box, renderer: config.renderer },
          }))
        : [
            {
              id: templateName,
              label: templateName,
              body:
                config.kind === "multiple"
                  ? { placements: config.placements, renderer: config.renderer }
                  : { bounding_box: config.bounding_box, renderer: config.renderer },
            },
          ],
    [config, colours, templateName],
  );
  const editorRevision = calibrationRevision || preparation?.config_revision || "";
  const editorBody =
    config.kind === "colour-matrix" ? jobs.find((job) => job.id === colour)?.body : jobs[0]?.body;
  const editorPreview = usePreview(
    templateName,
    editorRevision && editorBody
      ? { ...editorBody, calibration_revision: editorRevision, mask_edits: maskEdits }
      : null,
    design,
    true,
    onPreviewPending,
  );
  const revision = preparation?.config_revision ?? "";
  const placementKey = JSON.stringify(
    preparation?.placements.filter((p) => p.mask_available).map((p) => p.placement_id) ?? [],
  );
  useEffect(() => {
    let active = true;
    const ids: (string | null)[] = JSON.parse(placementKey) as (string | null)[];
    void Promise.all(
      ids.map(async (id) => [id ?? "implicit", await getMaskHistory(templateName, id)] as const),
    )
      .then((rows) => {
        if (active) setHistories({ revision, values: Object.fromEntries(rows) });
      })
      .catch(() => {});
    return () => {
      active = false;
    };
  }, [templateName, revision, placementKey]);
  const mapInputs = (value: TemplateConfigState | null) =>
    value?.renderer.type === "marigold"
      ? JSON.stringify({
          kind: value.kind,
          geometry:
            value.kind === "multiple"
              ? value.placements.map((p) => ({ id: p.id, bounding_box: p.bounding_box }))
              : value.bounding_box,
          inference: value.renderer.config.inference,
        })
      : null;
  const unsavedMaps = mapInputs(config) !== mapInputs(savedConfig) || maskEdits.length > 0;
  const awaitingSavedRevision =
    !!calibrationRevision && preparation?.config_revision !== calibrationRevision;
  const blocked =
    !marigoldMapsReady(preparation?.maps) ||
    unsavedMaps ||
    awaitingSavedRevision ||
    !!preparation?.active_job;
  return (
    <main className="app__main">
      <div className="app__preview">
        <div className="app__preview-bar">
          <ViewTabs value={tab} onChange={setTab} />
          <TestDesignPicker compact value={design} onChange={onDesignChange} />
          {tab === "calibrate" && config.kind === "colour-matrix" && colours.length > 1 && (
            <ColourPicker colour={colour} colours={colours} onChange={setSelectedColour} />
          )}
          {tab === "calibrate" && (
            <div className="app__outline-toggle">
              <BoxToggle checked={showBox} onChange={setShowBox} />
            </div>
          )}
        </div>
        {tab === "calibrate" && (
          <>
            <div className="mg-stage mg-editor-stage">
              {space ? (
                <QuadEditor
                  imageUrl={
                    editorPreview ??
                    templatePhotoUrl(templateName, config.kind === "colour-matrix" ? colour : null)
                  }
                  space={space}
                  boxes={placements.map((p) => p.bounding_box)}
                  selectedIndex={index}
                  onSelect={(i) => {
                    setSelectedId(placements[i]?.id ?? null);
                    setEditing(false);
                  }}
                  onChangeBox={changeBox}
                  outlines={showBox ? "all" : "none"}
                  interactive={!editing}
                  {...(config.kind === "multiple"
                    ? {
                        labels: placements.map((p) => p.colour),
                        labelSuggestions: knownColours,
                        labelPlaceholder: "assign colour",
                        onLabelChange: (i: number, c: string) =>
                          mutate(
                            placements.map((p, n) => (n === i ? { ...p, colour: c } : p)),
                            placements[i]?.id ?? null,
                          ),
                        onAddBox: add,
                        onDuplicateSelected: duplicate,
                        onDeleteSelected: () => {
                          if (!selected) return;
                          mutate(
                            placements.filter((p) => p.id !== selected.id),
                            null,
                          );
                          onMaskEdits(maskEdits.filter((e) => e.placement_id !== selected.id));
                        },
                        onBringSelectedToFront: () => {
                          if (selected)
                            mutate(
                              [...placements.filter((p) => p.id !== selected.id), selected],
                              selected.id,
                            );
                        },
                      }
                    : {})}
                  overlay={
                    <>
                      {placements.map((p, i) => {
                        const id = config.kind === "multiple" ? p.id : null;
                        const maskState = preparation?.placements.find(
                          (s) => s.placement_id === id,
                        );
                        return (
                          <PlacementOverlay
                            key={p.id}
                            showArtwork={!editorPreview}
                            box={p.bounding_box}
                            designUrl={`/api/designs/${encodeURIComponent(design)}/image`}
                            maskUrl={
                              maskState?.mask_available
                                ? maskUrl(templateName, id, false, revision)
                                : null
                            }
                            undoBases={
                              histories.revision === revision
                                ? (histories.values[id ?? "implicit"]?.strokes.map(
                                    (s) => s.before,
                                  ) ?? [])
                                : []
                            }
                            automaticMaskUrl={
                              maskState?.mask_available
                                ? maskUrl(templateName, id, true, revision)
                                : null
                            }
                            operations={
                              maskEdits.find((e) => e.placement_id === id)?.operations ?? []
                            }
                            space={space}
                            editing={editing && i === index}
                            mode={mode}
                            diameter={diameter}
                            onStroke={(stroke) => append(stroke, id)}
                          />
                        );
                      })}
                    </>
                  }
                />
              ) : (
                <p className="app__loading">No readable scene photo.</p>
              )}
              {space && <MaskBrushDock controls={controls} />}
            </div>
          </>
        )}
        <PreviewPanel
          fullQuality
          templateName={templateName}
          jobs={jobs}
          design={design}
          active={tab === "preview"}
          blocked={
            blocked
              ? unsavedMaps
                ? "Save your calibration changes before rendering."
                : awaitingSavedRevision
                  ? "Waiting for current calibration status. Reload the template if it changed elsewhere."
                  : (preparation?.maps.message ?? "Prepare the template first.")
              : null
          }
          onPrepare={onPrepare}
          prepareLabel={
            preparation?.maps.reason === "photo_changed"
              ? "Reset masks and prepare"
              : "Prepare template"
          }
          identity={preparation?.maps.content_digest ?? ""}
        />
      </div>
      <aside className="app__controls">
        {rendererControls}
        <MarigoldRealismPanel
          value={config.renderer.config.appearance}
          onChange={(appearance) =>
            onChange({
              ...config,
              renderer: { ...config.renderer, config: { ...config.renderer.config, appearance } },
            })
          }
        />
      </aside>
    </main>
  );
}

import { useCallback, useEffect, useRef, useState } from "react";
import { createListing, describeListingDraft, patchListing, renameListing } from "../api/listings";
import { listingDocument } from "../pages/editor/listingDocument";
import type { Issue, ListingDetail } from "../types";

/** How long the editor waits after the last edit before saving -- long
 * enough that a run of keystrokes in a text field collapses into one
 * request, short enough that "Saved a moment ago" reads as true. Also
 * flushed immediately on blur, on a tab switch and on unmount
 * (see `flush` below), so a save is never waiting on this timer alone. */
export const AUTOSAVE_DEBOUNCE_MS = 800;

export type Patch = Record<string, unknown>;

/** Where the listing stands with the disk, as the page head reports it.
 *
 * `unsaved` is the state where the listing has a name but the server would
 * not write the document: since ADR-0043 that means the document contradicts
 * itself (a price in the wrong currency, a title over Etsy's limit), never
 * that it is merely incomplete. `field_errors` names the field; this says
 * the consequence is a file that does not exist. */
export type SaveState =
  | { kind: "unnamed" }
  | { kind: "saving" }
  | { kind: "saved"; savedAt: number }
  | { kind: "unsaved"; reason?: string }
  | { kind: "name-taken"; name: string }
  | { kind: "save-failed" };

/** What one write came to. `saved: false` is a document the server would
 * not write -- nothing on disk changed -- carrying what to show about why:
 * the field errors, and the issues where they describe the candidate (a
 * listing template's valid-only save, template completeness) rather than something else. */
export type SaveOutcome =
  | { saved: true; detail: ListingDetail }
  | { saved: false; issues: Issue[] | null; field_errors: Record<string, string> };

/** How a document reaches the disk. The editor's three states (see
 * {@link useAutosave}) are the same for a listing and a listing template;
 * what differs is the endpoints and the document, so that is what a
 * transport supplies. `describe` is `null` where an unnamed draft has
 * nothing to ask the server. */
export interface AutosaveTransport {
  /** The stored document, out of what the editor shows. */
  document: (detail: ListingDetail) => Patch;
  describe: ((candidate: Patch) => Promise<ListingDetail>) | null;
  create: (name: string, candidate: Patch) => Promise<SaveOutcome>;
  /** `patch` is the edits since the last save; `candidate` the whole
   * document with them applied. A transport sends whichever it writes. */
  save: (name: string, patch: Patch, candidate: Patch) => Promise<SaveOutcome>;
  rename: (from: string, to: string) => Promise<ListingDetail>;
}

/** A listing: `POST /api/listing-draft`, `POST /api/listings`, a PATCH of
 * the delta and the rename. A refused create answers the *empty* draft
 * beside its field errors, so only the errors are news. */
export const LISTING_TRANSPORT: AutosaveTransport = {
  document: (detail) => listingDocument(detail),
  describe: (candidate) => describeListingDraft(candidate),
  create: async (name, candidate) => {
    const fresh = await createListing({ name, document: candidate });
    if (fresh.name === "") return { saved: false, issues: null, field_errors: fresh.field_errors };
    return { saved: true, detail: fresh };
  },
  // A PATCH whose merged document contradicts itself answers 200 with
  // `field_errors` and the listing unchanged: not written, so not saved.
  save: async (name, patch) => {
    const fresh = await patchListing(name, patch);
    if (Object.keys(fresh.field_errors ?? {}).length > 0) {
      return { saved: false, issues: null, field_errors: fresh.field_errors };
    }
    return { saved: true, detail: fresh };
  },
  rename: (from, to) => renameListing(from, to),
};

/** A `{ kind: "saved" }` stamped with when. Successful writes use the browser
 * clock; the initial state can instead use `listing.yaml`'s mtime supplied by
 * the server. */
function saved(savedAt = Date.now()): SaveState {
  return { kind: "saved", savedAt };
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** The same one-level-deep merge `core/application/listing_edits.py`'s `_merge` applies
 * server-side, mirrored here so the optimistic local state -- and the
 * accumulation of several edits made before the debounce fires -- agrees
 * with what the server will actually end up storing. */
function mergePatch(base: Patch, patch: Patch): Patch {
  const merged: Patch = { ...base };
  for (const [key, value] of Object.entries(patch)) {
    if (key === "etsy" && isPlainObject(value) && isPlainObject(merged.etsy)) {
      merged.etsy = { ...merged.etsy, ...value };
    } else {
      merged[key] = value;
    }
  }
  return merged;
}

/** `design:` as `config/listing.py`'s `_coerce_design` will store it.
 *
 * The editor sends the bare ref a human writes in `listing.yaml`, and the
 * server normalises it to `{default: ref}` -- so between the edit and the
 * response, local state held a *string* where every consumer expects the map,
 * and `Object.keys("designs/x.png")` made the design strip report "45
 * artworks". On a saved listing the response healed it 800ms later, which is
 * why it went unnoticed; on a draft there is no response to heal it.
 *
 * Applied to local state only. The patch itself keeps the bare form, because
 * that is the form the file stores. */
function coerceDesign(detail: Patch): Patch {
  if (typeof detail.design !== "string") return detail;
  return { ...detail, design: { default: detail.design } };
}

interface UseAutosave {
  /** The listing as the editor should render it: the server's last response,
   * with any not-yet-saved edits already merged in. */
  detail: ListingDetail;
  /** Applies a partial `listing.yaml` patch: updates local state immediately
   * and schedules (or extends) the debounced save. */
  update: (patch: Patch) => void;
  /** Shows a value the server has already written -- an AI run's drafted
   * brief (features/market-seo-20260924/spec.md, *AI runs*) -- without saving it again: local
   * state only, nothing pending, the save state untouched. Sending it back
   * would be a second write of the same value, and would race the seller's
   * own next edit to that field. */
  adopt: (patch: Patch) => void;
  /** Sends whatever is pending right now, without waiting for the debounce.
   * Callers use this on blur and on a tab switch; the hook itself calls it on
   * unmount, and `rename` awaits it. */
  flush: () => Promise<void>;
  /** Names an unnamed listing (creating it) or renames one that exists. Both
   * end at the same place -- a listing on disk under a new name -- which is
   * why they are one function and one `onNamed` callback. */
  commitName: (next: string) => void;
  save: SaveState;
}

/**
 * Autosave for listings. The mockup-template calibrator follows the same
 * rules (debounce, single flight, flush on unmount) in `useTemplateSession`,
 * whose document is a whole template.yaml PUT over a revision.
 *
 * It holds three transports, not one, because the editor is also the create
 * form and a listing therefore passes through three states in one sitting:
 *
 * | on disk | named | sends |
 * |---|---|---|
 * | no | no | `POST /api/listing-draft` -- writes nothing, refreshes issues |
 * | no | yes | `POST /api/listings` -- writes it, if the document will validate |
 * | yes | -- | `PATCH /api/listings/{name}` -- the delta |
 *
 * They live together rather than in a page or a sibling hook because the
 * choice depends on what is in `pending`, and `pending` lives here: a second
 * hook would have to copy the debounce, the merge and the flush-on-unmount to
 * reach it, and the create/patch boundary would end up somewhere other than
 * the place that knows whether it is safe to send at all.
 */
export function useAutosave(
  name: string | null,
  initial: ListingDetail,
  options: {
    onNamed?: (name: string, fresh: ListingDetail) => void;
    /** The listing's by default. Must keep its identity across renders --
     * a module constant, or memoized -- since every callback here
     * depends on it, and the flush-on-unmount effect runs whenever those
     * change. */
    transport?: AutosaveTransport;
  } = {},
): UseAutosave {
  const [detail, setDetail] = useState(initial);
  const [save, setSave] = useState<SaveState>(() =>
    name === null
      ? { kind: "unnamed" }
      : saved(initial.modified_at === null ? Date.now() : Date.parse(initial.modified_at)),
  );
  const pending = useRef<Patch | null>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  /** The name this listing is on disk under, or `null` while it is not. */
  const savedName = useRef<string | null>(name);
  /** A create or rename is in flight: edits keep accumulating in `pending`,
   * but nothing is sent, because the name they would be sent under is exactly
   * what is being decided. */
  const naming = useRef(false);
  /** A PATCH to the named listing is in flight. `update()` schedules a fresh
   * debounce on every edit, and `flush()` is also called directly on blur,
   * tab-switch and unmount -- any of those can land while the previous PATCH
   * is still outstanding. Without this guard, two PATCHes end up in flight
   * at once and whichever *resolves* last wins, regardless of which was
   * *sent* last. */
  const patching = useRef(false);
  /** A flush arrived while `patching.current` was true. Rather than firing a
   * second concurrent PATCH, it sets this so the in-flight one's `finally`
   * re-runs `flush()` once it settles -- picking up whatever is in `pending`
   * at that later point, one request at a time. */
  const patchAgain = useRef(false);
  /** A name typed for a listing that is not on disk yet. It outlives a refused
   * create, which is what lets the next edit retry it rather than asking the
   * user to type the name again. */
  const draftName = useRef("");
  /** What `adopt` has shown since the last save *sent* after it. A response
   * to a request sent earlier describes the file as it was before the server
   * wrote these values -- an AI run's brief lands while an autosave is in
   * flight -- so they are laid back over that response rather than blanked
   * by it. A new object on every adopt, so a request can tell whether one
   * happened while it was out. */
  const adopted = useRef<Patch | null>(null);
  // `detail` as the save callbacks should read it. A ref rather than a
  // dependency because a save must send what is on screen *now*, not what was
  // on screen when the debounce was armed.
  const latest = useRef(detail);
  const onNamed = options.onNamed;
  const transport = options.transport ?? LISTING_TRANSPORT;

  const clearTimer = useCallback(() => {
    if (timer.current !== null) {
      clearTimeout(timer.current);
      timer.current = null;
    }
  }, []);

  /** Whatever the server should be told about right now: the last response
   * with every pending edit merged over it, as a `listing.yaml` document. */
  const candidate = useCallback((): Patch => {
    return mergePatch(transport.document(latest.current), pending.current ?? {});
  }, [transport]);

  /** `sentWith` is `adopted` as it stood when the request was sent. */
  const applyResponse = useCallback((fresh: ListingDetail, sentWith: Patch | null) => {
    // A response carrying field errors describes the *empty* draft alongside
    // them (there is no listing to describe), so only the errors are news --
    // taking the rest would wipe the document being edited.
    if (Object.keys(fresh.field_errors ?? {}).length > 0) {
      setDetail((current) => ({ ...current, field_errors: fresh.field_errors }));
      return;
    }
    // Sent after the last adopt: the response already carries what was
    // adopted, and from here the file is the word on it.
    if (adopted.current === sentWith) adopted.current = null;
    // Keep edits made while a save was in flight visible, over anything
    // adopted meanwhile: the seller's own typing wins.
    const overlay = mergePatch(adopted.current ?? {}, pending.current ?? {});
    setDetail(
      Object.keys(overlay).length === 0
        ? fresh
        : (coerceDesign(mergePatch(fresh, overlay)) as ListingDetail),
    );
  }, []);

  /** A write the server refused: the edits stay on screen, and so does
   * everything else, with what the refusal said about them laid over. */
  const applyRefusal = useCallback((outcome: SaveOutcome & { saved: false }) => {
    setDetail((current) => ({
      ...current,
      field_errors: outcome.field_errors,
      ...(outcome.issues === null ? {} : { issues: outcome.issues }),
    }));
    // A contradiction no single field owns has no field to highlight, so
    // the page head is the only place left to say what it is.
    const reason = outcome.field_errors.__root__;
    setSave(reason === undefined ? { kind: "unsaved" } : { kind: "unsaved", reason });
  }, []);

  const create = useCallback(
    async (next: string) => {
      setSave({ kind: "saving" });
      // What this create carries, captured before the await. An edit made
      // while it is in flight lands in a *different* `pending` object
      // (`update` replaces it rather than mutating), and that one is not in
      // the document being sent -- so clearing `pending` wholesale on success
      // would drop it silently. The same rule `applyResponse` already states
      // for a PATCH, applied to the one request that did not have it: The
      // drafted brief is written by a request that resolves during
      // exactly this window, and it went missing every time.
      const sent = pending.current;
      const sentWith = adopted.current;
      const outcome = await transport.create(next, candidate());
      if (!outcome.saved) {
        // The server would not write it -- `field_errors` says why. `pending`
        // stays put, and so does the name, so the edit that fixes the document
        // is what retries the create.
        applyRefusal(outcome);
        return;
      }
      const fresh = outcome.detail;
      if (pending.current === sent) pending.current = null;
      savedName.current = next;
      applyResponse(fresh, sentWith);
      // Left "saving" when something is still pending, so the flush
      // `commitName` schedules is what reports the listing saved -- the same
      // way `flush` withholds it while another edit is waiting.
      if (pending.current === null) setSave(saved());
      onNamed?.(next, fresh);
    },
    [applyRefusal, applyResponse, candidate, onNamed, transport],
  );

  const flush = useCallback(async (): Promise<void> => {
    clearTimer();
    if (naming.current) return;

    if (savedName.current !== null) {
      if (patching.current) {
        // A PATCH is already in flight. Sending a second one now would race
        // it -- whichever *resolves* last would win, not whichever holds the
        // newer edit. Defer instead: the loop below re-checks `pending` once
        // the in-flight one settles, rather than firing a concurrent request.
        patchAgain.current = true;
        return;
      }
      // A loop, not recursion, so a deferred continuation (below) can pick up
      // whatever landed in `pending` while the previous PATCH was in flight,
      // one request at a time, without the function calling itself. The React
      // compiler cannot memoize a `useCallback` that calls itself.
      for (;;) {
        const patch = pending.current;
        const currentName = savedName.current;
        if (patch === null || currentName === null) return;
        // Cleared only once the PATCH actually lands -- a rejection (dropped
        // connection, a 5xx) must leave the edit right where the next flush
        // (the next debounce, or the next `update()`, which merges onto
        // whatever is still here) will find and retry it. Losing it here
        // would silently discard whatever was pending, structured
        // `description` triples included (AI SEO implementation plan, PR6).
        pending.current = null;
        patching.current = true;
        setSave({ kind: "saving" });
        const sentWith = adopted.current;
        // The whole document as well as the delta, for a transport that
        // writes all of it (a listing template's `PUT`). The delta is out of
        // `pending` already, so it is merged back in.
        const whole = mergePatch(candidate(), patch);
        try {
          const outcome = await transport.save(currentName, patch, whole);
          if (outcome.saved) {
            applyResponse(outcome.detail, sentWith);
            // A newer edit may already be waiting. Marking this one saved
            // would hide it until the next iteration starts.
            if (pending.current === null) setSave(saved());
          } else {
            // Not written: the values stay on screen and the edit stays
            // pending, so the next edit sends it again -- which is the
            // retry. Dropping it let that next edit save alone, and its
            // response put the unwritten values back to the file's.
            pending.current = mergePatch(patch, pending.current ?? {});
            applyRefusal(outcome);
          }
        } catch {
          // Swallowed, not rethrown: nothing that calls `flush()` (the
          // debounce timer, `onBlur`, unmount) is set up to catch it, and a
          // failed autosave is reported through `save` -- the same channel
          // every other outcome here uses -- rather than an exception a
          // caller would have to remember to handle.
          pending.current = mergePatch(patch, pending.current ?? {});
          setSave({ kind: "save-failed" });
        } finally {
          patching.current = false;
        }
        if (!patchAgain.current) return;
        patchAgain.current = false;
      }
    }

    if (pending.current === null) return;

    // Named, but refused once already: every edit is another attempt at the
    // document the server would not write, so it retries rather than settling
    // for a description of it.
    if (draftName.current !== "") {
      naming.current = true;
      try {
        await create(draftName.current);
      } catch {
        setSave({ kind: "name-taken", name: draftName.current });
      } finally {
        naming.current = false;
      }
      return;
    }

    // Not on disk and not named: describe the candidate so the issues banner
    // stays true. Nothing is written, so `pending` is not cleared -- it is what
    // the create will carry once a name arrives.
    if (transport.describe === null) return;
    const sentWith = adopted.current;
    const fresh = await transport.describe(candidate());
    applyResponse(fresh, sentWith);
  }, [applyRefusal, applyResponse, candidate, clearTimer, create, transport]);

  const update = useCallback(
    (patch: Patch) => {
      setDetail((current) => coerceDesign(mergePatch(current, patch)) as ListingDetail);
      pending.current = mergePatch(pending.current ?? {}, patch);
      clearTimer();
      timer.current = setTimeout(() => void flush(), AUTOSAVE_DEBOUNCE_MS);
    },
    [clearTimer, flush],
  );

  const adopt = useCallback((patch: Patch) => {
    adopted.current = mergePatch(adopted.current ?? {}, patch);
    setDetail((current) => coerceDesign(mergePatch(current, patch)) as ListingDetail);
  }, []);

  const commitName = useCallback(
    (next: string) => {
      if (next === savedName.current || naming.current) return;
      clearTimer();
      naming.current = true;
      setSave({ kind: "saving" });
      const run = async () => {
        if (savedName.current === null) {
          draftName.current = next;
          await create(next);
          return;
        }
        // Drain first: the old name still exists, so an edit already made has
        // somewhere to go. Anything typed from here lands in `pending` and is
        // sent under the new name -- two fates, and no third.
        const patch = pending.current;
        pending.current = null;
        const sentWith = adopted.current;
        if (patch !== null) {
          const outcome = await transport.save(
            savedName.current,
            patch,
            mergePatch(candidate(), patch),
          );
          if (outcome.saved) applyResponse(outcome.detail, sentWith);
        }
        const fresh = await transport.rename(savedName.current, next);
        savedName.current = next;
        // Read from the file after the drain, under the rename's lock: it
        // carries anything adopted before it.
        if (adopted.current === sentWith) adopted.current = null;
        setDetail(fresh);
        setSave(saved());
        onNamed?.(next, fresh);
      };
      run()
        .catch(() => setSave({ kind: "name-taken", name: next }))
        .finally(() => {
          naming.current = false;
          if (pending.current !== null) {
            timer.current = setTimeout(() => void flush(), AUTOSAVE_DEBOUNCE_MS);
          }
        });
    },
    [applyResponse, candidate, clearTimer, create, flush, onNamed, transport],
  );

  useEffect(() => {
    latest.current = detail;
  }, [detail]);

  const flushOnUnmount = useRef(flush);
  useEffect(() => {
    flushOnUnmount.current = flush;
  }, [flush]);

  // Flush on unmount so a listing switch (or navigating away) never silently
  // drops the last few hundred milliseconds of typing. Changing callbacks
  // while still mounted must not flush a refused edit in a retry loop.
  useEffect(() => () => void flushOnUnmount.current(), []);

  return { detail, update, adopt, flush, commitName, save };
}

import { useCallback, useEffect, useState } from "react";
import { followPreparation, getPreparation, type Preparation } from "../api/preparation";

/** Reattach to server work, including CPU rebuilds after save. Reconnection reads
 * status and resumes events; it never submits another preparation job. Automatic
 * reads pause while the editor composite is pending, then resume with a fresh
 * snapshot so progress validation does not compete with the visible edit. */
export function usePreparation(name: string | null, version: number, previewPending = false) {
  const [entry, setEntry] = useState<{ name: string; value: Preparation } | null>(null);
  const [error, setError] = useState("");
  const [refresh, setRefresh] = useState(0);
  const reload = useCallback(() => setRefresh((n) => n + 1), []);
  useEffect(() => {
    if (!name || previewPending) return;
    const template = name;
    let cancelled = false;
    let stream: ReturnType<typeof followPreparation> | undefined;
    let timer: ReturnType<typeof setTimeout> | undefined;
    let eventTimer: ReturnType<typeof setTimeout> | undefined;
    let cursor: number | undefined;
    let followedId: string | undefined;
    let reading = false;
    async function read() {
      if (reading || cancelled) return;
      reading = true;
      try {
        const value = await getPreparation(template);
        if (cancelled) return;
        setEntry({ name: template, value });
        setError("");
        stream?.close();
        if (value.active_job) {
          const id = value.active_job.id;
          if (followedId !== id) cursor = undefined;
          followedId = id;
          stream = followPreparation(id, {
            ...(cursor === undefined ? {} : { lastEventId: cursor }),
            onEvent: (event) => {
              cursor =
                "resync" in event
                  ? undefined
                  : "sequence" in event
                    ? event.sequence
                    : event.last_event_sequence;
              // CPU checkpoints arrive in bursts. Reading all masks and map
              // readiness per event competes with interactive composition.
              if (!eventTimer)
                eventTimer = setTimeout(() => {
                  eventTimer = undefined;
                  void read();
                }, 250);
            },
            onDone: () => {
              timer = setTimeout(() => void read(), 250);
            },
            onError: () => {
              cursor = undefined;
              timer = setTimeout(() => void read(), 1000);
            },
          });
        }
      } catch (e) {
        if (!cancelled) {
          setError(e instanceof Error ? e.message : "Could not read map status");
          timer = setTimeout(() => void read(), 3000);
        }
      } finally {
        reading = false;
      }
    }
    const onFocus = () => void read();
    window.addEventListener("focus", onFocus);
    void read();
    return () => {
      window.removeEventListener("focus", onFocus);
      cancelled = true;
      stream?.close();
      if (timer) clearTimeout(timer);
      if (eventTimer) clearTimeout(eventTimer);
    };
  }, [name, version, refresh, previewPending]);
  return { preparation: entry?.name === name ? entry.value : null, error, reload };
}

import { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
import { renderPreview } from "../api/calibrator";

/** How long the editor waits after the last edit before asking the server for
 * a new composite.
 *
 * Short, because an editor frame is now a downscaled render off a warm
 * in-process cache rather than a full-resolution one off disk. The debounce is
 * no longer what protects the server -- {@link usePreview}'s one-at-a-time
 * rule is -- it just avoids spending a request on the first pixel of a drag
 * that is about to travel two hundred more. */
export const PREVIEW_DEBOUNCE_MS = 80;

type PreviewBody = Parameters<typeof renderPreview>[1];

interface Job {
  templateName: string;
  key: string;
  design: string;
}

/**
 * The debounced preview loop, shared by all three editors.
 *
 * Each editor used to carry its own copy of this: the same `setTimeout`,
 * `renderPreview`, revoke-the-previous-URL and `clearTimeout` cleanup, written
 * out three times. All three had the same leak -- the cleanup cleared the
 * timer but never revoked the object URL still held in state, so every
 * template switch and every unmount stranded one blob in the document. There
 * is one implementation now, and it revokes on the way out.
 *
 * `body` is compared by value, not identity: an editor rebuilds it on every
 * render, and comparing by identity would restart the debounce on renders that
 * changed nothing the preview depends on. Pass `null` to hold off entirely
 * (a colour-matrix template with no colour selected yet).
 *
 * **One request is in flight at a time.** A drag outruns any debounce short
 * enough to feel live, and firing regardless just queues renders behind each
 * other on a server that runs them one at a time -- which does not make the
 * newest frame arrive sooner, only every frame arrive later, and progressively
 * later as the drag goes on. So a change during a render is *recorded* rather
 * than sent, and the render that finishes immediately starts the latest one
 * instead. Intermediate frames nobody would have seen are dropped, which is
 * the point.
 *
 * Renders at `editor` scale. The image that comes back is therefore smaller
 * than the template's real photo, and must not be measured to find the
 * coordinate space -- see `QuadEditor`'s `space` prop.
 */
export function usePreview(
  templateName: string,
  body: PreviewBody | null,
  design: string,
  strict = false,
  onPending?: (pending: boolean) => void,
): string | null {
  const pendingListener = useRef(onPending);
  const [displayedTemplate, setDisplayedTemplate] = useState(templateName);
  const latest = useRef("");
  const requestIdentity = JSON.stringify({ templateName, body, design });
  const strictMode = useRef(strict);
  useLayoutEffect(() => {
    latest.current = requestIdentity;
    strictMode.current = strict;
    pendingListener.current = onPending;
  }, [requestIdentity, strict, onPending]);
  const [url, setUrl] = useState<string | null>(null);

  // The URL currently on screen, for the unmount revoke below. A ref, because
  // that cleanup must not re-run every time the URL changes -- it would revoke
  // the image the editor is displaying.
  const current = useRef<string | null>(null);
  useEffect(() => {
    current.current = url;
  }, [url]);

  // The job waiting to be sent (at most one -- a newer edit overwrites an
  // unsent older one), and whether the loop is already running.
  const queued = useRef<Job | null>(null);
  const busy = useRef(false);
  // Bumped when this hook stops caring about anything already in flight: an
  // unmount, or a switch to a different template. Not bumped for an ordinary
  // edit -- that response is still the newest frame there is, and showing it
  // while the next one renders is what keeps the canvas from flickering back
  // to a stale image.
  const generation = useRef(0);

  // A loop rather than a call that restarts itself: the "render the newest
  // thing that arrived while I was busy" step is the same step as the first
  // one, and writing it as recursion only made the function reference itself
  // before it existed.
  const pump = useCallback(async () => {
    if (busy.current) return;
    busy.current = true;
    try {
      while (queued.current) {
        const job = queued.current;
        queued.current = null;
        const sent = generation.current;
        try {
          const next = await renderPreview(
            job.templateName,
            JSON.parse(job.key) as PreviewBody,
            job.design,
            "editor",
          );
          // A response for a template the editor has already left: revoked
          // here rather than stored, or it leaks exactly like the old cleanup
          // let the displayed one leak.
          if (
            sent !== generation.current ||
            (strictMode.current &&
              latest.current !==
                JSON.stringify({
                  templateName: job.templateName,
                  body: JSON.parse(job.key) as PreviewBody,
                  design: job.design,
                }))
          ) {
            URL.revokeObjectURL(next);
            continue;
          }
          setDisplayedTemplate(job.templateName);
          setUrl((previous) => {
            if (previous) URL.revokeObjectURL(previous);
            return next;
          });
          pendingListener.current?.(false);
        } catch {
          // A refused strict frame must not leave an old material composite
          // under newly edited geometry. Its caller can show the local overlay.
          if (
            sent === generation.current &&
            latest.current ===
              JSON.stringify({
                templateName: job.templateName,
                body: JSON.parse(job.key) as PreviewBody,
                design: job.design,
              })
          )
            pendingListener.current?.(false);
          if (strictMode.current && sent === generation.current) {
            setUrl((previous) => {
              if (previous) URL.revokeObjectURL(previous);
              return null;
            });
          }
        }
      }
    } finally {
      busy.current = false;
    }
  }, []);

  // Anything still in flight belongs to the previous template, so its result
  // must not land on this one's canvas.
  useEffect(() => {
    // Capture this template's listener. A newer render can already have
    // installed the next template's listener before this cleanup runs.
    const notify = pendingListener.current;
    return () => {
      generation.current += 1;
      queued.current = null;
      notify?.(false);
    };
  }, [templateName]);

  useEffect(
    () => () => {
      generation.current += 1;
      if (current.current) URL.revokeObjectURL(current.current);
    },
    [],
  );

  const key = body === null ? null : JSON.stringify(body);

  useEffect(() => {
    if (key === null) {
      pendingListener.current?.(false);
      return;
    }
    pendingListener.current?.(true);
    const timer = setTimeout(() => {
      queued.current = { templateName, key, design };
      void pump();
    }, PREVIEW_DEBOUNCE_MS);
    return () => clearTimeout(timer);
  }, [templateName, key, design, pump]);

  return strict && displayedTemplate !== templateName ? null : url;
}

import { useEffect, useRef, useState } from "react";
import { getPreparation, type Preparation, type PreparationJob } from "../api/preparation";
import type { TemplateSummary } from "../types";

/** Fill catalog readiness one row at a time; selected status has its own event lifecycle. */
export function useTemplateReadiness(
  templates: TemplateSummary[],
  selected: string | null,
  jobs: PreparationJob[],
) {
  const names = templates.filter((t) => t.renderer === "marigold").map((t) => t.name);
  const key = JSON.stringify(names);
  // The selected editor follows its own job events. Its autosaves must not
  // restart catalog discovery and compete with every interactive composite.
  const jobKey = JSON.stringify(
    jobs
      .filter((job) => job.template !== selected)
      .map((job) => [job.template, job.id + job.phase]),
  );
  const checked = useRef(new Map<string, string>());
  const [facts, setFacts] = useState<Record<string, Preparation["maps"]>>({});
  useEffect(() => {
    let active = true;
    const controller = new AbortController();
    const names: string[] = JSON.parse(key);
    const states = JSON.parse(jobKey) as [string, string][];
    for (const name of checked.current.keys())
      if (!names.includes(name)) checked.current.delete(name);
    if (selected) checked.current.delete(selected);
    async function read() {
      for (const name of names) {
        if (!active) return;
        if (name === selected) continue;
        const token = JSON.stringify(states.filter(([template]) => template === name));
        if (checked.current.get(name) === token) continue;
        checked.current.delete(name);
        try {
          const status = await getPreparation(name, controller.signal);
          if (!active) return;
          checked.current.set(name, token);
          setFacts((current) => ({ ...current, [name]: status.maps }));
        } catch {
          // Keep the catalog row unknown. Selecting it exposes the actionable error.
        }
      }
    }
    void read();
    return () => {
      active = false;
      controller.abort();
    };
  }, [key, selected, jobKey]);
  return facts;
}

import { useEffect, useState, useSyncExternalStore } from "react";
import { getTemplateConfig, saveTemplateConfig, TemplateConflictError } from "../api/calibrator";
import {
  cancelPreparation,
  getPreparation,
  prepareTemplate,
  type MaskEdit,
  type MaskOperation,
  type Preparation,
} from "../api/preparation";
import type { TemplateConfigState } from "../types";
import { AUTOSAVE_DEBOUNCE_MS } from "./useAutosave";
import { usePreparation } from "./usePreparation";

/** Where the open template stands with the disk, as the header reports it.
 *
 * `conflict` is a save the server refused because template.yaml moved on
 * since this session read it (409/412). Unlike `failed`, retrying cannot fix
 * it: only {@link TemplateSession.reload} can. */
export type TemplateSaveState =
  | { kind: "idle" }
  | { kind: "saving" }
  | { kind: "saved"; savedAt: number }
  | { kind: "failed"; message: string }
  | { kind: "conflict"; message: string };

/** `none` while no template is selected. `ready` with a `null` config is a
 * folder of photos with no template.yaml yet -- the kind picker's case. */
export type TemplateLoad = "none" | "loading" | "ready" | "error";

export type PreparationAction = "prepare" | "prepare_again" | "retry";

export interface TemplateSession {
  load: TemplateLoad;
  /** The draft: the document as last read or saved, with every edit since. */
  config: TemplateConfigState | null;
  /** The document as this session last read or wrote it. */
  saved: TemplateConfigState | null;
  dirty: boolean;
  save: TemplateSaveState;
  /** Mask strokes drawn but not yet committed by a save. */
  maskEdits: MaskEdit[];
  /** The revision a preview's `calibration_revision` names: the one this
   * session last read or wrote, or the one its own preparation completed at. */
  calibrationRevision: string;
  preparation: Preparation | null;
  preparationError: string;
  /** An explicit prepare or cancel request is outstanding. */
  preparing: boolean;
  /** Replaces the draft and (re)arms the debounced autosave. */
  update: (config: TemplateConfigState) => void;
  setMaskEdits: (edits: MaskEdit[]) => void;
  /** The Marigold editor's composite is in flight. A Marigold draft's
   * autosave and the preparation reads both wait for it, so neither competes
   * with the frame the seller is looking at; a save that fell due meanwhile
   * goes the moment it lands. */
  setPreviewPending: (pending: boolean) => void;
  /** Saves now, without waiting for the debounce. Never rejects: the outcome
   * is in `save`. */
  flush: () => Promise<void>;
  /** Writes the draft even when nothing changed. Approving from the Preview
   * tab is a save: calibration status is derived from template.yaml, so the
   * observable act of approving is the file being written. */
  approve: () => Promise<void>;
  /** Discards the draft and mask edits and reads template.yaml again -- after
   * a conflict, or once a kind has been assigned. */
  reload: () => void;
  /** Saves anything pending, then queues preparation against the revision
   * the server now holds. `resetMasksForPhoto` drops the mask edits of
   * placements whose photo changed (their masks are what is being reset). */
  prepare: (action?: PreparationAction, resetMasksForPhoto?: boolean) => Promise<void>;
  cancelPreparation: () => Promise<void>;
  reloadPreparation: () => void;
}

/** Key-order-blind equality. The server answers with its own key order, so a
 * byte comparison would call an untouched document edited. */
function canonical(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(canonical);
  if (value !== null && typeof value === "object")
    return Object.fromEntries(
      Object.entries(value)
        .sort(([left], [right]) => left.localeCompare(right))
        .map(([key, item]) => [key, canonical(item)]),
    );
  return value;
}

function sameConfig(left: TemplateConfigState, right: TemplateConfigState): boolean {
  return JSON.stringify(canonical(left)) === JSON.stringify(canonical(right));
}

/** One opening of one template. A switch or a reload makes a new one, so a
 * response for an old one is recognised by identity -- no name or sequence
 * guards -- and a save still in flight for it finishes against it. */
interface Doc {
  name: string;
  load: "loading" | "ready" | "error";
  draft: TemplateConfigState | null;
  saved: TemplateConfigState | null;
  /** Sent as `If-Match`; advanced by every save and by an adopted baseline. */
  revision: string;
  fence: string;
  maskEdits: MaskEdit[];
  save: TemplateSaveState;
  previewPending: boolean;
  timer: ReturnType<typeof setTimeout> | null;
  /** The debounce ran out while held by a pending preview. */
  due: boolean;
}

interface View {
  name: string | null;
  load: TemplateLoad;
  config: TemplateConfigState | null;
  saved: TemplateConfigState | null;
  dirty: boolean;
  save: TemplateSaveState;
  maskEdits: MaskEdit[];
  calibrationRevision: string;
  previewPending: boolean;
  preparationVersion: number;
  preparing: boolean;
  actionError: string;
}

interface Connections {
  reloadPreparation: () => void;
  onCatalogChanged: ((select?: string) => void) | undefined;
}

const IDLE: TemplateSaveState = { kind: "idle" };
const NO_EDITS: MaskEdit[] = [];

function isDirty(doc: Doc): boolean {
  return (
    doc.draft !== null &&
    doc.saved !== null &&
    (!sameConfig(doc.draft, doc.saved) || doc.maskEdits.length > 0)
  );
}

/** The session's state outside React, so the save loop reads what is true
 * now rather than what a render closed over. Every field is per instance:
 * two sessions (two tabs' worth, or two tests) share nothing. */
class Session {
  private doc: Doc | null = null;
  private listeners = new Set<() => void>();
  /** Every save, one at a time and across templates: a flush on switch can
   * still be in flight when the next template is read, and must land first. */
  private writes: Promise<void> = Promise.resolve();
  /** Operations are objects shared by successive draft snapshots, so an
   * editor handing back a list built before a save landed would otherwise
   * send its strokes twice. */
  private committed = new WeakSet<MaskOperation>();
  /** Preparation jobs this session queued. Only their completion may move
   * the revision baseline: anyone else's is a change made elsewhere. */
  private own = new Set<string>();
  private preparation: Preparation | null = null;
  private version = 0;
  private preparing = false;
  private actionError = "";
  private connections: Connections = { reloadPreparation: () => {}, onCatalogChanged: undefined };
  private view: View = this.render();

  subscribe = (listener: () => void) => {
    this.listeners.add(listener);
    return () => void this.listeners.delete(listener);
  };

  snapshot = () => this.view;

  connect(connections: Connections) {
    this.connections = connections;
  }

  open(name: string | null) {
    if ((this.doc?.name ?? null) === name) return;
    if (this.doc) this.detach(this.doc);
    this.doc = name === null ? null : this.read(name);
    this.preparation = null;
    this.emit();
  }

  /** Unmount: whatever is pending goes now, as on a switch. */
  close() {
    if (this.doc) this.detach(this.doc);
  }

  observe(preparation: Preparation | null) {
    this.preparation = preparation;
    const job = preparation?.latest_job;
    const doc = this.doc;
    if (
      doc &&
      job?.phase === "completed" &&
      job.template === doc.name &&
      this.own.has(job.id) &&
      job.config_revision === preparation?.config_revision &&
      doc.fence !== job.config_revision
    ) {
      doc.fence = job.config_revision;
      this.emit();
    }
  }

  update = (config: TemplateConfigState) => {
    const doc = this.doc;
    if (doc?.load !== "ready") return;
    doc.draft = config;
    this.edited(doc);
  };

  setMaskEdits = (edits: MaskEdit[]) => {
    const doc = this.doc;
    if (doc?.load !== "ready") return;
    doc.maskEdits = this.uncommitted(edits);
    this.edited(doc);
  };

  setPreviewPending = (pending: boolean) => {
    const doc = this.doc;
    if (!doc || doc.previewPending === pending) return;
    doc.previewPending = pending;
    if (doc.due && !this.held(doc)) {
      doc.due = false;
      void this.enqueue(doc).catch(() => {});
    }
    this.emit();
  };

  flush = (): Promise<void> => {
    const doc = this.doc;
    if (!doc) return Promise.resolve();
    this.clearTimer(doc);
    return this.enqueue(doc).catch(() => {});
  };

  approve = (): Promise<void> => {
    const doc = this.doc;
    if (!doc) return Promise.resolve();
    this.clearTimer(doc);
    return this.enqueue(doc, true).catch(() => {});
  };

  reload = () => {
    const doc = this.doc;
    if (!doc) return;
    this.clearTimer(doc);
    this.doc = this.read(doc.name);
    this.emit();
  };

  prepare = async (action: PreparationAction = "prepare", resetMasksForPhoto = false) => {
    const doc = this.doc;
    if (!doc?.draft || this.preparing) return;
    this.preparing = true;
    this.actionError = "";
    this.emit();
    try {
      if (resetMasksForPhoto) {
        const stale = new Set(
          this.preparation?.placements
            .filter((p) => !p.mask_available && p.mask_reason?.toLowerCase().includes("photo"))
            .map((p) => p.placement_id),
        );
        doc.maskEdits = doc.maskEdits.filter((edit) => !stale.has(edit.placement_id ?? null));
        this.emit();
      }
      this.clearTimer(doc);
      // Rejects if the save does: preparing an older revision than the one
      // on screen would prepare the wrong thing.
      await this.enqueue(doc);
      const current = await getPreparation(doc.name);
      const submitted = await prepareTemplate({
        template: doc.name,
        config_revision: current.config_revision,
        request_id: crypto.randomUUID(),
        action,
        reset_masks_for_photo: resetMasksForPhoto,
        ...(action === "retry" && current.latest_job
          ? { previous_job: current.latest_job.id }
          : {}),
      });
      this.own.add(submitted.id);
      this.connections.reloadPreparation();
      this.connections.onCatalogChanged?.();
    } catch (e) {
      this.actionError = e instanceof Error ? e.message : "Preparation could not start";
    } finally {
      this.preparing = false;
      this.emit();
    }
  };

  cancelPreparation = async () => {
    const job = this.preparation?.active_job;
    if (!job) return;
    this.preparing = true;
    this.emit();
    try {
      await cancelPreparation(job.id);
      this.connections.reloadPreparation();
    } catch (e) {
      this.actionError = e instanceof Error ? e.message : "Cancellation failed";
    } finally {
      this.preparing = false;
      this.emit();
    }
  };

  private read(name: string): Doc {
    const doc: Doc = {
      name,
      load: "loading",
      draft: null,
      saved: null,
      revision: "",
      fence: "",
      maskEdits: NO_EDITS,
      save: IDLE,
      previewPending: false,
      timer: null,
      due: false,
    };
    // After any save still in flight, or the read could describe the file
    // from before it.
    void this.writes
      .then(() => getTemplateConfig(name))
      .then(
        (loaded) => {
          if (this.doc !== doc) return;
          doc.load = "ready";
          doc.draft = doc.saved = loaded?.config ?? null;
          doc.revision = doc.fence = loaded?.revision ?? "";
          doc.save = loaded ? { kind: "saved", savedAt: Date.parse(loaded.modifiedAt) } : IDLE;
          this.emit();
        },
        () => {
          if (this.doc !== doc) return;
          doc.load = "error";
          this.emit();
        },
      );
    return doc;
  }

  /** The same interval the listing editor uses, measured from the last edit. */
  private edited(doc: Doc) {
    this.clearTimer(doc);
    doc.timer = setTimeout(() => {
      doc.timer = null;
      if (this.held(doc)) doc.due = true;
      else void this.enqueue(doc).catch(() => {});
    }, AUTOSAVE_DEBOUNCE_MS);
    this.emit();
  }

  private held(doc: Doc): boolean {
    return doc.previewPending && doc.draft?.renderer.type === "marigold";
  }

  private clearTimer(doc: Doc) {
    if (doc.timer !== null) clearTimeout(doc.timer);
    doc.timer = null;
    doc.due = false;
  }

  /** A switch flushes rather than drops: the edit was made, and the template
   * it was made to still exists. Not held by a preview: its editor is going. */
  private detach(doc: Doc) {
    this.clearTimer(doc);
    void this.enqueue(doc).catch(() => {});
  }

  /** Queues a save of `doc` behind any in flight. It reads the draft when it
   * is sent, not when it is queued, so a burst of flushes collapses into the
   * one request the latest draft needs, and a queued one finding nothing
   * dirty sends nothing. */
  private enqueue(doc: Doc, always = false): Promise<void> {
    const run = this.writes.then(() => this.send(doc, always));
    this.writes = run.catch(() => {});
    return run;
  }

  private async send(doc: Doc, always: boolean) {
    if (doc.load !== "ready" || doc.draft === null || (!always && !isDirty(doc))) return;
    const config = doc.draft;
    const edits = this.uncommitted(doc.maskEdits);
    doc.save = { kind: "saving" };
    this.emit();
    try {
      await this.adoptPreparedBaseline(doc);
      const result = await saveTemplateConfig(doc.name, config, edits, doc.revision);
      if (result.revision) doc.revision = result.revision;
      for (const edit of edits) for (const op of edit.operations) this.committed.add(op);
      doc.saved = config;
      doc.maskEdits = this.uncommitted(doc.maskEdits);
      doc.fence = doc.revision;
      doc.save = { kind: "saved", savedAt: Date.now() };
      const current = this.doc === doc;
      // A save rebuilds CPU-side maps, so preparation is read again.
      if (current) this.version += 1;
      this.emit();
      // Whether the template still needs calibration may have changed, and
      // the rail is what shows that. Only the open template is reselected: a
      // flushed one finishing late must not pull the rail back to it.
      this.connections.onCatalogChanged?.(current ? doc.name : undefined);
    } catch (e) {
      doc.save =
        e instanceof TemplateConflictError
          ? { kind: "conflict", message: e.message }
          : { kind: "failed", message: e instanceof Error ? e.message : "Save failed" };
      this.emit();
      throw e;
    }
  }

  /** A completed preparation this session queued rewrites template.yaml's
   * revision without changing what this session saved. Adopt that revision
   * as the `If-Match` baseline -- but only while the disk still holds exactly
   * the saved document at exactly the prepared revision, so an external edit
   * made since is still refused as a conflict. */
  private async adoptPreparedBaseline(doc: Doc) {
    const preparation = this.preparation;
    const job = preparation?.latest_job;
    if (
      !job ||
      job.phase !== "completed" ||
      job.template !== doc.name ||
      !this.own.has(job.id) ||
      job.config_revision !== preparation?.config_revision ||
      doc.saved === null
    )
      return;
    if (doc.revision !== job.config_revision) {
      const disk = await getTemplateConfig(doc.name).catch(() => null);
      if (disk?.revision !== job.config_revision || !sameConfig(disk.config, doc.saved)) return;
      doc.revision = job.config_revision;
    }
    this.own.delete(job.id);
  }

  private uncommitted(edits: MaskEdit[]): MaskEdit[] {
    const remaining = edits
      .map((edit) => ({
        ...edit,
        operations: edit.operations.filter((op) => !this.committed.has(op)),
      }))
      .filter((edit) => edit.operations.length > 0);
    return remaining.length ? remaining : NO_EDITS;
  }

  private emit() {
    this.view = this.render();
    for (const listener of this.listeners) listener();
  }

  private render(): View {
    const doc = this.doc;
    const ready = doc?.load === "ready";
    return {
      name: doc?.name ?? null,
      load: doc?.load ?? "none",
      config: ready ? doc.draft : null,
      saved: ready ? doc.saved : null,
      dirty: doc ? isDirty(doc) : false,
      save: doc?.save ?? IDLE,
      maskEdits: doc?.maskEdits ?? NO_EDITS,
      calibrationRevision: doc?.fence ?? "",
      previewPending: doc?.previewPending ?? false,
      preparationVersion: this.version,
      preparing: this.preparing,
      actionError: this.actionError,
    };
  }
}

/**
 * The calibrator's authoring session for the selected template: reading its
 * template.yaml, the draft against what was saved, autosave, the revision
 * every save names, mask strokes awaiting commit, and the preparation that
 * follows a save.
 *
 * Autosave follows the listing editor's rules ({@link useAutosave}): a
 * debounce from the last edit, one request in flight at a time, and pending
 * edits flushed -- not dropped -- on a template switch and on unmount. It
 * does not share that hook's code: that one merges listing patches and moves
 * a listing through create and rename, this one PUTs a whole document over a
 * revision and can be held by a preview.
 *
 * `onCatalogChanged` is told when a save or a queued preparation may have
 * changed the template list's facts, with the name to keep selected.
 */
export function useTemplateSession(
  name: string | null,
  options: { onCatalogChanged?: (select?: string) => void } = {},
): TemplateSession {
  const [session] = useState(() => new Session());
  const stored = useSyncExternalStore(session.subscribe, session.snapshot);
  // Until the effect below opens `name`, the store still holds the previous
  // template; it must not render under the new name.
  const view: View =
    stored.name === name
      ? stored
      : {
          ...stored,
          name,
          load: name === null ? "none" : "loading",
          config: null,
          saved: null,
          dirty: false,
          save: IDLE,
          maskEdits: NO_EDITS,
          calibrationRevision: "",
          previewPending: false,
        };
  const {
    preparation,
    error: mapError,
    reload: reloadPreparation,
  } = usePreparation(name, view.preparationVersion, view.previewPending);
  const { onCatalogChanged } = options;

  useEffect(() => {
    session.connect({ reloadPreparation, onCatalogChanged });
  }, [session, reloadPreparation, onCatalogChanged]);
  useEffect(() => session.open(name), [session, name]);
  useEffect(() => session.observe(preparation), [session, preparation]);
  useEffect(() => () => session.close(), [session]);

  return {
    load: view.load,
    config: view.config,
    saved: view.saved,
    dirty: view.dirty,
    save: view.save,
    maskEdits: view.maskEdits,
    calibrationRevision: view.calibrationRevision,
    preparation,
    preparationError: view.actionError || mapError,
    preparing: view.preparing,
    update: session.update,
    setMaskEdits: session.setMaskEdits,
    setPreviewPending: session.setPreviewPending,
    flush: session.flush,
    approve: session.approve,
    reload: session.reload,
    prepare: session.prepare,
    cancelPreparation: session.cancelPreparation,
    reloadPreparation,
  };
}

import { templateDesignPreviewUrl, templatePhotoUrl, templateThumbnailUrl } from "./api/calibrator";
import {
  commonMediaFileUrl,
  commonMediaThumbnailUrl,
  listingMediaFileUrl,
  listingMediaThumbnailUrl,
  listingScenePreviewUrl,
} from "./api/listings";
import {
  listingTemplateMediaFileUrl,
  listingTemplateMediaThumbnailUrl,
} from "./api/listingTemplates";
import type { MediaEntry, TemplateSummary } from "./types";

/**
 * What `media:` holds, and what it looks like.
 *
 * `media:` carries two shapes in one list (`config/listing.py`'s `MediaEntry`):
 * a `{template, colour}` entry the tool renders, and a file ref uploaded
 * as-is -- a shared file under `common-media/`, or one of the listing's own
 * spelled `./…` -- which may be an image or a video. Every
 * question about either one -- what is it called, what kind is it, is it
 * already in the listing, which picture shows it, which file on disk does it
 * come from -- is answered here.
 *
 * It exists because those answers were spread across whichever tab first
 * needed them. Six near-identical URL builders lived in two api modules;
 * "strip the directory and the `.png`" was written three times with three
 * different regexes; and "composite the design if there is one, otherwise show
 * the bare photo" was written twice, in `ImagesTab` and `VariantsTab`, with
 * *different* fallback orders. A component that wants a picture of something
 * now needs to know one function, not which of two api modules to import from
 * and which of five builders applies.
 *
 * The api modules keep their builders: those are the HTTP surface, one function
 * per endpoint, and this is the domain question layered over them.
 */

/** How big a picture the caller is asking for.
 *
 * `tile` is the 160px-capped thumbnail a row of them is picked from; `full` is
 * the photo's own resolution, for the one image being *judged* -- a preview
 * pane or a lightbox. They are different endpoints, not a query parameter, so
 * this is the one place the choice is made.
 */
export type PictureSize = "tile" | "full";

/** A shared asset's name, from the bare ref a listing stores.
 *
 * Filename-derived rather than looked up, so a reel tile still labels itself
 * when the file has been deleted from `common-media/` since the listing named
 * it. One implementation: the design strip and the reel each had their own.
 */
export function refName(ref: string): string {
  const file = ref.split("/").pop() ?? ref;
  return file.replace(/\.[^.]+$/, "");
}

/** A shared ref's path under `common-media/` -- what the picture endpoints
 * take. The whole path, not the stem: a shared file may be a JPEG and may sit
 * in a subdirectory, and only its full path says which file it is. */
function sharedName(ref: string): string {
  const prefix = "common-media/";
  return ref.startsWith(prefix) ? ref.slice(prefix.length) : ref;
}

/** A listing's own file (ADR-0046's `./` root) rather than a workspace one. */
function isListingLocal(ref: string): boolean {
  return ref.startsWith("./");
}

/** Whether an entry is a picture or a clip -- `config/media.py`'s
 * `media_kind`, mirrored.
 *
 * A template entry is always an image (a render is a PNG) and a file ref is a
 * video by its extension alone, case-insensitively, since a phone names its
 * clips `IMG_1234.MOV`. Every other ref is an image: a listing whose `media:`
 * names an unknown type is refused on load, so it never reaches the browser.
 */
export function mediaKind(entry: MediaEntry): "image" | "video" {
  if (typeof entry !== "string") return "image";
  return /\.(mp4|mov)$/i.test(entry) ? "video" : "image";
}

/**
 * Which saved listing a scene render resolves its artwork from, and a
 * signature of that listing's saved design (A35).
 *
 * Every layer of a scene prints the file its colour resolves to -- a
 * light/dark pair shows both files in one multi-colour scene -- so a picture
 * is asked of the listing, not of one design name. It is the *saved* listing
 * the server reads (multi-artwork plan, *Editor previews*), which is why the
 * signature is `design_content_hash`: it comes from the last server response,
 * so it changes when a design edit has landed rather than when it was made,
 * and a URL is never cached holding the picture from before the save.
 *
 * `null` for an unnamed draft, which has no saved listing to resolve from,
 * and for a listing with no design, which would only print nothing.
 */
export interface SceneSource {
  listing: string;
  version: string;
}

export function sceneSource(
  listing: string,
  designVersion: string | null | undefined,
): SceneSource | null {
  if (listing === "" || designVersion === null || designVersion === undefined) return null;
  return { listing, version: designVersion };
}

/** What to call one entry, in a tile label, a lightbox caption or an aria-label. */
export function mediaLabel(entry: MediaEntry): string {
  if (typeof entry === "string") return refName(entry);
  return entry.colour ? `${entry.template} · ${entry.colour}` : entry.template;
}

/** Is this template/colour pair already in `media:`?
 *
 * `(entry.colour ?? null) === colour` rather than `==`, because a
 * `multiple`/`single` entry's absent colour and an explicit `null` are the
 * same thing and `undefined` is not.
 */
export function isInMedia(
  media: readonly MediaEntry[],
  template: string,
  colour: string | null,
): boolean {
  return media.some(
    (m) => typeof m !== "string" && m.template === template && (m.colour ?? null) === colour,
  );
}

/** Colours this listing sells that `template` has no entry for.
 *
 * Driven by `colors:`, not by the template's own photo set -- a swatch is owed
 * for every colour on sale, and one the template cannot supply is exactly what
 * the coverage warning is for.
 */
export function missingColours(
  media: readonly MediaEntry[],
  colors: readonly string[],
  template: string,
): string[] {
  return colors.filter((c) => !isInMedia(media, template, c));
}

/**
 * The picture for one thing `media:` can hold.
 *
 * A template entry is a *render*: each layer printing the file its colour
 * resolves to, composited onto the template's saved geometry -- or, for a
 * listing template, its preview design on every layer. With no `artwork` it is
 * the bare inkless photo. A shared asset is
 * already exactly the file Etsy would receive, so it is served as-is.
 *
 * At `tile` size a template entry is always the bare thumbnail, never a render:
 * a tile is picked out of a row, and running the real pipeline once per tile
 * would cost a render per listing image just to open the tab. The thumbnail
 * still takes the colour -- without it a colour-matrix set answers with the
 * same photo every time, and a reel of eight identical tiles under eight
 * different colour labels is worse than no picture at all.
 */
export function pictureFor(
  entry: MediaEntry,
  artwork: Artwork | null,
  size: PictureSize = "full",
  owner: MediaOwner | string | null = null,
): string {
  if (typeof entry === "string") return filePicture(entry, size, ownerOf(owner));
  return templatePicture(entry.template, entry.colour ?? null, artwork, size);
}

/** What a render composites onto a template's photo: a saved listing, each
 * layer printing the file its colour resolves to ({@link SceneSource}); or,
 * in the listing-template editor where there is no artwork (UI doc §3), one
 * design picked only to preview with -- a workspace design by name, or a
 * calibrator test design by its library id. An object for the test design so
 * the two names cannot be mistaken for each other: they name files in
 * different directories. */
export type Artwork = SceneSource | string | { testDesign: string };

/** Whose directory a `./` ref is resolved against: a listing's, or a listing
 * template's (ADR-0047) -- the one other thing that owns files of its own.
 *
 * `copies` is for a listing template not saved yet (the *name it* state, UI
 * doc §1): its `./assets/…` refs are only a plan until the save copies them,
 * so each is drawn from the ref its source (`name`) still keeps it under. */
export interface MediaOwner {
  kind: "listing" | "listing-template";
  name: string;
  copies?: Readonly<Record<string, string>>;
}

/** A bare string is a listing's name -- what every listing caller passes. */
function ownerOf(owner: MediaOwner | string | null): MediaOwner | null {
  if (owner === null || owner === "") return null;
  return typeof owner === "string" ? { kind: "listing", name: owner } : owner;
}

/**
 * The picture for a file ref, from whichever of ADR-0046's two roots it names.
 *
 * A `./` ref is one of `owner`'s own files; with no owner -- the editor's
 * unnamed draft, which has no directory -- it names nothing, and the answer is
 * the empty string rather than a URL that would `404`. A video is served as
 * its file at either size: the thumbnail endpoint answers `415` for one,
 * because a muted `<video preload="metadata">` draws its own first frame.
 */
function filePicture(ref: string, size: PictureSize, owner: MediaOwner | null): string {
  const tile = size === "tile" && mediaKind(ref) === "image";
  if (isListingLocal(ref)) {
    if (owner === null) return "";
    const name = (owner.copies?.[ref] ?? ref).slice(2);
    if (owner.kind === "listing-template") {
      return tile
        ? listingTemplateMediaThumbnailUrl(owner.name, name)
        : listingTemplateMediaFileUrl(owner.name, name);
    }
    return tile
      ? listingMediaThumbnailUrl(owner.name, name)
      : listingMediaFileUrl(owner.name, name);
  }
  const name = sharedName(ref);
  return tile ? commonMediaThumbnailUrl(name) : commonMediaFileUrl(name);
}

/** A tile-sized picture of one gallery entry, for a listing-template card:
 * {@link pictureFor} at `tile` size, whoever owns the `./` files. */
export function ownedTile(entry: MediaEntry, owner: MediaOwner): string {
  return pictureFor(entry, null, "tile", owner);
}

/** The same, for a template/colour the locator is offering but the listing has
 * not taken yet -- there is no `MediaEntry` for it to be asked about. */
export function templatePicture(
  template: string,
  colour: string | null,
  artwork: Artwork | null,
  size: PictureSize = "full",
): string {
  if (size === "tile") return templateThumbnailUrl(template, colour);
  if (artwork === null) return templatePhotoUrl(template, colour);
  if (typeof artwork === "string" || "testDesign" in artwork) {
    return templateDesignPreviewUrl(template, artwork, colour);
  }
  return listingScenePreviewUrl(artwork.listing, template, colour, artwork.version);
}

/**
 * The file on disk an entry renders from, for the caption under a preview.
 *
 * Served by `GET /api/templates` (`TemplateSummary.photos`) rather than
 * composed here from ADR-0004's convention. That matters for the one layout the
 * convention does not describe: a vendor pack delivered as
 * `{template}-{colour}.png` is resolved by `Workspace.template_base_image`'s
 * trailing-segment fallback, and a caption derived from the convention alone
 * named a file that is not there.
 *
 * The plain convention is still the fallback, for a colour the server did not
 * list -- a colour the listing sells that this template has no photo for. That
 * path does not exist either, but naming the file the template *would* need is
 * the useful thing to say about a missing one.
 */
export function scenePath(
  template: TemplateSummary | undefined,
  templateName: string,
  colour: string | null,
): string {
  const served = template?.photos.find((p) => (p.colour ?? null) === colour);
  if (served !== undefined) return served.file;
  return `mockup-templates/${templateName}/${colour ?? "scene"}.png`;
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { listListings } from "../api/listings";
import { cancelRun, createRun, getRun, markRunSeen } from "../api/runs";
import { stageWillRun, type ListingSummary, type RunDetail } from "../types";
import { BatchAggregateStages } from "./batchDeploy/BatchAggregateStages";
import { BatchListingDrawer } from "./batchDeploy/BatchListingDrawer";
import { BatchListingGroups } from "./batchDeploy/BatchListingGroups";
import {
  batchDeployState,
  applyBatchRunEvent,
  type BatchRunSource,
  initialBatchDeployState,
  type BatchDeployState,
  type BatchListingState,
} from "./batchDeploy/batchDeployState";
import { batchResult, planGroup } from "./batchDeploy/batchDeployPresentation";
import { openRunStream, type RunStreamHandle } from "./deploy/runStream";
import { MARK_SEEN_GRACE_MS, TERMINAL_PHASES } from "./deploy/runPhases";

function formatGeneratedAt(value: string | null): string {
  if (value === null) return "";
  const date = new Date(value);
  return Number.isNaN(date.valueOf())
    ? ""
    : `Generated ${new Intl.DateTimeFormat(undefined, { dateStyle: "medium", timeStyle: "short" }).format(date)}`;
}

function planFor(listing: BatchListingState) {
  return listing.plan ?? listing.reviewedPlan;
}

function reviewedListings(state: BatchDeployState): BatchListingState[] {
  return state.reviewedListingOrder
    .map((listing) => state.listings[listing])
    .filter((listing): listing is BatchListingState => listing?.reviewedPlan !== null);
}

function requiredPreviewKeys(listings: readonly BatchListingState[]): string[] {
  const keys: string[] = [];
  for (const listing of listings) {
    const render = planFor(listing)?.stage_plans.find((stage) => stage.stage === "render");
    const snapshot = render?.snapshot;
    for (const scene of snapshot?.scenes ?? []) {
      if (scene.state !== "cached" && !scene.preview) {
        keys.push(`${listing.listing}|${scene.template}|${scene.colour ?? ""}`);
      }
    }
  }
  return keys;
}

function planCounts(listings: readonly BatchListingState[]) {
  const counts = { add: 0, edit: 0, remove: 0 };
  for (const listing of listings) {
    const group = planGroup(planFor(listing), listing.planFailure);
    if (group === "add") counts.add += 1;
    if (group === "change") counts.edit += 1;
    if (group === "remove") counts.remove += 1;
  }
  return counts;
}

function isPlanning(phase: BatchDeployState["phase"]): boolean {
  return (
    phase === "queued" || phase === "planning" || phase === "planned" || phase === "previewing"
  );
}

function isTerminalApply(state: BatchDeployState): boolean {
  return state.applyStarted && TERMINAL_PHASES.has(state.phase);
}

function countLabel(count: number, singular: string, plural = `${singular}s`): string {
  return `${count} ${count === 1 ? singular : plural}`;
}

/** The stable workspace route. It owns only run attachment and page composition;
 * event meaning remains in batchDeployState and all change meaning remains in
 * the engine-provided plans. A workspace apply keeps its linked review as the
 * approval surface and contributes only a live runtime overlay. */
export function BatchDeployPage() {
  const { runId = "" } = useParams<{ runId: string }>();
  const navigate = useNavigate();
  const [run, setRun] = useState<RunDetail | null>(null);
  const [state, setState] = useState<BatchDeployState>(initialBatchDeployState);
  const [summaries, setSummaries] = useState<ListingSummary[]>([]);
  const [selectedListing, setSelectedListing] = useState<string | null>(null);
  const [status, setStatus] = useState("");
  const streamRef = useRef<RunStreamHandle | null>(null);
  const attachRef = useRef<(id: string) => void>(() => {});
  const activeRunRef = useRef<string | null>(null);
  const seenRef = useRef<string | null>(null);
  const applyStartRef = useRef<Promise<void> | null>(null);
  const leavingRef = useRef(false);
  const [applyPending, setApplyPending] = useState(false);

  const openStream = useCallback((id: string, lastEventId: number, source: BatchRunSource) => {
    streamRef.current?.close();
    streamRef.current = openRunStream(id, {
      lastEventId,
      onEvent: (event) => {
        if (activeRunRef.current !== id) return;
        setState((current) => applyBatchRunEvent(current, event, source));
      },
      onError: () => {
        if (activeRunRef.current !== id) return;
        setStatus("Connection lost. Reconnecting…");
        void attachRef.current(id);
      },
    });
  }, []);

  const attach = useCallback(
    async (id: string) => {
      try {
        const loaded = await getRun(id);
        if (activeRunRef.current !== id) return;
        if (loaded.scope !== "workspace") {
          streamRef.current?.close();
          setRun(null);
          setState(initialBatchDeployState);
          setSelectedListing(null);
          setStatus("This URL is not a workspace planning run. Return to Listings.");
          return;
        }
        let reviewed = loaded;
        if (loaded.kind === "apply") {
          if (loaded.reviewed_run_id === null) throw new Error("apply run has no reviewed plan");
          reviewed = await getRun(loaded.reviewed_run_id);
          if (
            reviewed.scope !== "workspace" ||
            reviewed.kind !== "plan" ||
            reviewed.phase !== "ready"
          ) {
            throw new Error("apply run has no ready workspace review");
          }
        }
        setRun(loaded);
        setState(
          loaded.kind === "apply"
            ? batchDeployState(reviewed.events, loaded.events)
            : batchDeployState(loaded.events),
        );
        const lastEventId = loaded.events.at(-1)?.id ?? 0;
        if (!TERMINAL_PHASES.has(loaded.phase))
          openStream(id, lastEventId, loaded.kind === "apply" ? "apply" : "review");
        else streamRef.current?.close();
        setStatus("");
      } catch {
        if (activeRunRef.current === id) {
          setStatus("Could not load this batch run. Return to Listings and try again.");
        }
      }
    },
    [openStream],
  );

  useEffect(() => {
    attachRef.current = (id) => void attach(id);
  }, [attach]);

  useEffect(() => {
    activeRunRef.current = runId;
    seenRef.current = null;
    let current = true;
    void listListings()
      .then((loaded) => {
        if (current) setSummaries(loaded);
      })
      .catch(() => {
        if (current) setStatus("Could not load listing details for this review.");
      });
    void Promise.resolve().then(() => attach(runId));
    return () => {
      current = false;
      if (activeRunRef.current === runId) activeRunRef.current = null;
      streamRef.current?.close();
    };
  }, [attach, runId]);

  useEffect(() => {
    if (
      run === null ||
      run.id !== runId ||
      run.seen ||
      seenRef.current === run.id ||
      !TERMINAL_PHASES.has(state.phase)
    ) {
      return;
    }
    const id = run.id;
    const markSeen = () => {
      if (leavingRef.current) return;
      seenRef.current = id;
      void markRunSeen(id);
    };

    // A very small workspace apply can finish before the user's immediate
    // Back click is honoured -- Apply's own re-navigate to this apply run's
    // URL (handleApply) lands first and attaches here already terminal.
    // Give that exit intent a short window so Listings can still offer View
    // batch result; a result the user stays on is marked seen normally.
    if (!isTerminalApply(state)) {
      markSeen();
      return;
    }
    const timer = window.setTimeout(markSeen, MARK_SEEN_GRACE_MS);
    return () => window.clearTimeout(timer);
  }, [run, runId, state]);

  useEffect(() => {
    if (!isTerminalApply(state)) return;
    let current = true;
    void listListings()
      .then((loaded) => {
        if (current) setSummaries(loaded);
      })
      .catch(() => {
        if (current) setStatus("Could not refresh listing statuses after the batch result.");
      });
    return () => {
      current = false;
    };
  }, [state]);

  // Until this URL's detail has arrived, keep a previous route's plan out of
  // the approval surface. The state itself is reset by the detail replay, so
  // this also avoids synchronous setState calls in the route effect.
  const visibleState = run?.id === runId ? state : initialBatchDeployState;
  const listings = useMemo(() => reviewedListings(visibleState), [visibleState]);
  const plans = useMemo(
    () =>
      listings
        .map(planFor)
        .filter((plan): plan is NonNullable<ReturnType<typeof planFor>> => plan !== null),
    [listings],
  );
  const counts = useMemo(() => planCounts(listings), [listings]);
  const requiredPreviews = useMemo(() => requiredPreviewKeys(listings), [listings]);
  const previewsReady = requiredPreviews.every((key) => visibleState.previewsRendered.has(key));
  const runnableCount = plans.filter((plan) => plan.stage_plans.some(stageWillRun)).length;
  const nothingToDo =
    visibleState.phase === "ready" &&
    !Object.values(visibleState.listings).some(
      (listing) => listing.planFailure !== null || listing.failureMessage !== null,
    ) &&
    (plans.length === 0 ||
      plans.every((plan) => plan.stage_plans.every((stage) => !stageWillRun(stage))));
  const summaryByName = useMemo(
    () => new Map(summaries.map((summary) => [summary.name, summary])),
    [summaries],
  );
  const selected =
    selectedListing === null ? null : (visibleState.listings[selectedListing] ?? null);
  const selectedSummary =
    selectedListing === null ? null : (summaryByName.get(selectedListing) ?? null);
  const selectedPlan = selected === null ? null : planFor(selected);

  const result = batchResult(visibleState);
  const terminalApply = isTerminalApply(visibleState);
  const applying = visibleState.applyStarted && !terminalApply;

  const followCreatedRun = useCallback(
    async (created: Awaited<ReturnType<typeof createRun>>) => {
      if (created.kind === "conflict") {
        const conflict = await getRun(created.activeRun);
        if (conflict.scope === "workspace") {
          navigate(`/listings/deploy/${encodeURIComponent(conflict.id)}`, { replace: true });
        } else {
          setStatus("A listing deploy is already running. Return to Listings to follow it.");
        }
      } else {
        navigate(`/listings/deploy/${encodeURIComponent(created.run.id)}`, { replace: true });
      }
    },
    [navigate],
  );

  const startWorkspacePlan = useCallback(async () => {
    try {
      const created = await createRun({ kind: "plan", scope: "workspace" });
      await followCreatedRun(created);
    } catch {
      setStatus("Could not start a fresh workspace plan.");
    }
  }, [followCreatedRun]);

  async function handleApply() {
    if (run?.kind !== "plan" || visibleState.phase !== "ready" || !previewsReady) return;
    const reviewed = reviewedListings(visibleState);
    const listingsToApply = reviewed.filter((listing) => listing.fingerprint !== null);
    if (listingsToApply.length !== reviewed.length) return;
    setSelectedListing(null);
    const pending = (async () => {
      try {
        const created = await createRun({
          kind: "apply",
          scope: "workspace",
          listings: listingsToApply.map((listing) => listing.listing),
          expect: Object.fromEntries(
            listingsToApply.map((listing) => [listing.listing, listing.fingerprint as string]),
          ),
          reviewed_run_id: run.id,
        });
        await followCreatedRun(created);
      } catch {
        setStatus("Could not start the reviewed workspace apply.");
      }
    })();
    applyStartRef.current = pending;
    setApplyPending(true);
    try {
      await pending;
    } finally {
      if (applyStartRef.current === pending) applyStartRef.current = null;
      setApplyPending(false);
    }
  }

  async function handleBack() {
    leavingRef.current = true;
    await applyStartRef.current;
    if (run?.id === runId && run.kind === "plan" && isPlanning(visibleState.phase)) {
      await cancelRun(run.id).catch(() => false);
    }
    streamRef.current?.close();
    navigate("/listings");
  }

  const phase = visibleState.phase;
  const planning = !visibleState.applyStarted && isPlanning(phase);
  const headerTitle = planning
    ? "Planning all listings…"
    : applying
      ? "Applying all changes…"
      : terminalApply
        ? "Batch result"
        : "Review all changes";
  const planTimestamp = formatGeneratedAt(visibleState.generatedAt);
  const showReview =
    planning ||
    visibleState.phase === "previewing" ||
    visibleState.phase === "ready" ||
    applying ||
    terminalApply;
  const showPlanningFailure = visibleState.phase === "failed" && !visibleState.applyStarted;

  return (
    <div className="editor batch-deploy-page">
      <div className="page-head">
        <button
          type="button"
          className="btn btn-secondary dv-back"
          onClick={() => void handleBack()}
        >
          ← Back to listings
        </button>
        <span className="page-head__sep">/</span>
        <h1 className="page-head__title">{headerTitle}</h1>
        <span className="page-head__meta">{planTimestamp}</span>
      </div>

      {status !== "" && (
        <p className="app__status" role="status">
          {status}
        </p>
      )}

      {planning && (
        <div className="dv-planning" role="status">
          <span className="dv-spinner" aria-hidden="true" />
          <div>
            <h2>Planning all listings…</h2>
            <p>
              Reading Printify and Etsy to work out what apply would change across this workspace.
              Nothing is written yet.
            </p>
          </div>
        </div>
      )}

      {phase === "previewing" && (
        <div className="dv-planning" role="status">
          <span className="dv-spinner" aria-hidden="true" />
          <div>
            <h2>Rendering previews…</h2>
            <p>
              Preview images are being prepared for review. Apply stays disabled until they are
              ready.
            </p>
          </div>
        </div>
      )}

      {showPlanningFailure && (
        <div className="dv-callout dv-callout--blocked" role="alert">
          <strong>Planning could not finish.</strong>
          <p>Plan again to retry the workspace read, or return to Listings.</p>
        </div>
      )}

      {applying && (
        <div className="dv-callout dv-callout--drift" role="status">
          <strong>Applying reviewed changes.</strong>
          <p>Listings are updated one at a time and the run continues if one listing fails.</p>
        </div>
      )}

      {terminalApply && (
        <div
          className={`dv-callout ${result.partial ? "dv-callout--drift" : result.failed.length || result.stale.length ? "dv-callout--blocked" : "dv-callout--ok"}`}
          role={result.partial || result.failed.length || result.stale.length ? "alert" : "status"}
        >
          <strong>
            {result.partial
              ? "Batch partially applied."
              : result.stale.length > 0
                ? "Some listings became stale."
                : result.failed.length > 0
                  ? "Batch apply failed."
                  : "All planned work finished."}
          </strong>
          <p>
            {countLabel(result.succeeded.length, "listing")} succeeded
            {result.failed.length > 0 && ` · ${countLabel(result.failed.length, "listing")} failed`}
            {result.stale.length > 0 && ` · ${countLabel(result.stale.length, "listing")} stale`}
            {result.blocked.length > 0 &&
              ` · ${countLabel(result.blocked.length, "listing")} blocked`}
          </p>
        </div>
      )}

      {nothingToDo ? (
        <div className="dv-callout dv-callout--ok batch-deploy-empty" role="status">
          <div>
            <strong>Everything is up to date.</strong>
            <p>The all-listings plan found no changes to apply.</p>
          </div>
        </div>
      ) : (
        <>
          {visibleState.phase === "ready" && !visibleState.applyStarted && (
            <section className="batch-review-summary" aria-labelledby="batch-review-heading">
              <div>
                <span className="dv-eyebrow">Authoritative review</span>
                <h2 id="batch-review-heading">{listings.length} affected listings</h2>
                <p>
                  {counts.add} to add · {counts.edit} to edit · {counts.remove} to remove
                </p>
              </div>
              <span className="batch-review-summary__previews">
                {requiredPreviews.length === 0
                  ? "All required previews ready"
                  : `${requiredPreviews.filter((key) => visibleState.previewsRendered.has(key)).length} of ${requiredPreviews.length} previews ready`}
              </span>
            </section>
          )}

          {showReview && (
            <>
              <BatchAggregateStages
                plans={plans}
                listings={listings}
                onOpenListing={setSelectedListing}
              />
              <BatchListingGroups
                listings={Object.values(visibleState.listings)}
                onOpenListing={setSelectedListing}
              />
            </>
          )}
        </>
      )}

      <div className="dv-foot batch-deploy-footer">
        <p>
          {applying
            ? "Apply runs exactly this plan, one listing at a time."
            : terminalApply
              ? result.partial || result.failed.length > 0 || result.stale.length > 0
                ? "Review the affected listings, then plan again for the remaining work."
                : "All planned work finished."
              : phase === "ready" && runnableCount > 0
                ? previewsReady
                  ? "Apply runs exactly this plan, one listing at a time."
                  : `Preview images before applying (${requiredPreviews.filter((key) => visibleState.previewsRendered.has(key)).length} of ${requiredPreviews.length})…`
                : nothingToDo
                  ? "No remote changes were found."
                  : "Apply unlocks once the reviewed previews are ready."}
        </p>
        {applying ? (
          <button type="button" className="btn btn-primary dv-big" disabled>
            Applying…
          </button>
        ) : showPlanningFailure ? (
          <button
            type="button"
            className="btn btn-primary dv-big"
            onClick={() => void startWorkspacePlan()}
          >
            Try again
          </button>
        ) : nothingToDo ? (
          <button
            type="button"
            className="btn btn-primary dv-big"
            onClick={() => void startWorkspacePlan()}
          >
            Plan again
          </button>
        ) : terminalApply ? (
          <button
            type="button"
            className="btn btn-primary dv-big"
            onClick={() => void startWorkspacePlan()}
          >
            Plan again
          </button>
        ) : (
          <button
            type="button"
            className="btn btn-primary dv-big"
            disabled={
              applyPending ||
              phase !== "ready" ||
              runnableCount === 0 ||
              !previewsReady ||
              nothingToDo
            }
            onClick={() => void handleApply()}
            aria-label={`Apply ${runnableCount} listing${runnableCount === 1 ? "" : "s"}`}
            title={
              previewsReady
                ? "Applying reviewed plans is the next step"
                : "Preview images before applying"
            }
          >
            Apply {runnableCount} listing{runnableCount === 1 ? "" : "s"}
          </button>
        )}
      </div>

      <BatchListingDrawer
        open={selected !== null}
        listing={selected}
        summary={selectedSummary}
        mode={applying ? "applying" : terminalApply ? "applied" : "review"}
        previewsRendered={visibleState.previewsRendered}
        renderSnapshot={
          selectedPlan?.stage_plans.find((stage) => stage.stage === "render")?.snapshot ?? null
        }
        onClose={() => setSelectedListing(null)}
      />
    </div>
  );
}

