import { CheckCircleIcon } from "@phosphor-icons/react/dist/csr/CheckCircle";
import { FileZipIcon } from "@phosphor-icons/react/dist/csr/FileZip";
import { WarningCircleIcon } from "@phosphor-icons/react/dist/csr/WarningCircle";
import { useEffect, useRef, useState, type DragEvent } from "react";
import { Link, useLocation, useNavigate, useSearchParams } from "react-router-dom";
import { stageDesigns, StagingRefused, type StagingRefusal } from "../api/batches";
import { listListingTemplates } from "../api/listingTemplates";
import { ownedTile } from "../media";
import type { ListingTemplateSummary } from "../types";

/**
 * New batch (UI doc §4; the `new-batch` and `staging-refused` frames): pick
 * one listing template, then drop designs. A drop is posted straight to
 * staging and lands on the staging review; a refused one stays here with the
 * reason and the remedy, and nothing was kept. `?template=` preselects, as
 * Start batch on a card does.
 *
 * One ZIP or loose PNGs (spec, *Accepted input*). What may be dropped
 * together is the server's to judge: two ZIPs, a ZIP with loose files and
 * an unsafe archive come back as refusals, shown like any other.
 *
 * A drop on a listing-template card that the server refuses lands here too,
 * the refusal in the navigation's state (UI doc §2, closed question 2), so
 * a card has no refusal state of its own.
 */

/** A refusal, and the names of the files it was about. Names rather than
 * the files: it may arrive in history state from a card drop. */
export interface Refused extends StagingRefusal {
  files: string[];
}

function refusedHeading(files: string[]): string {
  const [only] = files;
  return files.length === 1 && only ? `${only} was not staged.` : "These files were not staged.";
}

export function NewBatchPage() {
  const navigate = useNavigate();
  const [params] = useSearchParams();
  const handed = (useLocation().state as { refused?: Refused } | null)?.refused ?? null;
  const [templates, setTemplates] = useState<ListingTemplateSummary[] | null>(null);
  const [chosen, setChosen] = useState(params.get("template") ?? "");
  const [refused, setRefused] = useState<Refused | null>(handed);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const input = useRef<HTMLInputElement>(null);

  useEffect(() => {
    let current = true;
    listListingTemplates()
      .then((loaded) => {
        if (!current) return;
        setTemplates(loaded);
        setChosen((name) => (loaded.some((t) => t.name === name) ? name : (loaded[0]?.name ?? "")));
      })
      .catch(() => current && setError("Could not load listing templates"));
    return () => {
      current = false;
    };
  }, []);

  function stage(files: File[]) {
    if (files.length === 0 || !chosen || busy) return;
    setBusy(true);
    setError("");
    stageDesigns(chosen, files)
      .then((session) => navigate(`/batches/staging/${session.id}`))
      .catch((exc: unknown) => {
        setBusy(false);
        if (exc instanceof StagingRefused) {
          setRefused({ ...exc.refusal, files: files.map((file) => file.name) });
        } else setError(exc instanceof Error ? exc.message : "The designs could not be staged.");
      });
  }

  function onDrop(event: DragEvent<HTMLDivElement>) {
    event.preventDefault();
    stage(Array.from(event.dataTransfer.files));
  }

  const template = templates?.find((t) => t.name === chosen);
  const minimum = template?.design_minimum;

  return (
    <>
      <div className="page-head">
        <Link className="page-head__crumb" to="/listing-templates">
          Listing templates
        </Link>
        <span className="page-head__sep">/</span>
        <h1 className="page-head__title">New batch</h1>
      </div>

      {error && (
        <p className="app__status" role="alert">
          {error}
        </p>
      )}

      <div className="bc-steps">
        <section className="bc-step">
          <h2>1. Listing template</h2>
          <p className="bc-muted bc-small">
            Every design in this batch gets the same product settings.
          </p>
          <div className="bc-picks" role="radiogroup" aria-label="Listing template">
            {(templates ?? []).map((t) => (
              <button
                key={t.name}
                type="button"
                role="radio"
                aria-checked={t.name === chosen}
                className={t.name === chosen ? "bc-pick bc-pick--on" : "bc-pick"}
                onClick={() => setChosen(t.name)}
              >
                {t.media[0] !== undefined && (
                  <img
                    src={ownedTile(t.media[0], { kind: "listing-template", name: t.name })}
                    alt=""
                  />
                )}
                <span className="bc-cell__text">
                  <span className="bc-pick__name">{t.name}</span>
                  <span className="bc-pick__facts">
                    {t.garment} · {t.colour_count} colours
                  </span>
                </span>
              </button>
            ))}
          </div>
          {templates !== null && templates.length === 0 && (
            <p className="bc-small bc-muted">
              There are no listing templates yet. Open a finished listing and choose Save as listing
              template.
            </p>
          )}
        </section>

        <section className="bc-step">
          <h2>2. Designs</h2>
          <p className="bc-muted bc-small">
            One ZIP, or any number of loose PNGs. Up to 25 designs per batch.
          </p>

          {refused && (
            <div
              className="dv-callout dv-callout--blocked"
              style={{ marginBottom: "var(--space-3)" }}
              role="alert"
            >
              <WarningCircleIcon className="dv-callout__icon" />
              <div>
                <strong>{refusedHeading(refused.files)}</strong>
                <div>{refused.message}</div>
                <div className="dv-callout__remedy">{refused.remedy}</div>
              </div>
            </div>
          )}

          <div
            className={refused ? "bc-drop bc-drop--error" : "bc-drop"}
            role="button"
            tabIndex={0}
            aria-disabled={!chosen || busy}
            onClick={() => input.current?.click()}
            onKeyDown={(event) => {
              if (event.key === "Enter" || event.key === " ") input.current?.click();
            }}
            onDragOver={(event) => event.preventDefault()}
            onDrop={onDrop}
          >
            <FileZipIcon className="bc-drop__icon" />
            <span className="bc-drop__title">
              {busy
                ? "Staging…"
                : refused
                  ? "Drop a different ZIP or PNGs"
                  : "Drop a ZIP or PNGs here"}
            </span>
            <span className="bc-small bc-muted">
              Kittl exports work as they are. Every PNG in the ZIP, in any folder, becomes a design.
            </span>
            <span className="bc-row" style={{ marginTop: "var(--space-1)" }}>
              <button type="button" className="btn btn-secondary" disabled={!chosen || busy}>
                Choose files…
              </button>
            </span>
            <input
              ref={input}
              type="file"
              accept=".png,.zip,image/png,application/zip"
              multiple
              hidden
              aria-label="Design files"
              onChange={(event) => {
                stage(Array.from(event.target.files ?? []));
                event.target.value = "";
              }}
            />
          </div>

          <div className="bc-reqs">
            <span className="bc-req">
              <CheckCircleIcon className="bc-icon" />
              PNG with a transparent background
            </span>
            {minimum && template && (
              <span className="bc-req">
                <CheckCircleIcon className="bc-icon" />
                At least {minimum.width} × {minimum.height} px (90% of the {template.garment} print
                area)
              </span>
            )}
            <span className="bc-req">
              <CheckCircleIcon className="bc-icon" />
              Not both a ZIP and loose PNGs, and never more than one ZIP
            </span>
          </div>
        </section>
      </div>
    </>
  );
}

import { STAGE_LABELS, stageWillRun } from "../../types";
import {
  aggregateStageOrder,
  aggregateStageProgress,
  type StageProgress,
} from "./batchDeployPresentation";
import type { BatchListingState } from "./batchDeployState";
import type { PlanDTO } from "../../types";

function stageState(progress: StageProgress): "queued" | "running" | "done" | "failed" {
  if (progress.failed > 0) return "failed";
  if (progress.running > 0) return "running";
  if (progress.total > 0 && progress.completed === progress.total) return "done";
  return "queued";
}

function StageIcon({ state }: { state: ReturnType<typeof stageState> }) {
  if (state === "running") return <span className="dv-spinner" aria-hidden="true" />;
  if (state === "done")
    return (
      <span className="batch-stage__icon" aria-hidden="true">
        ✓
      </span>
    );
  if (state === "failed")
    return (
      <span className="batch-stage__icon" aria-hidden="true">
        !
      </span>
    );
  return (
    <span className="batch-stage__icon" aria-hidden="true">
      ›
    </span>
  );
}

function runningListing(
  stage: string,
  listings: readonly BatchListingState[],
): BatchListingState | undefined {
  return listings.find((listing) => listing.stageRuntime[stage]?.kind === "applying");
}

function exceptionListing(
  stage: string,
  listings: readonly BatchListingState[],
): BatchListingState | undefined {
  return listings.find((listing) => {
    if (listing.stageRuntime[stage]?.kind === "failed") return true;
    if (!listing.stale) return false;
    const plan = listing.plan ?? listing.reviewedPlan;
    return plan?.stage_plans.some(
      (candidate) => candidate.stage === stage && stageWillRun(candidate),
    );
  });
}

/** Run-level progress. It reads only the PR2 projections, so a stage tile
 * cannot accidentally grow a second definition of runnable or completed. */
export function BatchAggregateStages({
  plans,
  listings,
  onOpenListing,
}: {
  plans: readonly PlanDTO[];
  listings: readonly BatchListingState[];
  onOpenListing: (listing: string) => void;
}) {
  const stages = aggregateStageOrder(plans);

  return (
    <section className="batch-aggregate" aria-labelledby="batch-aggregate-heading">
      <span id="batch-aggregate-heading" className="dv-eyebrow">
        Overall run stages
      </span>
      {stages.length === 0 ? (
        <p className="batch-aggregate__empty">No stages were returned by the plan.</p>
      ) : (
        <div className="dv-steps batch-aggregate__steps">
          {stages.map((stage) => {
            const progress = aggregateStageProgress(plans, listings, stage);
            const state = stageState(progress);
            const running = runningListing(stage, listings);
            const exception = running === undefined ? exceptionListing(stage, listings) : undefined;
            const label = STAGE_LABELS[stage] ?? stage;
            return (
              <div key={stage} className={`dv-step batch-stage batch-stage--${state}`}>
                <div className="dv-step__top">
                  <StageIcon state={state} />
                  <span className="dv-step__name">{label}</span>
                </div>
                <div className="batch-stage__count dv-tnum">
                  {progress.completed}/{progress.total}
                </div>
                {running !== undefined ? (
                  <button
                    type="button"
                    className="batch-stage__current"
                    onClick={() => onOpenListing(running.listing)}
                  >
                    Running · {running.listing} →
                  </button>
                ) : exception !== undefined ? (
                  <button
                    type="button"
                    className="batch-stage__current"
                    onClick={() => onOpenListing(exception.listing)}
                  >
                    Attention · {exception.listing} →
                  </button>
                ) : (
                  <div className="dv-step__why">
                    {progress.total === 0
                      ? "No listings will run"
                      : state === "done"
                        ? "All listings done"
                        : `${progress.total} listing${progress.total === 1 ? "" : "s"} will run`}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </section>
  );
}

import { useState, type FocusEvent, type MouseEvent } from "react";
import type { CandidateNames } from "./batchDeployPresentation";

function countDescription(names: CandidateNames): string {
  const parts: string[] = [];
  if (names.add.length > 0) parts.push(`${names.add.length} to add`);
  if (names.remove.length > 0) parts.push(`${names.remove.length} to remove`);
  if (names.edit.length > 0) parts.push(`${names.edit.length} to edit`);
  return parts.join(", ");
}

function CandidateGroup({ label, names }: { label: string; names: readonly string[] }) {
  if (names.length === 0) return null;
  const verb = label === "Add" ? "to add" : label === "Remove" ? "to remove" : "to edit";
  return (
    <div className="batch-candidate-popover__group">
      <strong>
        {label} · {names.length} {verb}
      </strong>
      <span>{names.join(", ")}</span>
    </div>
  );
}

/** The Listings-page entry point. It is intentionally unaware of navigation or
 * run creation; PR4 supplies that callback while this module owns the compact
 * accessible orientation aid. */
export function BatchCandidateControl({
  names,
  onDeploy,
  disabled = false,
}: {
  names: CandidateNames;
  onDeploy: () => void;
  disabled?: boolean;
}) {
  const [open, setOpen] = useState(false);
  const description = countDescription(names);
  const popoverId = "batch-candidate-popover";

  function handleBlur(event: FocusEvent<HTMLDivElement>) {
    if (event.currentTarget.contains(event.relatedTarget as Node | null)) return;
    setOpen(false);
  }

  function handleMouseLeave(event: MouseEvent<HTMLDivElement>) {
    if (!event.currentTarget.contains(document.activeElement)) setOpen(false);
  }

  const label = description === "" ? "Deploy changes" : `Deploy changes: ${description}`;

  return (
    <div
      className="batch-candidate-control"
      onMouseEnter={() => setOpen(true)}
      onMouseLeave={handleMouseLeave}
      onFocus={() => setOpen(true)}
      onBlur={handleBlur}
    >
      <button
        type="button"
        className="btn btn-primary batch-candidate-control__button"
        aria-label={label}
        aria-controls={popoverId}
        aria-describedby={open ? popoverId : undefined}
        aria-expanded={open}
        disabled={disabled}
        onClick={onDeploy}
      >
        <span aria-hidden="true">↗</span>
        <span>Deploy changes</span>
        {description !== "" && (
          <span className="batch-candidate-control__counts" aria-hidden="true">
            {names.add.length > 0 && <span className="tag tag-accent-2">+{names.add.length}</span>}
            {names.remove.length > 0 && (
              <span className="tag tag-dirty">−{names.remove.length}</span>
            )}
            {names.edit.length > 0 && <span className="tag tag-accent">~{names.edit.length}</span>}
          </span>
        )}
      </button>
      {open && (
        <aside id={popoverId} className="batch-candidate-popover" role="tooltip">
          <h3>Candidate changes</h3>
          <CandidateGroup label="Add" names={names.add} />
          <CandidateGroup label="Edit" names={names.edit} />
          <CandidateGroup label="Remove" names={names.remove} />
          <p>Open to generate a fresh plan across all listings.</p>
        </aside>
      )}
    </div>
  );
}

import {
  useEffect,
  useMemo,
  useRef,
  useState,
  type KeyboardEvent,
  type MouseEvent,
  type PointerEvent,
} from "react";
import { stageBlocked, type ListingSummary, type RenderSnapshot } from "../../types";
import { sceneSource } from "../../media";
import { ComparisonView } from "../deploy/ComparisonView";
import { buildComparison } from "../deploy/comparison";
import { PriceTable } from "../deploy/PriceTable";
import { StepStrip } from "../deploy/StepStrip";
import { planGroup, type BatchPlanGroup } from "./batchDeployPresentation";
import type { BatchListingState } from "./batchDeployState";

export type BatchDrawerMode = "review" | "applying" | "applied";

function dialogIsOpen(dialog: HTMLDialogElement): boolean {
  return dialog.open || dialog.hasAttribute("open");
}

function closeNativeDialog(dialog: HTMLDialogElement) {
  if (!dialogIsOpen(dialog)) return;
  if (typeof dialog.close === "function") dialog.close();
  else dialog.removeAttribute("open");
}

function openNativeDialog(dialog: HTMLDialogElement) {
  if (dialogIsOpen(dialog)) return;
  if (typeof dialog.showModal === "function") dialog.showModal();
  else dialog.setAttribute("open", "");
}

const FALLBACK_COLLAPSED_GAP = 32;
const FALLBACK_EXPANDED_GAP = 16;
const MINIMUM_HEIGHT_RATIO = 0.3;

function cssPixels(element: HTMLElement, property: string, fallback: number): number {
  const value = Number.parseFloat(getComputedStyle(element).getPropertyValue(property));
  return Number.isFinite(value) ? value : fallback;
}

function drawerBounds(panel: HTMLElement): {
  minimum: number;
  collapsed: number;
  expanded: number;
} {
  const viewportHeight = window.innerHeight;
  const collapsedGap = cssPixels(panel, "--space-8", FALLBACK_COLLAPSED_GAP);
  const expandedGap = cssPixels(panel, "--space-4", FALLBACK_EXPANDED_GAP);
  const collapsed = Math.min(viewportHeight * 0.74, viewportHeight - collapsedGap);
  return {
    minimum: Math.min(viewportHeight * MINIMUM_HEIGHT_RATIO, collapsed),
    collapsed,
    expanded: Math.min(viewportHeight * 0.92, viewportHeight - expandedGap),
  };
}

function clamp(value: number, minimum: number, maximum: number): number {
  return Math.min(Math.max(value, minimum), maximum);
}

function focusableElements(dialog: HTMLDialogElement): HTMLElement[] {
  return Array.from(
    dialog.querySelectorAll<HTMLElement>(
      'button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), summary, [contenteditable="true"], [tabindex]:not([tabindex="-1"])',
    ),
  );
}

function groupLabel(group: BatchPlanGroup): string {
  switch (group) {
    case "add":
      return "Add to Etsy";
    case "change":
      return "Change on Etsy";
    case "remove":
      return "Remove from Etsy";
    case "attention":
      return "Needs attention";
  }
}

function drawerSummary(
  listing: BatchListingState | null,
  comparison: ReturnType<typeof buildComparison> | null,
): string {
  if (listing?.planFailure !== null && listing?.planFailure !== undefined) {
    return listing.planFailure;
  }
  if (listing?.failureMessage !== null && listing?.failureMessage !== undefined) {
    return listing.failureMessage;
  }
  const blockedStage = listing?.plan?.stage_plans.find((stage) => stageBlocked(stage) !== null);
  const blocked = blockedStage === undefined ? null : stageBlocked(blockedStage);
  return blocked ?? (comparison?.impacts.join(" · ") || "No changes planned");
}

function comparisonPreviews(listing: string, previewsRendered: ReadonlySet<string>): Set<string> {
  const prefix = `${listing}|`;
  return new Set(
    [...previewsRendered]
      .filter((key) => key.startsWith(prefix))
      .map((key) => key.slice(prefix.length)),
  );
}

/** A real modal drawer, kept independent from the eventual review page so PR4
 * can compose it without taking ownership of its focus or diff semantics. */
export function BatchListingDrawer({
  open,
  listing,
  summary,
  mode = "review",
  previewsRendered = new Set(),
  renderSnapshot = null,
  collapsed = false,
  imageUrlForRef,
  onClose,
}: {
  open: boolean;
  listing: BatchListingState | null;
  summary?: Pick<ListingSummary, "name" | "design"> | null;
  mode?: BatchDrawerMode;
  previewsRendered?: ReadonlySet<string>;
  renderSnapshot?: RenderSnapshot | null;
  collapsed?: boolean;
  imageUrlForRef?: (ref: string) => string | null;
  onClose: () => void;
}) {
  const dialogRef = useRef<HTMLDialogElement>(null);
  const restoreFocusRef = useRef<HTMLElement | null>(null);
  const closeRef = useRef<HTMLButtonElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const dragRef = useRef<{ startY: number; startHeight: number } | null>(null);
  const suppressHandleClickRef = useRef(false);
  const [entered, setEntered] = useState(false);
  const [expanded, setExpanded] = useState(false);
  const [drawerHeight, setDrawerHeight] = useState<number | null>(null);
  const [dragging, setDragging] = useState(false);
  const name = summary?.name ?? listing?.listing ?? "Listing";
  const plan = listing?.plan ?? listing?.reviewedPlan ?? null;
  const titleId = `batch-drawer-title-${name.replace(/[^a-z0-9]+/gi, "-")}`;
  const comparison = useMemo(() => (plan === null ? null : buildComparison(plan)), [plan]);
  const category = groupLabel(planGroup(plan, listing?.planFailure ?? null));
  const summaryText = drawerSummary(listing, comparison);

  useEffect(() => {
    const dialog = dialogRef.current;
    if (dialog === null) return;

    if (open) {
      restoreFocusRef.current =
        document.activeElement instanceof HTMLElement ? document.activeElement : null;
      openNativeDialog(dialog);
      // showModal() focuses the first control and scrolls the translated panel into view.
      dialog.scrollTop = 0;
      closeRef.current?.focus({ preventScroll: true });
      const frame = window.requestAnimationFrame(() => setEntered(true));
      return () => window.cancelAnimationFrame(frame);
    }

    closeNativeDialog(dialog);
    const frame = window.requestAnimationFrame(() => setEntered(false));
    const previous = restoreFocusRef.current;
    restoreFocusRef.current = null;
    previous?.focus();
    return () => window.cancelAnimationFrame(frame);
  }, [open]);

  useEffect(() => {
    if (!open) return;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      document.body.style.overflow = previousOverflow;
    };
  }, [open]);

  function handleKeyDown(event: KeyboardEvent<HTMLDialogElement>) {
    if (event.key === "Escape") {
      event.preventDefault();
      onClose();
      return;
    }
    if (event.key !== "Tab") return;
    const dialog = dialogRef.current;
    if (dialog === null) return;
    const focusable = focusableElements(dialog);
    if (focusable.length === 0) {
      event.preventDefault();
      dialog.focus();
      return;
    }
    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    if (event.shiftKey && document.activeElement === first) {
      event.preventDefault();
      last?.focus();
    } else if (!event.shiftKey && document.activeElement === last) {
      event.preventDefault();
      first?.focus();
    }
  }

  function handleScrimClick(event: MouseEvent<HTMLDialogElement>) {
    if (event.target === event.currentTarget) onClose();
  }

  function handleHandlePointerDown(event: PointerEvent<HTMLButtonElement>) {
    if (event.button !== 0) return;
    const panel = panelRef.current;
    if (panel === null) return;
    const bounds = drawerBounds(panel);
    const measuredHeight = panel.getBoundingClientRect().height;
    dragRef.current = {
      startY: event.clientY,
      startHeight: clamp(
        measuredHeight || drawerHeight || (expanded ? bounds.expanded : bounds.collapsed),
        bounds.minimum,
        bounds.expanded,
      ),
    };
    suppressHandleClickRef.current = false;
    setDragging(true);
    event.currentTarget.setPointerCapture?.(event.pointerId);
  }

  function handleHandlePointerMove(event: PointerEvent<HTMLButtonElement>) {
    const drag = dragRef.current;
    const panel = panelRef.current;
    if (drag === null || panel === null) return;
    const bounds = drawerBounds(panel);
    const height = clamp(
      drag.startHeight - (event.clientY - drag.startY),
      bounds.minimum,
      bounds.expanded,
    );
    setDrawerHeight(height);
    setExpanded(height > (bounds.collapsed + bounds.expanded) / 2);
    if (Math.abs(event.clientY - drag.startY) >= 4) suppressHandleClickRef.current = true;
  }

  function handleHandlePointerEnd(event: PointerEvent<HTMLButtonElement>) {
    dragRef.current = null;
    setDragging(false);
    event.currentTarget.releasePointerCapture?.(event.pointerId);
  }

  function handleHandleClick() {
    if (suppressHandleClickRef.current) {
      suppressHandleClickRef.current = false;
      return;
    }
    const panel = panelRef.current;
    if (panel === null) return;
    const nextExpanded = !expanded;
    setExpanded(nextExpanded);
    const bounds = drawerBounds(panel);
    setDrawerHeight(nextExpanded ? bounds.expanded : bounds.collapsed);
  }

  return (
    <dialog
      ref={dialogRef}
      className={`batch-drawer-dialog${entered ? " batch-drawer-dialog--entered" : ""}`}
      aria-modal="true"
      aria-labelledby={titleId}
      aria-hidden={!open}
      onClick={handleScrimClick}
      onKeyDown={handleKeyDown}
      onCancel={(event) => {
        event.preventDefault();
        onClose();
      }}
    >
      <div
        ref={panelRef}
        className={`batch-drawer-panel${expanded ? " batch-drawer-panel--expanded" : ""}${dragging ? " batch-drawer-panel--dragging" : ""}`}
        style={drawerHeight === null ? undefined : { height: `${drawerHeight}px` }}
        onClick={(event) => event.stopPropagation()}
      >
        <header className="batch-drawer__head">
          <div>
            <span className="dv-eyebrow">{category}</span>
            <h2 id={titleId}>{name}</h2>
            <p>{summaryText}</p>
          </div>
          <button ref={closeRef} type="button" className="btn btn-secondary" onClick={onClose}>
            Close
          </button>
        </header>
        <button
          type="button"
          className="batch-drawer__handle"
          aria-label={expanded ? "Collapse drawer" : "Expand drawer"}
          aria-expanded={expanded}
          aria-controls={`${titleId}-panel`}
          onClick={handleHandleClick}
          onPointerDown={handleHandlePointerDown}
          onPointerMove={handleHandlePointerMove}
          onPointerUp={handleHandlePointerEnd}
          onPointerCancel={handleHandlePointerEnd}
        >
          <span aria-hidden="true" />
        </button>
        <div id={`${titleId}-panel`} className="batch-drawer__body">
          {plan === null || comparison === null ? (
            <div className="batch-drawer__empty">
              <h3>{name}</h3>
              <p>The reviewed plan is no longer available for this listing.</p>
            </div>
          ) : (
            <>
              <StepStrip
                plan={plan}
                stageRuntime={listing?.stageRuntime ?? {}}
                heading={
                  mode === "applied"
                    ? "What apply did"
                    : mode === "applying"
                      ? "Live progress for this listing"
                      : "What apply will do"
                }
              />
              <ComparisonView
                comparison={comparison}
                listing={{
                  name,
                  // The server resolves every layer from the saved listing
                  // (A35); nothing is edited here, so no version to key by.
                  scene: sceneSource(name, ""),
                }}
                renderSnapshot={renderSnapshot}
                previewsRendered={comparisonPreviews(name, previewsRendered)}
                collapsed={collapsed}
                etsyListingId={plan.etsy_listing_id}
                {...(imageUrlForRef === undefined ? {} : { imageUrlForRef })}
              />
              <PriceTable rows={comparison?.priceRows ?? []} />
            </>
          )}
        </div>
      </div>
    </dialog>
  );
}

import { stageBlocked, stageWillRun, type PlanDTO } from "../../types";
import {
  buyerFacingImpacts,
  listingStageProgress,
  planGroup,
  type BatchPlanGroup,
} from "./batchDeployPresentation";
import type { BatchListingState } from "./batchDeployState";

const GROUP_LABELS: Record<BatchPlanGroup, string> = {
  add: "Add to Etsy",
  change: "Change on Etsy",
  remove: "Remove from Etsy",
  attention: "Needs attention",
};

function planFor(listing: BatchListingState): PlanDTO | null {
  return listing.plan ?? listing.reviewedPlan;
}

function rowStatus(listing: BatchListingState, plan: PlanDTO | null): string {
  if (listing.stale) return "Stale";
  if (listing.failureMessage !== null) return "Failed";
  if (plan === null || listing.planFailure !== null)
    return listing.planFailure ?? "Needs attention";

  const runnable = plan.stage_plans.filter(stageWillRun);
  if (runnable.length === 0) {
    return plan.stage_plans.some((stage) => stageBlocked(stage) !== null)
      ? "Blocked"
      : "No changes";
  }

  let completed = 0;
  let failed = 0;
  let running = false;
  for (const stage of runnable) {
    const progress = listingStageProgress(plan, listing.stageRuntime, stage.stage);
    completed += progress.completed;
    failed += progress.failed;
    running ||= progress.running > 0;
  }
  if (failed > 0) return "Failed";
  if (running) return "Running";
  if (completed === runnable.length) return "Done";
  if (completed > 0) return `${completed}/${runnable.length}`;
  return `${runnable.length} stage${runnable.length === 1 ? "" : "s"}`;
}

function ListingRow({
  listing,
  onOpenListing,
}: {
  listing: BatchListingState;
  onOpenListing: (listing: string) => void;
}) {
  const plan = planFor(listing);
  const group = planGroup(plan, listing.planFailure);
  const status = rowStatus(listing, plan);
  const impacts = plan === null ? [] : buyerFacingImpacts(plan);
  const summary = listing.planFailure ?? (impacts.length > 0 ? impacts.join(" · ") : status);

  return (
    <button
      type="button"
      className={`batch-listing-row batch-listing-row--${group}`}
      aria-label={`${listing.listing}: ${status}`}
      onClick={() => onOpenListing(listing.listing)}
    >
      <span className="batch-listing-row__copy">
        <strong>{listing.listing}</strong>
        <span className="batch-listing-row__summary">{summary}</span>
      </span>
      <span className="batch-listing-row__state">
        {listing.checkingStage !== null && <span className="dv-spinner" aria-hidden="true" />}
        <span>{status}</span>
        <span aria-hidden="true">→</span>
      </span>
    </button>
  );
}

/** The authoritative plans stay in their four review groups. This component
 * only decides how to present each already-computed state. */
export function BatchListingGroups({
  listings,
  onOpenListing,
}: {
  listings: readonly BatchListingState[];
  onOpenListing: (listing: string) => void;
}) {
  const groups = (Object.keys(GROUP_LABELS) as BatchPlanGroup[]).map((group) => ({
    group,
    listings: listings.filter(
      (listing) => planGroup(planFor(listing), listing.planFailure) === group,
    ),
  }));

  return (
    <div className="batch-listing-groups">
      {groups.map(({ group, listings: groupListings }) => (
        <section
          key={group}
          className="batch-listing-group"
          aria-labelledby={`batch-group-${group}`}
        >
          <h2 id={`batch-group-${group}`}>
            {GROUP_LABELS[group]} <span className="page-head__meta">· {groupListings.length}</span>
          </h2>
          {groupListings.length > 0 ? (
            <div className="batch-listing-group__rows">
              {groupListings.map((listing) => (
                <ListingRow key={listing.listing} listing={listing} onOpenListing={onOpenListing} />
              ))}
            </div>
          ) : (
            <p className="batch-listing-group__empty">None</p>
          )}
        </section>
      ))}
    </div>
  );
}

import {
  stageBlocked,
  stageWillRun,
  type ListingSummary,
  type PlanDTO,
  type StagePlanDTO,
} from "../../types";
import { buildComparison, type ImpactTag } from "../deploy/comparison";
import type { StageRuntimeStatus } from "../deploy/deployState";
import type { BatchDeployState, BatchListingState } from "./batchDeployState";

export type BatchPlanGroup = "add" | "change" | "remove" | "attention";

export interface CandidateNames {
  add: string[];
  edit: string[];
  remove: string[];
}

export interface CandidateCounts {
  add: number;
  edit: number;
  remove: number;
}

export function candidateNames(summaries: readonly ListingSummary[]): CandidateNames {
  const names: CandidateNames = { add: [], edit: [], remove: [] };
  for (const summary of summaries) {
    const hasEtsyListing =
      summary.etsy_listing_id !== null && summary.etsy_listing_id !== undefined;
    if (summary.status === "pending-delete") {
      names.remove.push(summary.name);
    } else if (summary.status === "draft" && !hasEtsyListing) {
      names.add.push(summary.name);
    } else if (
      summary.status === "dirty" ||
      (summary.status === "draft" && hasEtsyListing) ||
      // Normal table gestures (delete, retire, renew) are lifecycle actions,
      // not evidence that the deploy plan has local work to review.
      summary.status === "pending-retire"
    ) {
      names.edit.push(summary.name);
    }
  }
  return names;
}

export function candidateCounts(summaries: readonly ListingSummary[]): CandidateCounts {
  const names = candidateNames(summaries);
  return { add: names.add.length, edit: names.edit.length, remove: names.remove.length };
}

function hasBlockedStage(plan: PlanDTO): boolean {
  return plan.stage_plans.some((stage) => stageBlocked(stage) !== null);
}

function hasRunnableStage(plan: PlanDTO): boolean {
  return plan.stage_plans.some(stageWillRun);
}

export function planGroup(plan: PlanDTO | null, planFailure: string | null = null): BatchPlanGroup {
  if (
    plan === null ||
    planFailure !== null ||
    (plan !== null && !hasRunnableStage(plan) && hasBlockedStage(plan))
  ) {
    return "attention";
  }
  if (plan.stage_plans.some((stage) => stage.stage === "retract")) return "remove";
  if (plan.etsy_listing_id === null) return "add";
  return "change";
}

export function buyerFacingImpacts(plan: PlanDTO): ImpactTag[] {
  return buildComparison(plan).impacts;
}

/** Returned pipeline order is authoritative for the first occurrence of each
 * stage. Retraction is a disjoint lifecycle operation, so it is always shown
 * after the normal pipeline even if a future backend emits it earlier. */
export function aggregateStageOrder(plans: readonly PlanDTO[]): string[] {
  const normal: string[] = [];
  let hasRetract = false;
  for (const plan of plans) {
    for (const stage of plan.stage_plans) {
      if (stage.stage === "retract") {
        hasRetract = true;
      } else if (!normal.includes(stage.stage)) {
        normal.push(stage.stage);
      }
    }
  }
  return hasRetract ? [...normal, "retract"] : normal;
}

export interface StageProgress {
  total: number;
  completed: number;
  running: number;
  failed: number;
}

function runtimeProgress(
  stagePlan: StagePlanDTO | undefined,
  runtime: StageRuntimeStatus | undefined,
): StageProgress {
  if (stagePlan === undefined || !stageWillRun(stagePlan)) {
    return { total: 0, completed: 0, running: 0, failed: 0 };
  }
  return {
    total: 1,
    completed: runtime?.kind === "applied" ? 1 : 0,
    running: runtime?.kind === "applying" ? 1 : 0,
    failed: runtime?.kind === "failed" ? 1 : 0,
  };
}

export function listingStageProgress(
  plan: PlanDTO,
  stageRuntime: Record<string, StageRuntimeStatus>,
  stage: string,
): StageProgress {
  return runtimeProgress(
    plan.stage_plans.find((candidate) => candidate.stage === stage),
    stageRuntime[stage],
  );
}

export function aggregateStageProgress(
  plans: readonly PlanDTO[],
  listings: readonly BatchListingState[],
  stage: string,
): StageProgress {
  const states = new Map(listings.map((listing) => [listing.listing, listing]));
  return plans.reduce<StageProgress>(
    (total, plan) => {
      const progress = listingStageProgress(
        plan,
        states.get(plan.listing)?.stageRuntime ?? {},
        stage,
      );
      return {
        total: total.total + progress.total,
        completed: total.completed + progress.completed,
        running: total.running + progress.running,
        failed: total.failed + progress.failed,
      };
    },
    { total: 0, completed: 0, running: 0, failed: 0 },
  );
}

export interface BatchResult {
  terminal: boolean;
  succeeded: string[];
  clean: string[];
  failed: string[];
  stale: string[];
  blocked: string[];
  attention: string[];
  pending: string[];
  partial: boolean;
}

const TERMINAL_PHASES = new Set(["applied", "failed", "stale", "cancelled"]);

function planIsClean(plan: PlanDTO): boolean {
  return plan.stage_plans.every((stage) => !stageWillRun(stage) && stageBlocked(stage) === null);
}

function planIsBlocked(plan: PlanDTO): boolean {
  return !hasRunnableStage(plan) && hasBlockedStage(plan);
}

function allRunnableStagesApplied(listing: BatchListingState): boolean {
  return (
    listing.plan !== null &&
    listing.plan.stage_plans
      .filter(stageWillRun)
      .every((stage) => listing.stageRuntime[stage.stage]?.kind === "applied")
  );
}

export function batchResult(state: BatchDeployState): BatchResult {
  const terminal = state.applyStarted && TERMINAL_PHASES.has(state.phase);
  const result: BatchResult = {
    terminal,
    succeeded: [],
    clean: [],
    failed: [],
    stale: [],
    blocked: [],
    attention: [],
    pending: [],
    partial: false,
  };

  for (const [name, listing] of Object.entries(state.listings)) {
    if (listing.stale) {
      result.stale.push(name);
    } else if (listing.plan === null || listing.planFailure !== null) {
      result.attention.push(name);
    } else if (listing.failureMessage !== null) {
      result.failed.push(name);
    } else if (planIsBlocked(listing.plan)) {
      result.blocked.push(name);
    } else if (planIsClean(listing.plan)) {
      result.clean.push(name);
      if (terminal) result.succeeded.push(name);
      else result.pending.push(name);
    } else if (allRunnableStagesApplied(listing)) {
      result.succeeded.push(name);
    } else {
      result.pending.push(name);
    }
  }

  result.attention.push(...result.failed, ...result.stale, ...result.blocked);
  result.partial =
    terminal &&
    result.succeeded.length > 0 &&
    (result.failed.length > 0 || result.stale.length > 0);
  return result;
}

import { MutedClip } from "../../components/MutedClip";
import { pictureFor, type SceneSource } from "../../media";
import type { RenderSnapshot } from "../../types";
import type {
  AfterImageTile,
  AfterVideoTile,
  BeforeImageTile,
  BeforeVideoTile,
  Comparison as ComparisonData,
  TagsBlock,
} from "./comparison";
import { wordDiff } from "./wordDiff";

/**
 * The centre of the page: "On Etsy now" / "After apply", or a single column
 * once there is nothing to compare or the run has applied (spec's
 * "Comparison" element, decision 3).
 *
 * Named `ComparisonView`, not `Comparison` -- the frontend module table
 * names this file `Comparison.tsx` beside the pure `comparison.ts` it
 * consumes, differing only in case. That collides on Windows and macOS's
 * default case-insensitive filesystems (this repo's own toolchain, per
 * CLAUDE.md's Environment section) and `tsc` refuses to build it even on a
 * case-sensitive one, having seen both spellings resolve to one path. One
 * of the two names had to move; the pure module keeps the plain noun.
 *
 * **Where a gallery tile's picture comes from** is the one place this
 * component adds a rule `comparison.ts` does not carry, because it needs
 * the DOM-facing side of `media.ts` `comparison.ts` is pure and must not
 * import:
 *
 * - "On Etsy now" prefers the live `url` (Etsy's own CDN image). A `ref`
 * with no `url` yet (freshly uploaded, or a hand-added Shop Manager image
 * this tool never uploaded) falls back to the local render the same way
 * the spec says to.
 * - "After apply" for a scene the render stage will re-render shows a
 * spinner until `previewsRendered` names it, then the preview endpoint's
 * own file. A scene whose render is already current (`state: "cached"`)
 * shows today's picture directly -- there is nothing new to wait for.
 * Neither of those endpoints exists for a bare shared-media ref, which
 * renders through `pictureFor` like the editor's own reel does.
 * - A video is drawn "after" from its own file, as a muted clip the
 * browser gives a poster frame, and "now" from Etsy's `thumbnail_url` --
 * the one picture of it the API offers.
 */

export interface ListingMediaContext {
  name: string;
  /** Where a cached scene's picture resolves its artwork from (A35), or
   * `null` to show the bare photo. */
  scene: SceneSource | null;
}

function parseRef(ref: string): { template: string; colour: string | null } | null {
  const colon = ref.indexOf(":");
  if (colon === -1) {
    // A bare template name (a `multiple`/`single`-kind scene has no colour
    // segment) reads as a template only when it isn't a shared-asset path --
    // the one distinction `_ref()` on the backend doesn't need to make,
    // because it already knows which case it is building.
    if (ref.includes("/") || ref.includes(".")) return null;
    return { template: ref, colour: null };
  }
  return { template: ref.slice(0, colon), colour: ref.slice(colon + 1) };
}

function sceneState(
  renderSnapshot: RenderSnapshot | null,
  template: string,
  colour: string | null,
) {
  return renderSnapshot?.scenes.find((s) => s.template === template && s.colour === colour) ?? null;
}

function AfterTile({
  tile,
  listing,
  renderSnapshot,
  previewsRendered,
  imageUrlForRef,
}: {
  tile: AfterImageTile;
  listing: ListingMediaContext;
  renderSnapshot: RenderSnapshot | null;
  previewsRendered: Set<string>;
  imageUrlForRef: ((ref: string) => string | null) | undefined;
}) {
  const parsed = parseRef(tile.ref);
  let src: string | null = null;
  let pending = false;

  if (imageUrlForRef !== undefined) {
    src = imageUrlForRef(tile.ref);
  } else if (parsed === null) {
    src = pictureFor(tile.ref, listing.scene, "full", listing.name || null);
  } else {
    const scene = sceneState(renderSnapshot, parsed.template, parsed.colour);
    const key = `${parsed.template}|${parsed.colour ?? ""}`;
    const ready =
      scene === null || scene.state === "cached" || scene.preview || previewsRendered.has(key);
    if (ready) {
      src =
        scene !== null && scene.state !== "cached"
          ? previewUrl(listing.name, parsed.template, parsed.colour, scene.scene_hash)
          : pictureFor({ template: parsed.template, colour: parsed.colour }, listing.scene, "full");
    } else {
      pending = true;
    }
  }

  return (
    <figure className="dv-thumb-wrap">
      <div
        className={`dv-thumb${tile.badge === "new" ? " dv-thumb--new" : ""}${tile.replaced ? " dv-thumb--replaced" : ""}`}
        title={tile.replaced ? "Changed" : undefined}
      >
        {pending ? (
          <span className="dv-spinner" aria-hidden="true" />
        ) : (
          <img alt={tile.ref} src={src ?? undefined} />
        )}
        {tile.badge === "new" && <span className="dv-thumb__badge dv-thumb__badge--new">New</span>}
        {tile.badge === "moved" && (
          <span className="dv-thumb__badge dv-thumb__badge--moved">was {tile.movedFrom}</span>
        )}
      </div>
    </figure>
  );
}

/** This plan's own preview of the scene, named by the hash the plan computed
 * for it -- a file read, where asking without the hash re-plans the listing. */
function previewUrl(
  listing: string,
  template: string,
  colour: string | null,
  sceneHash: string,
): string {
  const base = `/api/listings/${encodeURIComponent(listing)}/previews/${encodeURIComponent(template)}`;
  const path = colour !== null ? `${base}/${encodeURIComponent(colour)}` : base;
  return `${path}?hash=${encodeURIComponent(sceneHash)}`;
}

function BeforeTile({ tile }: { tile: BeforeImageTile }) {
  return (
    <figure className="dv-thumb-wrap">
      <div
        className={`dv-thumb${tile.badge === "removed" ? " dv-thumb--gone" : ""}${tile.replaced ? " dv-thumb--replaced" : ""}`}
        title={tile.replaced ? "Changed" : undefined}
      >
        {tile.url !== null ? (
          <img alt={tile.ref ?? "listing image"} src={tile.url} />
        ) : (
          <span className="dv-thumb--empty" aria-hidden="true" />
        )}
        {tile.badge === "removed" && (
          <span className="dv-thumb__badge dv-thumb__badge--gone">Removed</span>
        )}
      </div>
    </figure>
  );
}

function AfterVideo({ tile, listing }: { tile: AfterVideoTile; listing: string }) {
  const isNew = tile.badge === "new";
  return (
    <figure className="dv-thumb-wrap">
      <div className={`dv-thumb${isNew ? " dv-thumb--new" : ""}`}>
        <MutedClip src={pictureFor(tile.ref, null, "full", listing || null)} label={tile.ref} />
        {isNew && <span className="dv-thumb__badge dv-thumb__badge--new">New</span>}
      </div>
      <figcaption className="dv-thumb__caption">
        {tile.slot === "featured" ? "Featured · 2nd" : `After ${tile.afterImages ?? 0} images`}
      </figcaption>
    </figure>
  );
}

function BeforeVideo({ tile }: { tile: BeforeVideoTile }) {
  const gone = tile.badge === "removed";
  return (
    <figure className="dv-thumb-wrap">
      <div className={`dv-thumb${gone ? " dv-thumb--gone" : ""}`}>
        {tile.url !== null ? (
          <img alt={tile.ref ?? "listing video"} src={tile.url} />
        ) : (
          <span className="dv-thumb--empty" aria-hidden="true" />
        )}
        {gone && <span className="dv-thumb__badge dv-thumb__badge--gone">Removed</span>}
      </div>
      <figcaption className="dv-thumb__caption">
        {tile.ref === null ? "Not uploaded by this tool" : tile.ref.split("/").pop()}
        {tile.inactive && " · Not playing on Etsy"}
      </figcaption>
    </figure>
  );
}

function Block({
  label,
  changed,
  side,
  children,
}: {
  label: string;
  changed: boolean;
  side: "before" | "after";
  children: React.ReactNode;
}) {
  const cls = changed ? `dv-block dv-block--${side}` : "dv-block";
  return (
    <div className={cls}>
      <div className="dv-block__label">
        <span className="dv-eyebrow">{label}</span>
        {changed && (
          <span className={side === "before" ? "dv-changed dv-changed--before" : "dv-changed"}>
            {side === "after" ? "Changes" : "Replaced"}
          </span>
        )}
      </div>
      {children}
    </div>
  );
}

function StringList({
  label,
  block,
  side,
}: {
  label: string;
  block: TagsBlock;
  side: "before" | "after";
}) {
  const isAfter = side === "after";
  return (
    <Block label={label} changed={block.changed} side={side}>
      <div className="dv-chips">
        {(isAfter ? block.after : block.before).map((value) => {
          const added = isAfter && block.added.includes(value);
          const removed = !isAfter && block.removed.includes(value);
          return (
            <span
              key={value}
              className={`dv-chip${added ? " dv-chip--add" : ""}${removed ? " dv-chip--rm" : ""}`}
            >
              {value}
            </span>
          );
        })}
      </div>
    </Block>
  );
}

function Column({
  side,
  comparison,
  listing,
  renderSnapshot,
  previewsRendered,
  etsyListingIdLabel,
  imageUrlForRef,
}: {
  side: "before" | "after";
  comparison: ComparisonData;
  listing: ListingMediaContext;
  renderSnapshot: RenderSnapshot | null;
  previewsRendered: Set<string>;
  etsyListingIdLabel: string;
  imageUrlForRef: ((ref: string) => string | null) | undefined;
}) {
  const isAfter = side === "after";
  const { title, description, tags, materials, colours, price, images, videos } = comparison;

  return (
    <div className="dv-col">
      <div className="dv-col__head">
        <h3>{isAfter ? "After apply" : "On Etsy now"}</h3>
        <span className="dv-eyebrow">{isAfter ? "from this plan" : etsyListingIdLabel}</span>
      </div>

      {images && (
        <Block label="Images" changed={images.changed} side={side}>
          <div className="dv-gallery">
            {isAfter
              ? images.after.map((tile) => (
                  <AfterTile
                    key={tile.rank}
                    tile={tile}
                    listing={listing}
                    renderSnapshot={renderSnapshot}
                    previewsRendered={previewsRendered}
                    imageUrlForRef={imageUrlForRef}
                  />
                ))
              : images.before.map((tile) => <BeforeTile key={tile.rank} tile={tile} />)}
          </div>
        </Block>
      )}

      {videos && (
        <Block label="Videos" changed={videos.changed} side={side}>
          <div className="dv-gallery dv-gallery--videos">
            {isAfter
              ? videos.after.map((tile) => (
                  <AfterVideo key={tile.ref} tile={tile} listing={listing.name} />
                ))
              : videos.before.map((tile) => <BeforeVideo key={tile.videoId} tile={tile} />)}
          </div>
        </Block>
      )}

      {title && (
        <Block label="Title" changed={title.changed} side={side}>
          <div className="dv-title">
            {isAfter && title.changed
              ? wordDiff(title.before ?? "", title.after).map((token, index) => (
                  <span
                    key={index}
                    className={token.type === "same" ? undefined : `dv-${token.type}`}
                  >
                    {token.text}{" "}
                  </span>
                ))
              : isAfter
                ? title.after
                : (title.before ?? "—")}
          </div>
        </Block>
      )}

      {description && (
        <Block label="Description" changed={description.changed} side={side}>
          <div className="dv-description">
            {isAfter && description.changed
              ? wordDiff(description.before ?? "", description.after).map((token, index) => (
                  <span
                    key={index}
                    className={token.type === "same" ? undefined : `dv-${token.type}`}
                  >
                    {token.text}{" "}
                  </span>
                ))
              : isAfter
                ? description.after
                : (description.before ?? "—")}
          </div>
        </Block>
      )}

      {price && (
        <Block label="Price" changed={price.changed} side={side}>
          <div className="dv-price dv-tnum">
            {formatRange(isAfter ? price.after : price.before)}
          </div>
        </Block>
      )}

      {colours && (
        <Block label="Colours" changed={colours.changed} side={side}>
          <div className="dv-swatches">
            {(isAfter ? colours.after : colours.before).map((colour) => {
              const isNew = isAfter && colours.added.includes(colour);
              return (
                <span key={colour} className={isNew ? "dv-sw dv-sw--new" : "dv-sw"}>
                  {colour}
                  {isNew && " · new"}
                </span>
              );
            })}
          </div>
        </Block>
      )}

      {tags && <StringList label="Tags" block={tags} side={side} />}
      {materials && <StringList label="Materials" block={materials} side={side} />}
    </div>
  );
}

/** `"349 NOK"` alone, or `"349–399 NOK"` -- the bare low amount, an
 * en-dash, then the high amount with its unit, matching how the design mock
 * reads a price range. */
function formatRange(range: { min: string; max: string } | null): string {
  if (range === null) return "—";
  if (range.min === range.max) return range.min;
  const minAmount = range.min.split(" ")[0] ?? range.min;
  return `${minAmount}–${range.max}`;
}

export function ComparisonView({
  comparison,
  listing,
  renderSnapshot,
  previewsRendered,
  collapsed,
  etsyListingId,
  imageUrlForRef,
}: {
  comparison: ComparisonData;
  listing: ListingMediaContext;
  renderSnapshot: RenderSnapshot | null;
  previewsRendered: Set<string>;
  /** Collapse to one "On Etsy now" column -- once applied, or when the plan
   * found nothing to compare. */
  collapsed: boolean;
  etsyListingId: number | null;
  /** Optional fixture resolver for canvases and component galleries. The app
   * normally derives these URLs from the listing's media refs. */
  imageUrlForRef?: (ref: string) => string | null;
}) {
  const etsyListingIdLabel = etsyListingId !== null ? `listing ${etsyListingId}` : "";
  const columnProps = {
    comparison,
    listing,
    renderSnapshot,
    previewsRendered,
    etsyListingIdLabel,
    imageUrlForRef,
  };

  if (!comparison.hasEtsyListing) {
    return (
      <div className="dv-compare dv-compare--single">
        <Column {...columnProps} side="after" />
        <p className="dv-note">Not on Etsy yet.</p>
      </div>
    );
  }

  if (collapsed) {
    return (
      <div className="dv-compare dv-compare--single">
        <Column {...columnProps} side="before" />
      </div>
    );
  }

  return (
    <div className="dv-compare">
      <Column {...columnProps} side="before" />
      <Column {...columnProps} side="after" />
    </div>
  );
}

import type { PriceRow } from "./comparison";

/**
 * Per-size price table, shown only when a price changed (spec's "Price
 * table" element). Rows come straight from `comparison.ts`'s `priceRows` --
 * built from the engine's own `PriceChange`s, grouped by size -- so a red
 * "below cost" mark here is never a second copy of `publish`'s own rule
 *.
 */

function difference(before: string | null, after: string | null): string {
  if (before === null || after === null) return "no change";
  const currency = after.split(" ").pop() ?? "";
  const delta = Number.parseFloat(after) - Number.parseFloat(before);
  if (delta === 0) return "no change";
  const sign = delta > 0 ? "+" : "−";
  return `${sign}${Math.abs(delta)} ${currency}`;
}

export function PriceTable({ rows }: { rows: PriceRow[] }) {
  if (rows.length === 0) return null;

  return (
    <div className="dv-prices">
      <table>
        <thead>
          <tr>
            <th scope="col">Size</th>
            <th scope="col">On Etsy now</th>
            <th scope="col">After apply</th>
            <th scope="col">Difference</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => (
            <tr key={row.size}>
              <th scope="row">{row.size}</th>
              <td className="dv-tnum">{row.before ?? "—"}</td>
              <td className={`dv-tnum${row.belowCost ? " dv-bad" : row.changed ? " dv-up" : ""}`}>
                {row.after ?? "—"}
                {row.belowCost && " · below cost"}
              </td>
              <td className="dv-tnum">{difference(row.before, row.after)}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

import { useEffect, useState } from "react";
import type { StageRuntimeStatus } from "./deployState";
import type { PlanDTO, StagePlanDTO } from "../../types";
import { STAGE_LABELS, stageActions, stageBlocked, stageReason, stageWillRun } from "../../types";

/**
 * "What apply will do" / "What apply did" -- one cell per stage the plan
 * actually returned, in pipeline order (spec's "Step strip" element,
 * decision 11: nothing here hard-codes five stages, so a `retract`-only
 * plan draws one cell and an `_all_blocked` listing draws every stage red).
 *
 * A stage the engine puts under another by `group` (`etsy_videos` under
 * `etsy_media`, ADR-0045) is drawn beside it inside one labelled group, so the
 * strip reads as the CLI's `etsy_media/etsy_videos` does. The grouping is the
 * engine's data, never inferred here from a name.
 */

type CellState =
  "run" | "skip" | "blocked" | "running" | "applying-log" | "done" | "failed" | "not-reached";

function cellState(
  stagePlan: StagePlanDTO,
  runtime: StageRuntimeStatus | undefined,
  failedEarlier: boolean,
): CellState {
  if (runtime?.kind === "applying") return "running";
  if (runtime?.kind === "applied") return "done";
  if (runtime?.kind === "failed") return "failed";
  if (stageWillRun(stagePlan) && failedEarlier) return "not-reached";
  if (stageBlocked(stagePlan) !== null) return "blocked";
  return stageWillRun(stagePlan) ? "run" : "skip";
}

function Icon({ state }: { state: CellState }) {
  if (state === "running") return <span className="dv-spinner" aria-hidden="true" />;
  if (state === "run") {
    return (
      <svg width="16" height="16" viewBox="0 0 16 16" aria-hidden="true">
        <circle cx="8" cy="8" r="6.5" fill="var(--color-accent)" />
        <path d="M6.5 5.2 10.5 8l-4 2.8Z" fill="var(--color-bg)" />
      </svg>
    );
  }
  if (state === "blocked" || state === "failed") {
    return (
      <svg width="16" height="16" viewBox="0 0 16 16" aria-hidden="true">
        <circle cx="8" cy="8" r="6.5" fill="var(--color-danger)" />
        <path d="M5 11 11 5" stroke="var(--color-bg)" strokeWidth="1.8" />
      </svg>
    );
  }
  if (state === "done") {
    return (
      <svg width="16" height="16" viewBox="0 0 16 16" aria-hidden="true">
        <circle cx="8" cy="8" r="6.5" fill="var(--color-accent-2)" />
        <path
          d="m5 8.2 2 2 4-4.2"
          stroke="var(--color-bg)"
          strokeWidth="1.8"
          fill="none"
          strokeLinecap="round"
          strokeLinejoin="round"
        />
      </svg>
    );
  }
  return (
    <svg width="16" height="16" viewBox="0 0 16 16" aria-hidden="true">
      <circle cx="8" cy="8" r="5.5" fill="none" stroke="var(--color-neutral-400)" strokeWidth="2" />
    </svg>
  );
}

function whyText(
  state: CellState,
  stagePlan: StagePlanDTO,
  runtime: StageRuntimeStatus | undefined,
): string {
  switch (state) {
    case "blocked":
      return "Blocked";
    case "skip":
      return "No changes";
    case "done":
      return "Done";
    case "running":
      return "Running";
    case "failed":
      return (runtime && runtime.kind === "failed" && runtime.message) || "Failed";
    case "not-reached":
      return "Not reached";
    default:
      return stageReason(stagePlan) ?? "";
  }
}

function formatElapsed(milliseconds: number): string {
  const totalSeconds = Math.max(0, Math.floor(milliseconds / 1000));
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  return minutes > 0 ? `${minutes}:${seconds.toString().padStart(2, "0")}` : `${seconds}s`;
}

function StageTimer({ runtime }: { runtime: StageRuntimeStatus }) {
  const [now, setNow] = useState(Date.now);

  useEffect(() => {
    if (runtime.kind !== "applying") return;
    const timer = window.setInterval(() => setNow(Date.now()), 250);
    return () => window.clearInterval(timer);
  }, [runtime.kind, runtime.startedAt]);

  const end = runtime.kind === "applying" ? now : runtime.finishedAt;
  return (
    <span
      className="dv-step__timer"
      aria-label={`Elapsed ${formatElapsed(end - runtime.startedAt)}`}
    >
      {formatElapsed(end - runtime.startedAt)}
    </span>
  );
}

function StepCell({
  stagePlan,
  runtime,
  failedEarlier,
}: {
  stagePlan: StagePlanDTO;
  runtime: StageRuntimeStatus | undefined;
  failedEarlier: boolean;
}) {
  const [open, setOpen] = useState(false);
  const state = cellState(stagePlan, runtime, failedEarlier);
  const label = STAGE_LABELS[stagePlan.stage] ?? stagePlan.stage;
  const log = runtime?.kind === "applying" ? runtime.log : null;
  const actions = stageActions(stagePlan);

  return (
    <div className={`dv-step dv-step--${state}`}>
      <div className="dv-step__top">
        <Icon state={state} />
        <span className="dv-step__name">{label}</span>
        {runtime && <StageTimer runtime={runtime} />}
      </div>
      <div className={state === "running" ? "dv-step__why" : "dv-step__why"}>
        {whyText(state, stagePlan, runtime)}
      </div>
      {log !== null && <div className="dv-step__log">&rsaquo; {log}</div>}
      {(state === "run" || state === "done") && actions.length > 0 && (
        <details open={open} onToggle={(e) => setOpen((e.target as HTMLDetailsElement).open)}>
          <summary>
            {actions.length} action{actions.length > 1 ? "s" : ""}
          </summary>
          <ul>
            {actions.map((action, index) => (
              <li key={index}>
                {action.description}
                {action.outputs.length > 0 && (
                  <>
                    {" → "}
                    <span className="dv-mono">{action.outputs[0]?.split("/").pop()}</span>
                  </>
                )}
              </li>
            ))}
          </ul>
        </details>
      )}
    </div>
  );
}

/** The strip's cells, each stage with the ones grouped under it. A stage
 * whose group is not in the plan stands on its own. */
function nest(stagePlans: readonly StagePlanDTO[]): StagePlanDTO[][] {
  const present = new Set(stagePlans.map((s) => s.stage as string));
  const rows: StagePlanDTO[][] = [];
  for (const stagePlan of stagePlans) {
    const parent = stagePlan.group ?? null;
    const row =
      parent !== null && present.has(parent) ? rows.find((r) => r[0]?.stage === parent) : undefined;
    if (row !== undefined) row.push(stagePlan);
    else rows.push([stagePlan]);
  }
  return rows;
}

export function StepStrip({
  plan,
  stageRuntime,
  heading,
}: {
  plan: PlanDTO;
  stageRuntime: Record<string, StageRuntimeStatus>;
  heading: string;
}) {
  const failedIndex = plan.stage_plans.findIndex((s) => stageRuntime[s.stage]?.kind === "failed");
  const cell = (stagePlan: StagePlanDTO) => (
    <StepCell
      key={stagePlan.stage}
      stagePlan={stagePlan}
      runtime={stageRuntime[stagePlan.stage]}
      failedEarlier={failedIndex !== -1 && plan.stage_plans.indexOf(stagePlan) > failedIndex}
    />
  );

  return (
    <div className="dv-stack" style={{ gap: 8 }}>
      <span className="dv-eyebrow">{heading}</span>
      <div className="dv-steps">
        {nest(plan.stage_plans).map((row) => {
          const head = row[0] as StagePlanDTO;
          if (row.length === 1) return cell(head);
          const label = STAGE_LABELS[head.stage] ?? head.stage;
          return (
            <div
              key={head.stage}
              className="dv-step-group"
              role="group"
              aria-label={label}
              style={{
                gridColumn: `span ${row.length}`,
                gridTemplateColumns: `repeat(${row.length}, minmax(0, 1fr))`,
              }}
            >
              {row.map(cell)}
            </div>
          );
        })}
      </div>
    </div>
  );
}

import type { PlanDTO, RunEvent } from "../../types";

export type StageRuntimeStatus =
  | { kind: "applying"; log: string | null; startedAt: number }
  | { kind: "applied"; startedAt: number; finishedAt: number }
  | { kind: "failed"; message: string; startedAt: number; finishedAt: number };

export interface ListingRunState {
  reviewedPlan: PlanDTO | null;
  plan: PlanDTO | null;
  fingerprint: string | null;
  planFailure: string | null;
  failureMessage: string | null;
  stale: boolean;
  checkingStage: string | null;
  stageRuntime: Record<string, StageRuntimeStatus>;
}

export type ListingPlanMode = "review" | "replace" | "runtime-only";

export function initialListingRunState(): ListingRunState {
  return {
    reviewedPlan: null,
    plan: null,
    fingerprint: null,
    planFailure: null,
    failureMessage: null,
    stale: false,
    checkingStage: null,
    stageRuntime: {},
  };
}

function withRuntime(
  state: ListingRunState,
  stage: string,
  runtime: StageRuntimeStatus,
): ListingRunState {
  return { ...state, stageRuntime: { ...state.stageRuntime, [stage]: runtime } };
}

function eventTime(event: { occurred_at?: string }): number {
  const at = event.occurred_at;
  if (at === undefined) return 0;
  const parsed = Date.parse(at);
  return Number.isNaN(parsed) ? 0 : parsed;
}

/** One authoritative projection for a listing's plan and stage-runtime events.
 * Individual deploy uses `replace`; batch review uses `review`; batch apply
 * uses `runtime-only` so re-planning cannot overwrite what was reviewed. */
export function applyListingRunEvent(
  state: ListingRunState,
  event: RunEvent,
  planMode: ListingPlanMode,
): ListingRunState {
  switch (event.type) {
    case "stage_checking":
      return { ...state, checkingStage: event.stage };

    case "stage_planned":
      return {
        ...state,
        checkingStage: state.checkingStage === event.stage_plan.stage ? null : state.checkingStage,
      };

    case "listing_planned":
      if (planMode === "runtime-only") {
        return { ...state, planFailure: null, checkingStage: null };
      }
      return {
        ...state,
        reviewedPlan: planMode === "review" ? event.plan : state.reviewedPlan,
        plan: event.plan,
        fingerprint: event.fingerprint,
        planFailure: null,
        checkingStage: null,
        stale: false,
      };

    case "stage_applying":
      return withRuntime(state, event.stage, {
        kind: "applying",
        log: null,
        startedAt: eventTime(event),
      });

    case "progress": {
      const current = state.stageRuntime[event.stage];
      if (current === undefined || current.kind !== "applying") return state;
      return withRuntime(state, event.stage, { ...current, log: event.message });
    }

    case "stage_applied": {
      const finishedAt = eventTime(event);
      const current = state.stageRuntime[event.stage];
      return withRuntime(state, event.stage, {
        kind: "applied",
        startedAt: current?.kind === "applying" ? current.startedAt : finishedAt,
        finishedAt,
      });
    }

    case "stage_failed": {
      const finishedAt = eventTime(event);
      const current = state.stageRuntime[event.stage];
      return withRuntime(state, event.stage, {
        kind: "failed",
        message: event.message,
        startedAt: current?.kind === "applying" ? current.startedAt : finishedAt,
        finishedAt,
      });
    }

    case "listing_failed":
      return {
        ...state,
        failureMessage: event.message,
        planFailure: state.plan === null ? event.message : state.planFailure,
        ...(event.stale_plan
          ? { plan: event.stale_plan, stale: true, fingerprint: null, checkingStage: null }
          : {}),
      };

    default:
      return state;
  }
}

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { openRunStream } from "./runStream";

/**
 * `GET /api/runs/{id}/events` through a plain `fetch` reader, framed exactly
 * as `server/api/runs.py`'s `_sse_frame` writes: `id: <n>\nevent: <type>\ndata:
 * <json>\n\n`. `fetch` is stubbed with a real `ReadableStream` so the parser
 * is exercised against actual chunk boundaries, not a fake that hands back
 * whole frames for free.
 */

function sseBody(frames: string[]): ReadableStream<Uint8Array> {
  const encoder = new TextEncoder();
  let index = 0;
  return new ReadableStream({
    pull(controller) {
      if (index >= frames.length) {
        controller.close();
        return;
      }
      controller.enqueue(encoder.encode(frames[index]));
      index++;
    },
  });
}

function frame(id: number, type: string, data: Record<string, unknown>): string {
  return `id: ${id}\nevent: ${type}\ndata: ${JSON.stringify({ id, type, ...data })}\n\n`;
}

describe("openRunStream", () => {
  let fetchMock: ReturnType<typeof vi.fn>;

  beforeEach(() => {
    fetchMock = vi.fn();
    vi.stubGlobal("fetch", fetchMock);
  });

  afterEach(() => {
    vi.unstubAllGlobals();
  });

  it("parses every frame in the stream, in order, and reports when it ends", async () => {
    const body = sseBody([
      frame(1, "phase", { phase: "queued" }),
      frame(2, "phase", { phase: "planning" }),
    ]);
    fetchMock.mockResolvedValue(new Response(body, { status: 200 }));

    const events: unknown[] = [];
    let done = false;
    openRunStream("run-1", {
      onEvent: (e) => events.push(e),
      onDone: () => {
        done = true;
      },
    });

    await vi.waitFor(() => expect(done).toBe(true));

    expect(events).toEqual([
      { id: 1, type: "phase", phase: "queued" },
      { id: 2, type: "phase", phase: "planning" },
    ]);
  });

  it("parses a frame split across two chunks", async () => {
    const whole = frame(1, "phase", { phase: "ready" });
    const splitAt = Math.floor(whole.length / 2);
    const body = sseBody([whole.slice(0, splitAt), whole.slice(splitAt)]);
    fetchMock.mockResolvedValue(new Response(body, { status: 200 }));

    const events: unknown[] = [];
    openRunStream("run-2", { onEvent: (e) => events.push(e) });

    await vi.waitFor(() => expect(events).toHaveLength(1));
    expect(events[0]).toEqual({ id: 1, type: "phase", phase: "ready" });
  });

  it("sends Last-Event-ID when reattaching after a known event", async () => {
    fetchMock.mockResolvedValue(new Response(sseBody([]), { status: 200 }));

    openRunStream("run-3", { lastEventId: 7, onEvent: () => {} });

    await vi.waitFor(() => expect(fetchMock).toHaveBeenCalled());
    const [url, init] = fetchMock.mock.calls[0] as [string, RequestInit];
    expect(url).toBe("/api/runs/run-3/events");
    expect((init.headers as Record<string, string>)["Last-Event-ID"]).toBe("7");
  });

  it("sends no Last-Event-ID for a run just started", async () => {
    fetchMock.mockResolvedValue(new Response(sseBody([]), { status: 200 }));

    openRunStream("run-4", { onEvent: () => {} });

    await vi.waitFor(() => expect(fetchMock).toHaveBeenCalled());
    const [, init] = fetchMock.mock.calls[0] as [string, RequestInit];
    expect(init.headers).toEqual({});
  });

  it("reports an HTTP error instead of silently doing nothing", async () => {
    fetchMock.mockResolvedValue(new Response(null, { status: 404 }));

    let error: unknown = null;
    openRunStream("run-5", { onEvent: () => {}, onError: (e) => (error = e) });

    await vi.waitFor(() => expect(error).not.toBeNull());
  });

  it("close() aborts the underlying request without calling onError", async () => {
    const body = sseBody([]);
    fetchMock.mockImplementation((_url: string, init: RequestInit) => {
      return new Promise((_resolve, reject) => {
        init.signal?.addEventListener("abort", () =>
          reject(new DOMException("aborted", "AbortError")),
        );
      });
    });

    let errored = false;
    const handle = openRunStream("run-6", {
      onEvent: () => {},
      onError: () => {
        errored = true;
      },
    });
    handle.close();

    await vi.waitFor(() => expect(fetchMock).toHaveBeenCalled());
    // Give the rejected promise's microtask a turn.
    await new Promise((r) => setTimeout(r, 0));
    expect(errored).toBe(false);
    void body;
  });
});

import { CaretDownIcon } from "@phosphor-icons/react/dist/csr/CaretDown";
import { CircleNotchIcon } from "@phosphor-icons/react/dist/csr/CircleNotch";
import { UploadSimpleIcon } from "@phosphor-icons/react/dist/csr/UploadSimple";
import { useEffect, useRef, useState, type DragEvent } from "react";
import {
  listGarmentProfiles,
  listingDesignThumbnailUrl,
  listListingDesigns,
  uploadListingDesign,
} from "../../api/listings";
import { refName } from "../../media";
import type { DesignMap, ListingDesignSummary } from "../../types";
import { ArtworkPicker } from "./ArtworkPicker";
import {
  cap,
  isLinked,
  linking,
  keepOne,
  listNames,
  pickFor,
  slotFile,
  slotUsers,
  TILE,
  toneLabel,
  unlinked,
  type SlotTarget,
  type Tone,
} from "./artwork";
import { ChooseBaseDialog } from "./ChooseBaseDialog";
import { ShirtThumb } from "./ShirtThumb";

/**
 * The design strip above the tabs: which artwork each shirt prints.
 *
 * One design (`design.default`) is the default and shows as one selector
 * beside a light and a dark shirt wearing it. **Use different designs on
 * light & dark shirts** splits it into two selectors, `on-light` and
 * `on-dark`, each beside the one shirt it prints on; going back to one design
 * asks which file to keep when there are two. Every change is one `onChange`
 * with the whole new map, built by `artwork.ts`'s transitions.
 *
 * A PNG dropped on a selector is uploaded into `designs/` and picked for that
 * selector. The drop targets are the selectors on show: dropping never
 * changes the mode, so a listing on one design is only ever given another
 * one design.
 *
 * Which Recent designs panel is open is the shell's state, not the strip's,
 * so the card under the Variants stage can open a slot's panel too.
 */

interface Props {
  design: DesignMap;
  /** The colours the listing sells -- which ones each slot prints on. */
  colours: readonly string[];
  garmentProfile: string;
  open: SlotTarget | null;
  onOpen: (target: SlotTarget | null) => void;
  /** The new `design:` map. What it sets off beyond the edit -- naming a
   * draft, arming AI -- is decided from the map, not from which control made
   * it (spec: *Representative artwork*). */
  onChange: (next: DesignMap) => void;
  /** Previews a colour on the Variants stage: the own-design line's names. */
  onPreview: (colour: string) => void;
}

/** How many the strip offers before the full list is needed. Four fills one
 * row of the picker grid; the rest are a search away. */
const RECENT = 4;

const ONE: SlotTarget = { kind: "one" };

const sameTarget = (a: SlotTarget | null, b: SlotTarget) =>
  a !== null && a.kind === b.kind && (a.kind === "one" || (b.kind === "slot" && a.tone === b.tone));

function targetLabel(target: SlotTarget): string {
  return target.kind === "one" ? "all shirts" : toneLabel(target.tone);
}

const hasFiles = (e: DragEvent) => Array.from(e.dataTransfer.types).includes("Files");

/** Enter/leave counted, so passing over a child doesn't drop the state. */
function useDragDepth(onChange: (holding: boolean) => void) {
  const depth = useRef(0);
  return {
    enter(e: DragEvent): boolean {
      if (!hasFiles(e)) return false;
      e.preventDefault();
      depth.current += 1;
      if (depth.current === 1) onChange(true);
      return true;
    },
    leave() {
      depth.current = Math.max(0, depth.current - 1);
      if (depth.current === 0) onChange(false);
    },
    reset() {
      depth.current = 0;
      onChange(false);
    },
  };
}

export function ArtworkStrip({
  design,
  colours,
  garmentProfile,
  open,
  onOpen,
  onChange,
  onPreview,
}: Props) {
  const [library, setLibrary] = useState<ListingDesignSummary[]>([]);
  const [tones, setTones] = useState<Record<string, Tone>>({});
  const [finding, setFinding] = useState<SlotTarget | null>(null);
  const [choosing, setChoosing] = useState<{ light: string; dark: string } | null>(null);
  const [holding, setHolding] = useState(false);
  const [uploading, setUploading] = useState<{ target: SlotTarget; name: string } | null>(null);
  const [failed, setFailed] = useState<string | null>(null);
  const hold = useDragDepth(setHolding);
  // An upload outlives the render that started it; it picks into the map as
  // it is when the file lands, not as it was when the file was dropped.
  const latest = useRef(design);
  useEffect(() => {
    latest.current = design;
  }, [design]);

  useEffect(() => {
    listListingDesigns()
      .then(setLibrary)
      .catch(() => setLibrary([]));
  }, []);

  useEffect(() => {
    let current = true;
    listGarmentProfiles()
      .then((profiles) => {
        if (current) setTones(profiles.find((p) => p.name === garmentProfile)?.colors ?? {});
      })
      .catch(() => undefined);
    return () => {
      current = false;
    };
  }, [garmentProfile]);

  const split = !isLinked(design);
  const users = slotUsers(design, colours, tones);
  const own = colours.filter((c) => (design[c] ?? null) !== null);

  function pick(target: SlotTarget, ref: string) {
    onChange(pickFor(design, target, ref));
    onOpen(null);
    setFinding(null);
  }

  async function upload(target: SlotTarget, file: File) {
    setFailed(null);
    setUploading({ target, name: file.name });
    try {
      const added = await uploadListingDesign(file);
      setLibrary((designs) => [added, ...designs.filter((d) => d.file !== added.file)]);
      onChange(pickFor(latest.current, target, added.file));
    } catch (error) {
      const reason = error instanceof Error ? error.message : "the upload failed";
      setFailed(`Couldn't upload ${file.name}: ${reason}`);
    } finally {
      setUploading(null);
    }
  }

  function link() {
    const outcome = linking(design);
    if (outcome.kind === "linked") onChange(outcome.design);
    else setChoosing({ light: outcome.light, dark: outcome.dark });
  }

  const everyShirt =
    own.length > 0
      ? "Prints on every colour without its own design"
      : "Prints on every colour you sell";

  /** What a slot shows; its handlers are written where it is rendered. */
  const view = (target: SlotTarget) => {
    const file = slotFile(design, target);
    const tone = target.kind === "slot" ? target.tone : null;
    const used =
      tone === null
        ? everyShirt
        : users[tone].length === 0
          ? null
          : `Prints on ${listNames(users[tone])}`;
    return {
      title: `For ${targetLabel(target)}`,
      target,
      file,
      tones: tone === null ? (["light", "dark"] as const) : [tone],
      usedBy: used,
      open: sameTarget(open, target),
      missing: tone !== null && file === null && users[tone].length > 0,
      emptyText: tone === null ? "No design selected" : `Choose the design for ${toneLabel(tone)}`,
      holding,
      uploading: uploading !== null && sameTarget(uploading.target, target) ? uploading.name : null,
    };
  };
  const targets: SlotTarget[] = split
    ? [
        { kind: "slot", tone: "light" },
        { kind: "slot", tone: "dark" },
      ]
    : [ONE];

  return (
    <div className="design-select design-strip">
      {own.length > 0 && (
        <div className="design-select__head">
          <span className="design-select__own">
            Also printing their own design:{" "}
            {own.map((colour, i) => (
              <span key={colour}>
                {i > 0 && ", "}
                <button
                  type="button"
                  className="design-select__colour"
                  onClick={() => onPreview(colour)}
                >
                  {cap(colour)}
                </button>
              </span>
            ))}
          </span>
        </div>
      )}

      <div
        className={
          holding ? "design-strip__card design-strip__card--holding" : "design-strip__card"
        }
        onDragEnter={(e) => hold.enter(e)}
        onDragLeave={() => hold.leave()}
        // Over the card but between targets: take the drop so the browser
        // doesn't navigate to the file, and do nothing with it.
        onDragOver={(e) => {
          if (hasFiles(e)) e.preventDefault();
        }}
        onDrop={(e) => {
          e.preventDefault();
          hold.reset();
        }}
      >
        <div
          className={
            split ? "design-strip__slots design-strip__slots--split" : "design-strip__slots"
          }
        >
          {targets.map((target) => (
            <Slot
              key={target.kind === "one" ? "one" : target.tone}
              {...view(target)}
              onChange={() => onOpen(sameTarget(open, target) ? null : target)}
              onFile={(f) => void upload(target, f)}
            />
          ))}
        </div>
        <div className="design-strip__foot">
          <button
            type="button"
            className="design-strip__mode"
            onClick={() => {
              onOpen(null);
              if (split) link();
              else onChange(unlinked(design));
            }}
          >
            {split
              ? "Use one design for all shirts"
              : "Use different designs on light & dark shirts"}
          </button>
          {failed !== null ? (
            <span className="design-strip__failed" role="alert">
              {failed}
            </span>
          ) : (
            <span className="design-strip__hint">
              <UploadSimpleIcon weight="bold" aria-hidden="true" />
              Drop a PNG on {split ? "a design" : "the design"} to upload it
            </span>
          )}
        </div>
      </div>

      {open !== null && (
        <div className="add-panel">
          <span className="section-label">Recent designs for {targetLabel(open)}</span>
          <div className="template-grid">
            {library.slice(0, RECENT).map((d) => (
              <button
                key={d.file}
                type="button"
                className={
                  slotFile(design, open) === d.file
                    ? "template-card template-card--active"
                    : "template-card"
                }
                // PRD 73: a ref with no prefix is the workspace root, so the
                // design's workspace-relative path is already the ref.
                onClick={() => pick(open, d.file)}
              >
                <span className="template-card__name">{d.name}</span>
                <span className="template-card__kind">{d.file}</span>
              </button>
            ))}
          </div>
          <div className="design-strip__panel-actions">
            <button
              type="button"
              className="btn-like btn-like--ghost btn-sm"
              onClick={() => {
                setFinding(open);
                onOpen(null);
              }}
            >
              Find a design…
            </button>
            <label className="btn-like btn-like--ghost btn-sm">
              Upload a PNG…
              <input
                type="file"
                accept="image/png"
                hidden
                onChange={(e) => {
                  const file = e.currentTarget.files?.[0];
                  e.currentTarget.value = "";
                  if (file === undefined) return;
                  onOpen(null);
                  void upload(open, file);
                }}
              />
            </label>
          </div>
        </div>
      )}

      {finding !== null && (
        <ArtworkPicker
          title={`Design for ${targetLabel(finding)}`}
          hint={
            finding.kind === "one"
              ? "Every colour prints it, apart from any with their own design."
              : users[finding.tone].length > 0
                ? `Prints on ${listNames(users[finding.tone])}.`
                : "No colour you sell uses it right now."
          }
          tile={finding.kind === "one" ? TILE.neutral : TILE[finding.tone]}
          current={slotFile(design, finding)}
          library={library}
          onPick={(ref) => pick(finding, ref)}
          onClose={() => setFinding(null)}
        />
      )}

      {choosing !== null && (
        <ChooseBaseDialog
          light={choosing.light}
          dark={choosing.dark}
          own={own}
          onKeep={(ref) => {
            setChoosing(null);
            onChange(keepOne(design, ref));
          }}
          onCancel={() => setChoosing(null)}
        />
      )}
    </div>
  );
}

function Slot({
  title,
  target,
  file,
  tones,
  usedBy,
  open,
  missing,
  emptyText,
  holding,
  uploading,
  onChange,
  onFile,
}: {
  title: string;
  target: SlotTarget;
  file: string | null;
  /** The shirts drawn beside it: both for one design, else its own. */
  tones: readonly Tone[];
  /** The "Prints on …" line; `null` when the slot is unused. */
  usedBy: string | null;
  open: boolean;
  /** Empty, and a colour the listing sells needs it. */
  missing: boolean;
  emptyText: string;
  /** A file is being held over the strip: every slot shows it is a target. */
  holding: boolean;
  /** The name of the file uploading into this slot. */
  uploading: string | null;
  onChange: () => void;
  onFile: (file: File) => void;
}) {
  const [over, setOver] = useState(false);
  const drag = useDragDepth(setOver);
  const label = targetLabel(target);
  const artwork = file === null ? null : listingDesignThumbnailUrl(refName(file));
  const cls = [
    "design-row",
    "design-row--slot",
    missing ? "design-row--missing" : "",
    open ? "design-row--open" : "",
    holding ? "design-row--target" : "",
    over ? "design-row--over" : "",
  ]
    .filter(Boolean)
    .join(" ");
  return (
    <section
      className={cls}
      aria-label={title}
      onDragEnter={(e) => drag.enter(e)}
      onDragLeave={() => drag.leave()}
      onDragOver={(e) => {
        if (hasFiles(e)) e.preventDefault();
      }}
      onDrop={(e) => {
        // Bubbles on to the card, which clears its own holding state.
        e.preventDefault();
        drag.reset();
        const dropped = e.dataTransfer.files[0];
        if (dropped !== undefined) onFile(dropped);
      }}
    >
      <div className="design-strip__shirts">
        {tones.map((tone) => (
          <ShirtThumb key={tone} cloth={TILE[tone]} artwork={uploading === null ? artwork : null} />
        ))}
        {uploading !== null && (
          <CircleNotchIcon className="design-strip__spin" weight="bold" aria-hidden="true" />
        )}
      </div>
      <div className="design-row__text">
        <div className="design-row__title">{title}</div>
        {uploading !== null ? (
          <div className="design-row__name" role="status">
            Uploading {uploading}…
          </div>
        ) : file !== null ? (
          <div className="design-row__name">{refName(file)}</div>
        ) : (
          <div className="design-row__name design-row__name--empty">{emptyText}</div>
        )}
        <div
          className={
            usedBy === null ? "design-row__users design-row__users--idle" : "design-row__users"
          }
        >
          {usedBy ?? "Not used — no colour you sell needs it"}
        </div>
        <button
          type="button"
          className="design-row__change"
          aria-label={`${file === null ? "Choose" : "Change"} design for ${label}`}
          aria-expanded={open}
          onClick={onChange}
        >
          {file === null ? "Choose" : "Change"} <CaretDownIcon weight="bold" aria-hidden="true" />
        </button>
      </div>
      {over && (
        <div className="design-strip__veil" aria-hidden="true">
          <UploadSimpleIcon weight="bold" />
          Drop to upload and use on {label}
        </div>
      )}
    </section>
  );
}

import { useEffect, useRef, useState } from "react";
import { createEtsySection, listCommonCopy, listEtsySections } from "../../api/listings";
import type { CommonCopySummary, EtsySectionSummary, ListingDetail } from "../../types";
import { AiChoiceDrawer } from "./aiSeo/AiChoiceDrawer";
import { DescriptionSourcePicker } from "./DescriptionSourcePicker";
import { MarketListingsPanel } from "./market/MarketListingsPanel";
import { AiSeoControl } from "./aiSeo/AiSeoControl";
import { AiTagsDrawer } from "./aiSeo/AiTagsDrawer";
import type { AiSeoMode } from "./aiSeo/useAiSeoMode";

/** Title/tags/description/section (phase 5).
 *
 * Section is a dropdown of the live shop's sections (`GET /api/etsy/sections`,
 * `EtsyShopClient.shop_sections` -- unscoped, needs only the workspace's app
 * key pair) when that list is available. Its inline create action uses the
 * signed-in client because Etsy requires `shops_w`. The field falls back to
 * free text for a workspace that hasn't configured a shop id or Etsy
 * credentials yet -- an ordinary state short of `setup`/`auth etsy`, not an
 * error. Pricing lives on its own tab. */

/** Etsy's own ceilings, mirrored from `config/listing.py`'s MAX_* constants.
 * Shown as counters rather than enforced here: the server is what refuses a
 * candidate (and says so through `field_errors`), and a field that silently
 * truncates what you paste is worse than one that tells you it is over. */
const MAX_TITLE_LENGTH = 140;
const MAX_TAGS = 13;
const CREATE_SECTION_VALUE = "create";

/** `check_copy_is_concrete`/`check_description_ref`
 * (`config/listing_validation.py`) file every description issue -- the empty
 * lead that blocks deployment, and a `ref` that will not resolve -- under
 * this one `where`, matching `_COPY_WHERE["description"]` exactly. Both are
 * shown together beneath the description fields, the same block issues the
 * page-level banner surfaces, but visible without leaving the tab. */
const DESCRIPTION_ISSUE_WHERE = "Listing Details › Description";

type Props = {
  detail: ListingDetail;
  onUpdate: (patch: Record<string, unknown>) => void;
  onFlush: () => void;
} & (
  | {
      kind?: "listing";
      /** AI Mode, owned by `ListingEditorShell` rather than by this tab : a request has to survive a tab switch, and the chain that starts
       * one begins at the design strip above the tabs. */
      aiSeo: AiSeoMode;
    }
  | {
      /** A listing template's Details (UI doc §3): no Brief, Title, Tags,
       * Description lead, AI Mode or market panel -- each listing in a batch
       * writes those for itself -- and a hint that its lead goes above this
       * body. */
      kind: "listing-template";
      aiSeo?: undefined;
    }
);

export function DetailsTab(props: Props) {
  const { detail, onUpdate, onFlush } = props;
  const aiSeo = props.kind === "listing-template" ? null : props.aiSeo;
  const [tagDraft, setTagDraft] = useState("");
  const [sections, setSections] = useState<EtsySectionSummary[]>([]);
  const [sectionsAvailable, setSectionsAvailable] = useState(false);
  const [creatingSection, setCreatingSection] = useState(false);
  const [sectionDraft, setSectionDraft] = useState("");
  const [sectionCreating, setSectionCreating] = useState(false);
  const [sectionCreateError, setSectionCreateError] = useState<string | null>(null);
  const [commonCopy, setCommonCopy] = useState<CommonCopySummary[]>([]);
  const [previewOpen, setPreviewOpen] = useState(false);
  const previewRef = useRef<HTMLDivElement>(null);
  const previewButtonRef = useRef<HTMLButtonElement>(null);
  const phase = aiSeo?.phase ?? null;
  const proposal = aiSeo?.proposal ?? null;
  const [trackedPhase, setTrackedPhase] = useState(phase);
  const [drawerMotion, setDrawerMotion] = useState(false);
  if (phase !== trackedPhase) {
    setTrackedPhase(phase);
    if (trackedPhase === "loading") {
      setDrawerMotion(proposal !== null && document.visibilityState === "visible");
    }
  }
  if (proposal === null && drawerMotion) setDrawerMotion(false);
  const aiModeButtonRef = useRef<HTMLButtonElement>(null);
  const titleDrawerRef = useRef<HTMLDivElement>(null);
  const hadAiSeoProposal = useRef(false);
  const tags = detail.etsy.tags;
  const titleError = detail.field_errors["etsy.title"];
  const sectionError = detail.field_errors["etsy.section"];
  const title = detail.etsy.title;
  const description = detail.etsy.description;
  const descriptionIssues = detail.issues.filter((i) => i.where === DESCRIPTION_ISSUE_WHERE);

  useEffect(() => {
    listEtsySections().then((result) => {
      setSectionsAvailable(result.available);
      setSections(result.sections);
    });
  }, []);

  useEffect(() => {
    listCommonCopy().then(setCommonCopy);
  }, []);

  useEffect(() => {
    if (!previewOpen) return;
    function onPointerDown(event: PointerEvent) {
      if (!previewRef.current?.contains(event.target as Node)) setPreviewOpen(false);
    }
    function onKeyDown(event: KeyboardEvent) {
      if (event.key === "Escape") {
        setPreviewOpen(false);
        previewButtonRef.current?.focus();
      }
    }
    document.addEventListener("pointerdown", onPointerDown);
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("pointerdown", onPointerDown);
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [previewOpen]);

  // Accessibility (`docs/features/ai-seo-20260922/interactions.md` section 10):
  // "Keyboard focus moves to the first useful control in the first opened
  // drawer after generation, and returns to a sensible field or AI Mode
  // control when the last drawer closes." Every drawer opens together right
  // after a successful `generate()` (a fresh proposal starts every field
  // unresolved), so the title drawer -- first in the field order -- is
  // always "the first opened drawer" at that moment; closing every drawer
  // (rejecting, choosing, or resolving each one) is exactly when `proposal`
  // goes back to `null`.
  useEffect(() => {
    const hasProposal = proposal !== null;
    if (hasProposal && !hadAiSeoProposal.current) {
      titleDrawerRef.current?.querySelector<HTMLButtonElement>(".seo-choice-list button")?.focus();
    } else if (!hasProposal && hadAiSeoProposal.current) {
      aiModeButtonRef.current?.focus();
    }
    hadAiSeoProposal.current = hasProposal;
  }, [proposal]);

  function setBodySource(source: string | null) {
    if (source === null) {
      onUpdate({
        etsy: { description: { ...description, text: description.text ?? "", ref: null } },
      });
      return;
    }
    onUpdate({ etsy: { description: { ...description, text: null, ref: source } } });
  }

  function commitTags() {
    const additions = tagDraft
      .split(",")
      .map((t) => t.trim())
      .filter((t) => t !== "" && !tags.includes(t));
    if (additions.length > 0) {
      onUpdate({ etsy: { tags: [...tags, ...additions] } });
    }
    setTagDraft("");
  }

  function removeTag(tag: string) {
    onUpdate({ etsy: { tags: tags.filter((t) => t !== tag) } });
  }

  async function commitSection() {
    const title = sectionDraft.trim();
    if (title === "") return;
    setSectionCreating(true);
    setSectionCreateError(null);
    try {
      const created = await createEtsySection(title);
      setSections((current) => [...current, created]);
      setCreatingSection(false);
      setSectionDraft("");
      onUpdate({ etsy: { section: created.title } });
      onFlush();
    } catch {
      setSectionCreateError("Could not create the section on Etsy. Check your Etsy sign-in.");
    } finally {
      setSectionCreating(false);
    }
  }

  const fields = (
    <div className="details-tab">
      <fieldset className="seo-details-fieldset">
        <legend className="seo-details-legend">Listing details</legend>

        {aiSeo !== null && (
          <>
            <div className="seo-brief-row">
              <div className="field">
                <label htmlFor="details-brief">Brief</label>
                <textarea
                  id="details-brief"
                  placeholder="Describe the design and include any exact words shown in it."
                  value={detail.brief}
                  onChange={(event) => onUpdate({ brief: event.target.value })}
                  onBlur={onFlush}
                />
              </div>
              <AiSeoControl mode={aiSeo} buttonRef={aiModeButtonRef} />
            </div>

            <div className={titleError ? "field field--invalid" : "field"}>
              <label htmlFor="details-title">Title</label>
              <div className="field__line">
                <div className="field__stack">
                  <input
                    id="details-title"
                    className="input"
                    type="text"
                    placeholder="The title shoppers see on Etsy"
                    value={detail.etsy.title}
                    onChange={(event) => onUpdate({ etsy: { title: event.target.value } })}
                    onBlur={onFlush}
                  />
                  {titleError && <span className="field__error">{titleError}</span>}
                  {aiSeo.proposal?.resolution.title === "pending" && (
                    <div ref={titleDrawerRef}>
                      <AiChoiceDrawer
                        enter={drawerMotion}
                        field="title"
                        options={aiSeo.proposal.proposal.titles}
                        staleReason={aiSeo.staleReason}
                        rationale={aiSeo.proposal.proposal.rationale}
                        warnings={aiSeo.proposal.proposal.warnings}
                        observedText={aiSeo.proposal.proposal.observed_text}
                        onChoose={aiSeo.chooseTitle}
                        onReject={aiSeo.rejectTitle}
                      />
                    </div>
                  )}
                </div>
                <span className="field__count">
                  {title.length} / {MAX_TITLE_LENGTH}
                </span>
              </div>
            </div>

            <div className="field">
              <label htmlFor="details-tag-draft">Tags</label>
              <div className="chips">
                {tags.map((tag) => (
                  <span key={tag} className="chip">
                    {tag}
                    <span className="chip__x" onClick={() => removeTag(tag)}>
                      ×
                    </span>
                  </span>
                ))}
                {tags.length === 0 && <span className="chips__empty">No tags yet</span>}
              </div>
              <div className="field__line">
                <div className="field__stack">
                  <input
                    id="details-tag-draft"
                    className="input tag-paste"
                    type="text"
                    placeholder="Type or paste tags, comma separated — press Enter to add"
                    value={tagDraft}
                    onChange={(event) => setTagDraft(event.target.value)}
                    onKeyDown={(event) => {
                      if (event.key === "Enter") {
                        event.preventDefault();
                        commitTags();
                      }
                    }}
                    onBlur={commitTags}
                  />
                  {aiSeo.proposal?.resolution.tags === "pending" && (
                    <AiTagsDrawer
                      enter={drawerMotion}
                      tags={aiSeo.proposal.proposal.tags}
                      selected={tags}
                      staleReason={aiSeo.staleReason}
                      rationale={aiSeo.proposal.proposal.rationale}
                      warnings={aiSeo.proposal.proposal.warnings}
                      observedText={aiSeo.proposal.proposal.observed_text}
                      onToggle={aiSeo.toggleTag}
                      onAcceptBest={aiSeo.acceptBestTags}
                      onClose={aiSeo.closeTags}
                    />
                  )}
                </div>
                <span className="field__count">
                  {tags.length} / {MAX_TAGS}
                </span>
              </div>
            </div>

            <div className="field">
              <label htmlFor="details-description-lead">Description Lead</label>
              <textarea
                id="details-description-lead"
                value={description.lead}
                onChange={(event) =>
                  onUpdate({
                    etsy: { description: { ...description, lead: event.target.value } },
                  })
                }
                onBlur={onFlush}
              />
              {aiSeo.proposal?.resolution.lead === "pending" && (
                <AiChoiceDrawer
                  enter={drawerMotion}
                  field="description lead"
                  options={aiSeo.proposal.proposal.description_leads}
                  staleReason={aiSeo.staleReason}
                  rationale={aiSeo.proposal.proposal.rationale}
                  warnings={aiSeo.proposal.proposal.warnings}
                  observedText={aiSeo.proposal.proposal.observed_text}
                  onChoose={aiSeo.chooseLead}
                  onReject={aiSeo.rejectLead}
                />
              )}
            </div>
          </>
        )}

        <div className={descriptionIssues.length > 0 ? "field field--invalid" : "field"}>
          <label htmlFor="details-description-source">Description Body</label>
          <DescriptionSourcePicker
            value={description.ref ?? null}
            items={commonCopy}
            onSelect={(source) => {
              setBodySource(source);
              onFlush();
            }}
          />

          {description.ref === null && (
            <textarea
              id="details-description-text"
              aria-label="Description body"
              value={description.text ?? ""}
              onChange={(event) =>
                onUpdate({
                  etsy: { description: { ...description, text: event.target.value, ref: null } },
                })
              }
              onBlur={onFlush}
            />
          )}

          {descriptionIssues.map((issue, index) => (
            <span key={index} className="field__error">
              {issue.message}
            </span>
          ))}
          {aiSeo === null && (
            <span className="field__hint">
              Each listing's own description lead is placed above this body.
            </span>
          )}
        </div>

        <div className="description-preview-control" ref={previewRef}>
          <button
            ref={previewButtonRef}
            type="button"
            className="description-preview-control__link"
            aria-expanded={previewOpen}
            aria-controls="details-description-preview"
            onClick={() => setPreviewOpen((open) => !open)}
          >
            Description preview
          </button>
          {/* The server's own join of lead + resolved body
              (`Workspace.compose_description`) -- rendered as-is, never
              rejoined here, so this can never disagree with what Printify,
              Etsy, and the deploy comparison view will actually send
              (AI SEO implementation plan, "Description and common-copy
              boundaries"). */}
          {previewOpen && (
            <div
              id="details-description-preview"
              className="description-preview-card"
              role="region"
              aria-label="Description preview"
            >
              <strong className="description-preview-card__title">Description preview</strong>
              <p className="description-preview">{detail.description_composed}</p>
            </div>
          )}
        </div>

        <div className={sectionError ? "field field--invalid" : "field"}>
          <label htmlFor="details-section">Section</label>
          {sectionsAvailable ? (
            <select
              id="details-section"
              className="input"
              value={
                creatingSection
                  ? CREATE_SECTION_VALUE
                  : String(
                      sections.find((section) => section.title === detail.etsy.section)?.id ?? "",
                    )
              }
              onChange={(event) => {
                if (event.target.value === CREATE_SECTION_VALUE) {
                  setCreatingSection(true);
                  setSectionCreateError(null);
                  return;
                }
                setCreatingSection(false);
                const selected = sections.find(
                  (section) => String(section.id) === event.target.value,
                );
                onUpdate({ etsy: { section: selected?.title ?? null } });
                onFlush();
              }}
            >
              <option value="">No section</option>
              {sections.map((s) => (
                <option key={s.id} value={String(s.id)}>
                  {s.title}
                </option>
              ))}
              <option value={CREATE_SECTION_VALUE}>Create new section…</option>
            </select>
          ) : (
            <input
              id="details-section"
              className="input"
              type="text"
              value={detail.etsy.section ?? ""}
              onChange={(event) => onUpdate({ etsy: { section: event.target.value || null } })}
              onBlur={onFlush}
            />
          )}
          {creatingSection && (
            <form
              className="section-create"
              onSubmit={(event) => {
                event.preventDefault();
                void commitSection();
              }}
            >
              <label htmlFor="details-new-section">New section name</label>
              <input
                id="details-new-section"
                className="input"
                type="text"
                autoFocus
                value={sectionDraft}
                onChange={(event) => setSectionDraft(event.target.value)}
              />
              <button
                className="btn btn-primary"
                type="submit"
                disabled={sectionCreating || sectionDraft.trim() === ""}
              >
                {sectionCreating ? "Creating…" : "Create section"}
              </button>
              <button
                className="btn btn-ghost"
                type="button"
                disabled={sectionCreating}
                onClick={() => {
                  setCreatingSection(false);
                  setSectionDraft("");
                  setSectionCreateError(null);
                }}
              >
                Cancel
              </button>
              {sectionCreateError && (
                <span className="field__error" role="alert">
                  {sectionCreateError}
                </span>
              )}
            </form>
          )}
          {sectionError && <span className="field__error">{sectionError}</span>}
        </div>

        {/* No Materials field: they belong to the garment profile, which
            every listing on it deploys (docs/features/listings-ui-20260915/spec.md), so a
            read-only copy here only looked editable. */}
      </fieldset>
    </div>
  );

  // The top listings panel sits beside the fields once there is a search to
  // show (docs/features/market-seo-20260924/interactions.md, section 3). Without one the
  // fields keep their own width: an empty "run AI Mode" card would be noise
  // on every new listing. The wrapper is there either way, so the fields are
  // never remounted -- losing the seller's focus and caret -- when research
  // starts mid-edit and the panel appears.
  return (
    <div className={aiSeo === null || aiSeo.market === null ? undefined : "mkt-layout"}>
      {fields}
      {aiSeo !== null && aiSeo.market !== null && (
        <MarketListingsPanel state={aiSeo.market} proposal={aiSeo.proposal?.proposal ?? null} />
      )}
    </div>
  );
}

import { useEffect, useState } from "react";
import { listTemplates } from "../../api/calibrator";
import { listCommonMedia, listListingMediaFiles } from "../../api/listings";
import { listListingTemplateMediaFiles } from "../../api/listingTemplates";
import { Lightbox, type LightboxItem } from "../../components/Lightbox";
import {
  type Artwork,
  type MediaOwner,
  mediaKind,
  mediaLabel,
  pictureFor,
  sceneSource,
} from "../../media";
import type { MediaFileSummary, ListingDetail, TemplateSummary } from "../../types";
import { MediaLocator } from "./MediaLocator";
import { MediaReel } from "./MediaReel";
import { type Focus, viewFocus } from "./focus";
import * as edits from "./mediaEdits";

/**
 * Listing Images: a locator to add from, a preview pane to judge by, and the
 * reel that is the listing's actual `media:`.
 *
 * This module is the three of them side by side and the state they share --
 * what the preview is pointing at, which tile is selected, whether the
 * carousel is open. Everything else belongs to one of them: browsing is
 * `MediaLocator`'s, the drag is `MediaReel`'s, what a picture's URL is is
 * `media`'s, and what a click *changes* is `mediaEdits`'s.
 *
 * It was one 733-line function holding all of that, thirteen `useState` deep,
 * with ADR-0030's swatch-source gate as a callback three levels inside it. The
 * split is by question: the rule about what `media:` may contain is now
 * callable without a DOM, and a test that clicks one × no longer has to mount
 * a template picker first.
 *
 * The **preview pane** and the reel's tiles ask for deliberately different
 * pictures. A tile is the template's bare photo, downscaled, because a tile is
 * picked out of a row and running the real pipeline once per tile would cost a
 * render per listing image just to open the tab. The pane is the opposite
 * question: one image, the listing's real artwork composited onto the
 * template's saved geometry at the photo's own resolution, large enough to
 * judge -- and clicking it opens the whole reel in the calibrator's lightbox,
 * where arrow keys walk the set and `1:1` stops the browser downsampling it.
 * Comparing neighbours is the point: the fault worth catching is usually "this
 * one colour is wrong".
 */

interface Props {
  detail: ListingDetail;
  onUpdate: (patch: Record<string, unknown>) => void;
  /** What the renders composite, when it is not the listing's own design:
   * the listing-template editor's preview design (UI doc §3). */
  artwork?: Artwork | null;
  /** Whose `./` files these are, when not the listing's: a listing
   * template's. One with `copies` is not saved yet and has no directory. */
  owner?: MediaOwner | null;
}

export function ImagesTab({ detail, onUpdate, artwork, owner }: Props) {
  const [templates, setTemplates] = useState<TemplateSummary[]>([]);
  const [shared, setShared] = useState<MediaFileSummary[]>([]);
  const [local, setLocal] = useState<MediaFileSummary[]>([]);
  const [status, setStatus] = useState("");
  const [focus, setFocus] = useState<Focus | null>(null);
  const [lightboxIndex, setLightboxIndex] = useState<number | null>(null);
  const [actualSize, setActualSize] = useState(false);

  useEffect(() => {
    listTemplates()
      .then(setTemplates)
      .catch(() => setStatus("failed to load templates"));
    listCommonMedia()
      .then(setShared)
      .catch(() => setStatus("failed to load shared files"));
  }, []);

  // A draft has no directory, so nothing of its own to list.
  const listing: MediaOwner | null =
    owner === undefined ? (detail.name ? { kind: "listing", name: detail.name } : null) : owner;
  const directory = listing === null || listing.copies !== undefined ? null : listing;
  const directoryKind = directory?.kind ?? null;
  const directoryName = directory?.name ?? null;
  useEffect(() => {
    if (directoryName === null) return;
    (directoryKind === "listing-template"
      ? listListingTemplateMediaFiles(directoryName)
      : listListingMediaFiles(directoryName)
    )
      .then(setLocal)
      .catch(() => setStatus("failed to load this listing's files"));
  }, [directoryKind, directoryName]);

  // Each layer resolved from the saved listing, multi-colour scenes too
  // (A35) -- or, in the listing-template editor, its preview design.
  const scene: Artwork | null =
    artwork !== undefined ? artwork : sceneSource(detail.name, detail.design_content_hash);

  /** Every edit is a patch or nothing: a rule that declines (the twentieth
   * image is already there) returns `null` rather than an unchanged document,
   * so an autosave is never armed for a change that did not happen. */
  function apply(patch: Record<string, unknown> | null) {
    if (patch !== null) onUpdate(patch);
  }

  /** The reel, as the lightbox reads it. Its order is the order Etsy will
   * show the images in, which is the order worth stepping through. */
  const lightboxItems: LightboxItem[] = detail.media.map((entry, index) => ({
    id: `${mediaLabel(entry)}-${index}`,
    label: mediaLabel(entry),
    url: pictureFor(entry, scene, "full", listing),
    kind: mediaKind(entry),
  }));

  const view = focus === null ? null : viewFocus(focus, detail, templates, scene, listing);
  // The reel highlights whatever the stage is showing, wherever the pointing
  // came from.
  const selectedIndex = view !== null && view.reelIndex >= 0 ? view.reelIndex : null;

  function toggleFocused() {
    if (focus === null) return;
    apply(
      focus.kind === "file"
        ? edits.toggleFile(detail, focus.asset.ref)
        : edits.toggleEntry(detail, focus.template, focus.colour),
    );
  }

  return (
    <div className="images-tab">
      <MediaLocator
        detail={detail}
        templates={templates}
        local={directory === null ? null : local}
        owner={listing}
        shared={shared}
        onToggleTemplate={(template, colour) => apply(edits.toggleEntry(detail, template, colour))}
        onToggleFile={(ref) => apply(edits.toggleFile(detail, ref))}
        onAddMissingColours={(template) => apply(edits.addEveryMissingColour(detail, template))}
        onToggleSwatchSource={(template) => apply(edits.toggleSwatchSource(detail, template))}
        onFocus={setFocus}
      />

      <div className="images-right">
        <div className="preview-pane">
          <div className="preview-stage preview-stage--large">
            {view === null && (
              <div className="image-placeholder">
                <span>Point at something on the left</span>
              </div>
            )}
            {view?.kind === "video" && (
              /* Its own controls, not the carousel button: a click on a
                  clip is play or seek (ADR-0045). Keyed by the file, so
                  pointing at another clip starts that one afresh. */
              <video
                key={view.picture}
                className="preview-stage__video"
                src={view.picture}
                aria-label={view.title}
                controls
                playsInline
                preload="metadata"
              />
            )}
            {view?.kind === "image" && (
              /* A button, not a bare `<img onClick>`: opening the carousel
                  is an action, and the keyboard has to be able to take it. */
              <button
                type="button"
                className="preview-stage__open"
                title={
                  view.inListing
                    ? "Open the listing's images at full size"
                    : "Add it to the listing to open it at full size"
                }
                onClick={() => {
                  if (view.reelIndex >= 0) setLightboxIndex(view.reelIndex);
                }}
              >
                <img src={view.picture} alt={view.title} />
              </button>
            )}
          </div>

          {/* Always there, so the reel below does not jump when the stage
              first gets something to show. */}
          <div className="preview-foot">
            {view !== null && (
              <>
                <span className="preview-meta">
                  <span className="preview-meta__title">{view.title}</span>
                  <span className="preview-meta__path">{view.path}</span>
                  {view.notes.map((note) => (
                    <span
                      key={note.message}
                      className={`preview-meta__note preview-meta__note--${note.severity}`}
                    >
                      {note.message}
                    </span>
                  ))}
                </span>
                <span className="preview-actions">
                  <button
                    type="button"
                    className={
                      view.inListing
                        ? "btn-like btn-like--ghost btn-sm"
                        : "btn-like btn-like--primary btn-sm"
                    }
                    onClick={toggleFocused}
                  >
                    {view.inListing ? "Remove from listing" : "+ Add to listing"}
                  </button>
                </span>
              </>
            )}
          </div>
        </div>

        <MediaReel
          media={detail.media}
          scene={scene}
          swatchTemplate={detail.etsy.variation_images ?? null}
          selectedIndex={selectedIndex}
          listing={listing}
          files={directory === null ? shared : [...local, ...shared]}
          onRemove={(index) => apply(edits.removeAt(detail, index))}
          onReorder={(from, to) => apply(edits.reorder(detail, from, to))}
          onFocus={setFocus}
        />

        <p role="status" className="app__status">
          {status}
        </p>
      </div>

      {lightboxIndex !== null && lightboxItems[lightboxIndex] !== undefined && (
        <Lightbox
          items={lightboxItems}
          index={lightboxIndex}
          actualSize={actualSize}
          onActualSizeChange={setActualSize}
          onIndexChange={setLightboxIndex}
          onClose={() => setLightboxIndex(null)}
        />
      )}
    </div>
  );
}

import type { Issue, IssueTab } from "../../types";

/**
 * The validation banner above the tab strip (phase 5), from the mockup's
 * `issues` markup.
 *
 * Two things it must not do, both learned the hard way:
 *
 * * **Summarise only the blocks.** A one-item summary sitting above three
 * rows, two of which it never mentioned, reads as a bug in the count. Both
 * severities are counted and joined.
 * * **Offer an action that does nothing.** An issue already on the open tab
 * gets the word "Below", not a "Fix →" button that would re-select the tab
 * it is already on.
 *
 * The list itself is whatever the server returned -- `config/listing_validation.py`
 * owns which rules exist and what they say; nothing here re-derives an issue.
 *
 * **Every row is a warning, never an error.** Nothing in this list
 * stops the listing being saved -- naming it writes it -- so an error's red
 * circle, and a summary saying the problems "block this listing", told a
 * seller their work was being refused when it was on disk. What a `block`
 * issue actually stops is the *deploy*, and it says so in words on its own
 * row rather than through colour alone: the tag is what separates "fix this
 * before deploying" from a `warn` that is only advice (no tags, say), now
 * that both wear the same icon.
 *
 * Informational notes are not global editor issues. For example, ADR-0045's
 * stripped-audio note remains available beside the focused clip (and may be
 * reported by a plan), but putting it over every editor tab reads as a
 * warning about something the seller cannot fix.
 */

interface Props {
  issues: Issue[];
  activeTab?: IssueTab;
  /** Absent where there are no tabs to jump to -- the listing-template
   * *name it* page, which is read only -- and the rows then offer no action. */
  onJumpTo?: (tab: IssueTab) => void;
  /** A listing template's wording (the `template-unsaved` mockup): it never
   * deploys, so a block is what stops the *save*, and no row says
   * *Prevents deploying*. */
  subject?: "listing" | "listing-template";
  when?: string;
}

function summarise(issues: Issue[], subject: Props["subject"]): string {
  const blocks = issues.filter((i) => i.severity === "block").length;
  const warns = issues.filter((i) => i.severity === "warn").length;
  const parts: string[] = [];
  const stops = subject === "listing-template" ? "this template saves" : "deploying";
  if (blocks > 0) parts.push(`${blocks} to fix before ${stops}`);
  // "Other" only beside a blocker count, where it says these are the ones
  // that do not stop a deploy; on its own it would be other than nothing.
  const other = blocks > 0 ? "other " : "";
  if (warns > 0) parts.push(warns === 1 ? `1 ${other}warning` : `${warns} ${other}warnings`);
  return parts.join(" · ");
}

/** A filled amber triangle with a dark mark, rather than an outline in the
 * text colour. The outline took `--color-accent-2-700`, which in this palette
 * is an olive that reads as grey -- a warning nobody recognises as one. The
 * colours live on the shapes themselves so the icon cannot drift back into
 * the surrounding text colour. */
function WarnIcon() {
  return (
    <svg viewBox="0 0 24 24">
      <path
        d="M10.3 3.9a2 2 0 0 1 3.4 0l8.1 14.1A2 2 0 0 1 20.1 21H3.9a2 2 0 0 1-1.7-3z"
        fill="var(--color-warning)"
      />
      <path
        d="M12 9v4.6M12 17.2v.01"
        fill="none"
        stroke="var(--color-warning-ink)"
        strokeWidth="2.2"
        strokeLinecap="round"
      />
    </svg>
  );
}

export function IssuesBanner({
  issues,
  activeTab,
  onJumpTo,
  subject = "listing",
  when = "Checked against this listing’s own configuration",
}: Props) {
  const visible = issues.filter((issue) => issue.severity !== "info");
  if (visible.length === 0) return null;

  return (
    <div className="issues">
      <div className="issues__head">
        <span className="issues__summary issues__summary--warn">{summarise(visible, subject)}</span>
        <span className="issues__when">{when}</span>
      </div>
      {visible.map((issue, index) => (
        <div key={`${issue.tab}-${issue.where}-${index}`} className="issue issue--warn">
          <span className="issue__icon" aria-hidden="true">
            <WarnIcon />
          </span>
          <span className="issue__body">
            <span className="issue__text">{issue.message}</span>
            <span className="issue__where">
              {issue.where}
              {issue.severity === "block" && subject === "listing" && (
                <span className="issue__deploy">Prevents deploying</span>
              )}
            </span>
          </span>
          {onJumpTo === undefined ? null : issue.tab === activeTab ? (
            <span className="issue__fix issue__fix--here">Below</span>
          ) : (
            <button
              type="button"
              className="issue__fix"
              aria-label={`Fix: ${issue.message}`}
              onClick={() => onJumpTo(issue.tab)}
            >
              Fix &rarr;
            </button>
          )}
        </div>
      ))}
    </div>
  );
}

import { ArrowCounterClockwiseIcon } from "@phosphor-icons/react/dist/csr/ArrowCounterClockwise";
import { ArrowLeftIcon } from "@phosphor-icons/react/dist/csr/ArrowLeft";
import { ArrowsClockwiseIcon } from "@phosphor-icons/react/dist/csr/ArrowsClockwise";
import { CheckCircleIcon } from "@phosphor-icons/react/dist/csr/CheckCircle";
import { PauseCircleIcon } from "@phosphor-icons/react/dist/csr/PauseCircle";
import { PlayCircleIcon } from "@phosphor-icons/react/dist/csr/PlayCircle";
import { StackPlusIcon } from "@phosphor-icons/react/dist/csr/StackPlus";
import { TrashIcon } from "@phosphor-icons/react/dist/csr/Trash";
import { type ReactNode, useState } from "react";
import { setReviewed, type ListingBatch } from "../../api/batches";
import { deleteListing } from "../../api/listings";
import { ActionDivider, ActionLink } from "../../components/ActionLink";
import { ConfirmDialog } from "../../components/ConfirmDialog";
import { OpenInMenu } from "../../components/OpenInMenu";
import { hasOpenTargets } from "../../components/openOn";
import type { Patch } from "../../hooks/useAutosave";
import type { ListingDetail } from "../../types";
import {
  deleteDetails,
  deleteLabel,
  deleteTitle,
  type Gesture,
  LIFECYCLE_OF,
} from "../listingLifecycle";

/**
 * The listing editor's side of its head (UI doc, *The editor head* and §8):
 * Back to batch in the breadcrumb's place, and the action row's contents.
 */

/** Back to batch, in the breadcrumb's place, only when the editor was opened
 * from the batch summary (`?batch=`). It names its batch in its tooltip, so
 * the identity row keeps its room for the name and Deploy. */
export function BackToBatch({
  batch,
  member,
  onBack,
}: {
  batch: string;
  member: ListingBatch | null;
  onBack: (batch: string) => void;
}) {
  const label = member !== null && member.batch_id === batch ? ` ${member.label}` : "";
  return (
    <button
      type="button"
      className="back-crumb"
      title={`Back to batch${label}`}
      onClick={() => onBack(batch)}
    >
      <ArrowLeftIcon aria-hidden="true" />
      Back to batch
    </button>
  );
}

/** The lifecycle gestures other than delete, as the action row words them.
 * `cancel` is the table's Undo on a pending delete. */
const GESTURES: Record<Exclude<Gesture, "delete">, { label: string; icon: ReactNode }> = {
  cancel: {
    label: "Undo mark for deletion",
    icon: <ArrowCounterClockwiseIcon aria-hidden="true" />,
  },
  retire: { label: "Retire", icon: <PauseCircleIcon aria-hidden="true" /> },
  "un-retire": { label: "Un-retire", icon: <PlayCircleIcon aria-hidden="true" /> },
  renew: { label: "Renew", icon: <ArrowsClockwiseIcon aria-hidden="true" /> },
};

/**
 * The listing's action row: Open in, Create listing template, then Mark
 * reviewed for a batch's listing and the listing's lifecycle gestures --
 * exactly the Listings table's, as the server serves them on the detail
 *, with the table's confirmation for deleting.
 *
 * Delete goes through `DELETE`, like the table, after flushing: a wipe
 * leaves the editor for Listings; a mark adopts what the server answered.
 * The other gestures are ordinary edits to `lifecycle`, sent at once through
 * the editor's own autosave, whose response carries the new status.
 */
export function ListingActions({
  detail,
  member,
  setMember,
  update,
  adopt,
  flush,
  onCreateTemplate,
  onDeleted,
}: {
  detail: ListingDetail;
  member: ListingBatch | null;
  setMember: (member: ListingBatch) => void;
  update: (patch: Patch) => void;
  adopt: (patch: Patch) => void;
  flush: () => Promise<void>;
  onCreateTemplate: () => void;
  onDeleted: () => void;
}) {
  const [confirming, setConfirming] = useState(false);
  const [error, setError] = useState("");
  const name = detail.name;

  function review(next: boolean) {
    if (member === null) return;
    setReviewed(member.batch_id, member.row_id, next)
      .then((batch) => {
        setError("");
        const row = batch.rows.find((r) => r.id === member.row_id);
        setMember({ ...member, reviewed: row?.reviewed ?? next });
      })
      .catch((exc: Error) => setError(exc.message));
  }

  function runGesture(gesture: Exclude<Gesture, "delete">) {
    setError("");
    update({ lifecycle: LIFECYCLE_OF[gesture] });
    void flush();
  }

  async function confirmDelete() {
    setConfirming(false);
    setError("");
    try {
      await flush();
      const row = await deleteListing(name);
      if (row === null) {
        onDeleted();
        return;
      }
      // Already written: shown, not saved again.
      adopt({ lifecycle: "deleted", status: row.status, gestures: row.gestures });
    } catch {
      setError(`Could not ${deleteLabel(detail).toLowerCase()} ${name}`);
    }
  }

  return (
    <>
      {hasOpenTargets(detail.etsy_listing_id, detail.printify_product_id) && (
        <OpenInMenu
          variant="action"
          etsyListingId={detail.etsy_listing_id}
          printifyProductId={detail.printify_product_id}
        />
      )}
      <ActionLink icon={<StackPlusIcon aria-hidden="true" />} onClick={onCreateTemplate}>
        Create listing template
      </ActionLink>
      {(member !== null || detail.gestures.length > 0) && <ActionDivider />}
      {member !== null && (
        <ActionLink
          icon={
            <CheckCircleIcon weight={member.reviewed ? "fill" : "regular"} aria-hidden="true" />
          }
          {...(member.reviewed ? { tone: "done" as const } : {})}
          aria-pressed={member.reviewed}
          title={
            member.reviewed
              ? "Mark needs review"
              : member.reviewable
                ? undefined
                : "Available once the batch has drafted this listing"
          }
          disabled={!member.reviewable}
          onClick={() => review(!member.reviewed)}
        >
          {member.reviewed ? "Reviewed" : "Mark reviewed"}
        </ActionLink>
      )}
      {detail.gestures.map((gesture) =>
        gesture === "delete" ? (
          <ActionLink
            key={gesture}
            tone="danger"
            icon={<TrashIcon aria-hidden="true" />}
            onClick={() => setConfirming(true)}
          >
            {deleteLabel(detail)}
          </ActionLink>
        ) : (
          <ActionLink
            key={gesture}
            icon={GESTURES[gesture].icon}
            onClick={() => runGesture(gesture)}
          >
            {GESTURES[gesture].label}
          </ActionLink>
        ),
      )}
      {error && (
        <span className="action-row__error" role="alert">
          {error}
        </span>
      )}
      {confirming && (
        <ConfirmDialog
          title={deleteTitle(detail)}
          confirmLabel={deleteLabel(detail)}
          details={deleteDetails(detail)}
          onConfirm={() => void confirmDelete()}
          onCancel={() => setConfirming(false)}
        />
      )}
    </>
  );
}

import { useState } from "react";
import { templateThumbnailUrl } from "../../api/calibrator";
import { MutedClip } from "../../components/MutedClip";
import { useHoverPlay } from "../../hooks/useHoverPlay";
import { isInMedia, mediaKind, missingColours, pictureFor, type MediaOwner } from "../../media";
import type { ListingDetail, MediaFileSummary, TemplateSummary } from "../../types";
import type { Focus } from "./focus";
import { MAX_VIDEOS } from "./mediaEdits";

/**
 * The half of the Listing Images tab that *offers* things: browse the two
 * things `media:` can hold, and add one.
 *
 * The segmented control is which half is being browsed -- **Mockup templates**
 * (a `{template, colour}` entry, rendered per listing) and **Files** (a file
 * ref uploaded as-is: a sizing chart, care instructions, a size-guide video).
 * One control rather than two panels because they fill the same gallery.
 *
 * *Files* is one list in two groups, one per root a ref can name:
 * *This listing* for the listing's own directory and *Shared* for
 * `common-media/`. The ref roots are an implementation detail rather than
 * useful navigation, and an empty root is omitted. Images and videos sit together, because `media:` is one
 * gallery; a video is drawn by a muted `<video>` from its own first
 * frame, carries its length, and plays on hover.
 *
 * Its own state is what it is *showing* (which half, the search, which template
 * is expanded). What a click *means* belongs to `mediaEdits`, and where the
 * preview is pointing belongs to the tab, because the preview pane and the reel
 * both read it.
 */

interface Props {
  detail: ListingDetail;
  templates: TemplateSummary[];
  /** The listing's own files, or `null` for a draft, which has no directory
   * yet and so no *This listing* group. */
  local: readonly MediaFileSummary[] | null;
  shared: readonly MediaFileSummary[];
  onToggleTemplate: (template: string, colour: string | null) => void;
  onToggleFile: (ref: string) => void;
  onAddMissingColours: (template: string) => void;
  onToggleSwatchSource: (template: string) => void;
  onFocus: (focus: Focus) => void;
  /** Whose `./` files `local` are: the listing by default, or a listing
   * template, whose group reads *This template* (UI doc, *Existing
   * components the template editor needs*). */
  owner?: MediaOwner | null;
}

/** Which half of `media:` the locator is browsing. */
type LocatorMode = "templates" | "files";

function kindLabel(kind: TemplateSummary["kind"]): string {
  if (kind === "colour-matrix") return "Colour matrix · one photo per colour";
  if (kind === "multiple") return "Multiple · several garments in one photo";
  if (kind === "single") return "Single · one fixed photo";
  return "";
}

/** `0:06`, `1:15` -- a clip's length as the badge shows it. */
function clipLength(seconds: number): string {
  const whole = Math.round(seconds);
  return `${Math.floor(whole / 60)}:${String(whole % 60).padStart(2, "0")}`;
}

interface FileTileProps {
  asset: MediaFileSummary;
  listing: MediaOwner | string | null;
  inListing: boolean;
  unavailable: string | null;
  onToggle: () => void;
  onFocus: () => void;
}

/** One file in the list: a picture for an image, a first frame and a length
 * for a video. */
function FileTile({ asset, listing, inListing, unavailable, onToggle, onFocus }: FileTileProps) {
  const { ref: clipRef, play, rest } = useHoverPlay();
  const [length, setLength] = useState<number | null>(null);
  const isVideo = asset.kind === "video";

  return (
    <button
      type="button"
      className={`loc-img${inListing ? " loc-img--in" : ""}${unavailable ? " loc-img--unavailable" : ""}`}
      aria-pressed={inListing}
      aria-describedby={unavailable === null ? undefined : "video-limit"}
      aria-label={asset.name}
      disabled={unavailable !== null}
      title={unavailable ?? undefined}
      onClick={onToggle}
      onMouseEnter={() => {
        onFocus();
        if (isVideo) play();
      }}
      onMouseLeave={isVideo ? rest : undefined}
    >
      <span className="loc-img__face">
        {isVideo ? (
          <>
            <MutedClip
              src={pictureFor(asset.ref, null, "full", listing)}
              clipRef={clipRef}
              onDuration={setLength}
            />
            <span className="loc-img__badge">
              {length === null ? "▶" : `▶ ${clipLength(length)}`}
            </span>
          </>
        ) : (
          <img src={pictureFor(asset.ref, null, "tile", listing)} alt="" loading="lazy" />
        )}
      </span>
      <span className="loc-img__name">{asset.name}</span>
    </button>
  );
}

export function MediaLocator({
  detail,
  templates,
  local,
  shared,
  onToggleTemplate,
  onToggleFile,
  onAddMissingColours,
  onToggleSwatchSource,
  onFocus,
  owner,
}: Props) {
  const [mode, setMode] = useState<LocatorMode>("templates");
  const [query, setQuery] = useState("");
  const [openTemplate, setOpenTemplate] = useState<string | null>(null);

  const needle = query.toLowerCase();
  const filtered = templates
    .filter((t) => t.status === "calibrated")
    .filter((t) => t.name.toLowerCase().includes(needle));
  const matches = (a: MediaFileSummary) => a.name.toLowerCase().includes(needle);
  const listing = owner === undefined ? detail.name || null : owner;
  const groups = [
    ...(local === null
      ? []
      : [
          {
            label: owner?.kind === "listing-template" ? "This template" : "This listing",
            files: local,
          },
        ]),
    {
      label: "Shared",
      files: shared,
    },
  ].filter((group) => group.files.length > 0);
  const nothingMatches =
    groups.some((g) => g.files.length > 0) && groups.every((g) => !g.files.some(matches));
  const swatchTemplate = detail.etsy.variation_images ?? null;
  const videoLimitReached =
    detail.media.filter((entry) => mediaKind(entry) === "video").length >= MAX_VIDEOS;

  function entriesFor(template: string): number {
    return detail.media.filter((m) => typeof m !== "string" && m.template === template).length;
  }

  return (
    <div className="locator">
      <div className="locator__head">
        <span className="locator__title">Add media</span>
        <span className="locator__hint">Hover to preview · click to add</span>
      </div>

      <div className="seg locator__modes">
        {(["templates", "files"] as LocatorMode[]).map((m) => (
          <button
            key={m}
            type="button"
            className={mode === m ? "seg-opt seg-opt--on" : "seg-opt"}
            aria-pressed={mode === m}
            // The query is cleared on the way across: "flat" means nothing
            // in common-media/, and a list that looks empty because of a
            // search you cannot see reads as a list with nothing in it.
            onClick={() => {
              setMode(m);
              setQuery("");
            }}
          >
            {m === "templates" ? "Mockup templates" : "Files"}
          </button>
        ))}
      </div>

      <div className="locator__search">
        <svg viewBox="0 0 24 24" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
          <circle cx="11" cy="11" r="7" />
          <path d="M20 20l-3.5-3.5" />
        </svg>
        <input
          className="input"
          type="text"
          placeholder={mode === "templates" ? "Search templates…" : "Search files…"}
          value={query}
          onChange={(event) => setQuery(event.target.value)}
        />
      </div>

      {mode === "files" && (
        <div className="locator__list">
          {videoLimitReached && (
            <p className="locator__limit" id="video-limit" role="status">
              {MAX_VIDEOS}-video limit reached — remove one before adding another.
            </p>
          )}
          {groups.map((g) => {
            const visible = g.files.filter(matches);
            if (visible.length === 0) return null;
            return (
              <div key={g.label} role="group" aria-label={g.label} className="loc-group">
                <span className="loc-group__label">{g.label}</span>
                {visible.length > 0 && (
                  <div className="loc-images">
                    {visible.map((asset) => (
                      <FileTile
                        key={asset.ref}
                        asset={asset}
                        listing={listing}
                        inListing={detail.media.includes(asset.ref)}
                        unavailable={
                          asset.kind === "video" &&
                          videoLimitReached &&
                          !detail.media.includes(asset.ref)
                            ? `Etsy allows at most ${MAX_VIDEOS} videos per listing`
                            : null
                        }
                        onToggle={() => onToggleFile(asset.ref)}
                        onFocus={() => onFocus({ kind: "file", asset })}
                      />
                    ))}
                  </div>
                )}
              </div>
            );
          })}
          {nothingMatches && <p className="locator__empty">No file matches that search.</p>}
        </div>
      )}

      {mode === "templates" && (
        <div className="locator__list">
          {filtered.map((t) => {
            const open = openTemplate === t.name;
            const inCount = entriesFor(t.name);
            const missing = missingColours(detail.media, detail.colors, t.name);
            const uncovered = swatchTemplate === t.name ? missing : [];
            return (
              <div key={t.name} className={open ? "loc-tmpl loc-tmpl--open" : "loc-tmpl"}>
                <div
                  className="loc-tmpl__head"
                  onClick={() => setOpenTemplate((current) => (current === t.name ? null : t.name))}
                  onMouseEnter={() =>
                    onFocus({
                      kind: "template",
                      template: t.name,
                      colour: t.kind === "colour-matrix" ? (detail.colors[0] ?? null) : null,
                    })
                  }
                >
                  <span className="loc-tmpl__mini">
                    <img src={templateThumbnailUrl(t.name)} alt="" loading="lazy" />
                  </span>
                  <span className="loc-tmpl__text">
                    <span className="loc-tmpl__name">{t.name}</span>
                    <span className="loc-tmpl__kind">{kindLabel(t.kind)}</span>
                  </span>
                  {inCount > 0 && <span className="loc-tmpl__count">{inCount} in listing</span>}
                  <span className="loc-tmpl__caret" aria-hidden="true">
                    {open ? "▾" : "▸"}
                  </span>
                </div>

                {open && (
                  <div className="loc-tmpl__body">
                    {t.kind === "colour-matrix" && detail.colors.length === 0 ? (
                      // Nothing to offer: a colour-matrix entry needs a
                      // colour, and every colour it could name comes from
                      // the listing's own `colors:`. Adding one anyway would
                      // write `{template, colour: null}`, which is a block.
                      <p className="loc-tmpl__note">Pick colours on Variants first.</p>
                    ) : t.kind === "colour-matrix" ? (
                      <>
                        <div className="cchips">
                          {/* The listing's own colours, not `t.colours`:
                              a colour-matrix set's photos are named for
                              ADR-0004's slug, but a template with a shared
                              filename prefix (`{template}-{colour}.png`)
                              reports that whole prefixed stem as its
                              "colour" (`template_colours`'s enumeration
                              direction has no slug to match against,
                              unlike `template_base_image`'s lookup
                              direction, which resolves a bare slug against
                              exactly this fallback) -- so comparing against
                              `detail.colors` by string equality showed
                              nothing at all for such a template. `media[]`
                              always stores the listing's own bare slug
                              (confirmed by `isInMedia`), so that is what a
                              chip must offer, regardless of what the
                              template's own photos happen to be named. */}
                          {detail.colors.map((colour) => {
                            const inListing = isInMedia(detail.media, t.name, colour);
                            return (
                              <button
                                key={colour}
                                type="button"
                                className={inListing ? "cchip cchip--in" : "cchip"}
                                aria-pressed={inListing}
                                onClick={() => onToggleTemplate(t.name, colour)}
                                onMouseEnter={() =>
                                  onFocus({ kind: "template", template: t.name, colour })
                                }
                              >
                                {colour}
                                {inListing && (
                                  <svg
                                    className="cchip__tick"
                                    viewBox="0 0 24 24"
                                    strokeWidth="3.5"
                                    strokeLinecap="round"
                                    strokeLinejoin="round"
                                    aria-hidden="true"
                                  >
                                    <path d="M5 13l4 4L19 7" />
                                  </svg>
                                )}
                              </button>
                            );
                          })}
                        </div>

                        {missing.length > 1 && (
                          <button
                            type="button"
                            className="btn-like btn-like--ghost btn-sm"
                            onClick={() => onAddMissingColours(t.name)}
                          >
                            + Add all {missing.length} remaining colours
                          </button>
                        )}
                        {detail.colors.length > 0 && missing.length === 0 && (
                          <p className="loc-tmpl__note">
                            Every colour this listing sells is already in the reel.
                          </p>
                        )}

                        {inCount > 0 && (
                          <div className="tmpl-swatch">
                            <div className="tmpl-swatch__row">
                              <span className="tmpl-swatch__label" id={`swatch-${t.name}`}>
                                Use for Etsy colour swatches
                                <span className="tmpl-swatch__sub">
                                  {swatchTemplate === t.name
                                    ? "Etsy shows these beside each colour option"
                                    : swatchTemplate
                                      ? `Currently using ${swatchTemplate}`
                                      : "Off — no swatch images sent"}
                                </span>
                              </span>
                              <button
                                type="button"
                                role="switch"
                                aria-checked={swatchTemplate === t.name}
                                aria-labelledby={`swatch-${t.name}`}
                                className={
                                  swatchTemplate === t.name ? "switch switch--on" : "switch"
                                }
                                onClick={() => onToggleSwatchSource(t.name)}
                              >
                                <span className="switch__knob" />
                              </button>
                            </div>
                            {swatchTemplate === t.name && (
                              <>
                                <span
                                  className={
                                    uncovered.length > 0
                                      ? "swatch-status swatch-status--warn"
                                      : "swatch-status swatch-status--ok"
                                  }
                                >
                                  {uncovered.length > 0
                                    ? `${detail.colors.length - uncovered.length} of ${detail.colors.length} covered`
                                    : `All ${detail.colors.length} covered`}
                                </span>
                                {uncovered.length > 0 && (
                                  <p className="swatch-note">
                                    {uncovered.join(", ")} {uncovered.length === 1 ? "has" : "have"}{" "}
                                    no image here — Etsy keeps{" "}
                                    {uncovered.length === 1 ? "that swatch" : "those swatches"}{" "}
                                    empty.
                                  </p>
                                )}
                              </>
                            )}
                          </div>
                        )}
                      </>
                    ) : (
                      <>
                        <p className="loc-tmpl__note">
                          {t.kind === "multiple"
                            ? "One photo showing several colours at once — it carries no colour of its own."
                            : "One fixed photo, the same for every colour."}
                        </p>
                        <button
                          type="button"
                          className={
                            isInMedia(detail.media, t.name, null)
                              ? "btn-like btn-like--ghost btn-sm"
                              : "btn-like btn-like--primary btn-sm"
                          }
                          onClick={() => onToggleTemplate(t.name, null)}
                        >
                          {isInMedia(detail.media, t.name, null) ? "Remove from listing" : "+ Add"}
                        </button>
                      </>
                    )}
                  </div>
                )}
              </div>
            );
          })}
          {filtered.length === 0 && (
            <p className="locator__empty">No template matches that search.</p>
          )}
        </div>
      )}
    </div>
  );
}

import { listingDesignThumbnailUrl } from "../../api/listings";
import { refName } from "../../media";
import type { DesignMap } from "../../types";
import {
  canHaveOwnDesign,
  cap,
  clothFor,
  resolve,
  toneLabel,
  wouldPrintAutomatically,
  type Tone,
} from "./artwork";

/**
 * "What this colour prints", under the Variants stage (interactions Part 1
 * §8, Part 2 §6).
 *
 * The stage shows the file; this says in words where it came from, because
 * resolution has three sources and depends on shared garment data, and a
 * seller who cannot see why a colour prints a file cannot fix it when it is
 * wrong. Its actions follow the state (Part 2 §6): a colour's own design
 * offers **Change** and **Use automatic design**, having already said what
 * automatic would print, so going back needs no confirmation; an empty slot
 * offers to fill the slot first, because that fixes every colour that needs
 * it at once; anything else offers the colour its own design. A colour with
 * no tone offers nothing -- tone is shared garment data, and an own design
 * does not stand in for it (spec: *Artwork resolution*).
 */

interface Props {
  colour: string;
  enabled: boolean;
  design: DesignMap;
  profile: string;
  tones: Readonly<Record<string, Tone>>;
  /** The colour's real garment shade, when the swatch has been sampled. */
  swatch: string | undefined;
  /** Opens that slot's Recent designs panel in the strip above the tabs. */
  onChooseSlot: (tone: Tone) => void;
  /** Opens the colour's own design picker. */
  onPickColour: () => void;
  /** Removes the colour's own design. */
  onAutomatic: () => void;
}

export function PrintsCard({
  colour,
  enabled,
  design,
  profile,
  tones,
  swatch,
  onChooseSlot,
  onPickColour,
  onAutomatic,
}: Props) {
  const name = cap(colour);
  if (!enabled) {
    return (
      <p className="variants-preview__hint">
        {name} isn’t sold on this listing. Switch it on to choose what it prints.
      </p>
    );
  }

  const resolution = resolve(design, colour, tones);
  let title: string;
  let why: string;
  switch (resolution.kind) {
    case "unclassified":
      title = `${name} can’t pick a design yet`;
      why = `The ${profile} garment profile doesn’t say whether ${colour} is a light or dark shirt. Mark it in garment-profiles/${profile}.yaml — this listing can’t decide it.`;
      break;
    case "slot-empty":
      title = `${name} has nothing to print`;
      why = `It’s a ${resolution.tone} shirt, and no design for ${toneLabel(resolution.tone)} is chosen yet.`;
      break;
    case "no-design":
      title = `${name} has nothing to print`;
      why = "Choose a design above.";
      break;
    case "resolved": {
      title = `${name} prints ${refName(resolution.ref)}`;
      if (resolution.source === "default") {
        why = "Automatic: the one design for all shirts.";
      } else if (resolution.source === "colour") {
        why = `Its own design, for ${name} only.${automaticWouldPrint(
          wouldPrintAutomatically(design, colour, tones),
        )}`;
      } else {
        const slot = resolution.source === "on-light" ? "light" : "dark";
        why = `Automatic: the design for ${toneLabel(slot)}, because ${profile} marks ${colour} ${slot}.`;
      }
      break;
    }
  }

  const file = resolution.kind === "resolved" ? resolution.ref : null;
  const own = resolution.kind === "resolved" && resolution.source === "colour";
  return (
    <div
      className={
        resolution.kind === "unclassified" ? "color-prints color-prints--blocked" : "color-prints"
      }
    >
      {file !== null ? (
        <span
          className="color-prints__thumb"
          style={{ background: clothFor(colour, swatch, design, tones) }}
        >
          <img src={listingDesignThumbnailUrl(refName(file))} alt="" />
        </span>
      ) : (
        <span className="color-prints__thumb design-tile--empty" />
      )}
      <div className="color-prints__text">
        <div className="color-prints__title">{title}</div>
        <div className="color-prints__why">{why}</div>
        {file !== null && (
          <div className="color-prints__note">Listing Images and Printify use this same file.</div>
        )}
      </div>
      {resolution.kind !== "unclassified" && canHaveOwnDesign(design) && (
        <div className="color-prints__actions">
          {own ? (
            <>
              <button
                type="button"
                className="btn-like btn-sm color-prints__btn"
                onClick={onPickColour}
              >
                Change
              </button>
              <button
                type="button"
                className="btn-like btn-like--ghost btn-sm color-prints__btn"
                onClick={onAutomatic}
              >
                Use automatic design
              </button>
            </>
          ) : resolution.kind === "slot-empty" ? (
            <>
              <button
                type="button"
                className="btn-like btn-like--primary btn-sm color-prints__btn"
                onClick={() => onChooseSlot(resolution.tone)}
              >
                Choose design for {toneLabel(resolution.tone)}
              </button>
              <button
                type="button"
                className="btn-like btn-like--ghost btn-sm color-prints__btn"
                onClick={onPickColour}
              >
                Select different design for {name}
              </button>
            </>
          ) : (
            <button
              type="button"
              className="btn-like btn-sm color-prints__btn"
              onClick={onPickColour}
            >
              Select different design
            </button>
          )}
        </div>
      )}
    </div>
  );
}

/** " Back on automatic it would print …" -- nothing when automatic prints
 * nothing, since there is then no file to name. */
function automaticWouldPrint(fallback: ReturnType<typeof resolve>): string {
  if (fallback.kind !== "resolved") return "";
  const slot =
    fallback.source === "on-light"
      ? `, the design for ${toneLabel("light")}`
      : fallback.source === "on-dark"
        ? `, the design for ${toneLabel("dark")}`
        : "";
  return ` Back on automatic it would print ${refName(fallback.ref)}${slot}.`;
}

import { fireEvent, render, screen, waitFor, within } from "@testing-library/react";
import { type ComponentProps, useState } from "react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import * as calibrator from "../../api/calibrator";
import * as listingsApi from "../../api/listings";
import type { GarmentProfileSummary, ListingDetail, TemplateSummary } from "../../types";
import { listingDetail } from "../../test/listings";
import { VariantsTab as VariantsTabView } from "./VariantsTab";

/** The previewed colour is the shell's state, so the strip's own-design line
 * can preview a colour too; this stands in for the shell. */
function VariantsTab(
  props: Omit<ComponentProps<typeof VariantsTabView>, "previewed" | "onPreview">,
) {
  const [previewed, setPreviewed] = useState<string | null>(null);
  return <VariantsTabView {...props} previewed={previewed} onPreview={setPreviewed} />;
}

function template(over: Partial<TemplateSummary> & { name: string }): TemplateSummary {
  return {
    kind: "colour-matrix",
    colours: ["black", "ivory"],
    photos: [],
    has_config: true,
    status: "calibrated",
    status_reason: null,
    width: 480,
    height: 576,
    ...over,
  };
}

function detail(over: Partial<ListingDetail> = {}): ListingDetail {
  return listingDetail({ design: {}, ...over });
}

