  const card = (container: HTMLElement) => {
    const el = container.querySelector(".color-prints");
    if (el === null) throw new Error("no prints card");
    return el as HTMLElement;
  };

  it("gives every enabled row a chip of the file it prints, on the colour's swatch", async () => {
    renderTab({ colors: ["black", "moss"] });
    await screen.findByText("moss");
    const chip = await within(row("moss")).findByRole("button", {
      name: "Select different design for Moss",
    });
    expect(chip).toHaveAttribute("title", "Select different design");
    expect(chip.querySelector("img")).toHaveAttribute(
      "src",
      "/api/listing-designs/take-a-hike-light-ink/thumbnail",
    );
    await waitFor(() => expect(chip).toHaveStyle({ background: "#5b6b3a" }));
    expect(within(row("ivory")).queryByRole("button", { name: /Select different/ })).toBeNull();
  });

  it("tags a colour with its own design and rings its chip", async () => {
    renderTab({ design: { "on-light": DARK_INK, "on-dark": LIGHT_INK, moss: MOSS_SPECIAL } });
    await screen.findByText("moss");
    expect(within(row("moss")).getByText("own design")).toHaveClass("tag");
    const chip = within(row("moss")).getByRole("button", { name: /Select different/ });
    expect(chip).toHaveClass("color-row__chip--own");
    expect(chip.querySelector("img")).toHaveAttribute(
      "src",
      "/api/listing-designs/moss-special/thumbnail",
    );
    expect(within(row("black")).queryByText("own design")).toBeNull();
  });

  it("leaves an empty dashed chip for a colour with nothing to print", async () => {
    renderTab({ design: { "on-light": null, "on-dark": LIGHT_INK } });
    await screen.findByText("ivory");
    const chip = within(row("ivory")).getByRole("button", { name: /Select different/ });
    expect(chip).toHaveClass("color-row__chip--empty");
    expect(chip.querySelector("img")).toBeNull();
  });

  it("offers no chip before the listing has a base design to sit beside", async () => {
    /* A colour key without a base key is a malformed write (spec: *Saving,
       blockers and warnings*), so the base design comes first. */
    const { container } = renderTab({ design: {} });
    await screen.findByText("moss");
    expect(screen.queryByRole("button", { name: /Select different/ })).toBeNull();
    expect(within(card(container)).queryByRole("button")).toBeNull();
  });

  it("opens the colour's picker from its chip, naming who else is unaffected", async () => {
    renderTab();
    await screen.findByText("moss");
    fireEvent.click(within(row("moss")).getByRole("button", { name: /Select different/ }));

    const dialog = await screen.findByRole("dialog", { name: "Design for Moss" });
    expect(dialog).toHaveTextContent(
      "Only Moss changes. Black and Navy keep the design for dark shirts.",
    );
    const current = await within(dialog).findByRole("button", { name: /take-a-hike-light-ink/ });
    expect(current).toHaveTextContent("Current");
    await waitFor(() =>
      expect(current.querySelector(".design-tile")).toHaveStyle({ background: "#5b6b3a" }),
    );
  });

  it("names the design for all shirts in the hint while linked", async () => {
    renderTab({ colors: ["black", "moss"], design: { default: DARK_INK } });
    await screen.findByText("moss");
    fireEvent.click(within(row("moss")).getByRole("button", { name: /Select different/ }));
    expect(await screen.findByRole("dialog", { name: "Design for Moss" })).toHaveTextContent(
      "Only Moss changes. Black keeps the design for all shirts.",
    );
  });

  it("writes the pick as the colour's own design and previews that colour", async () => {
    const { onUpdate } = renderTab();
    await screen.findByText("moss");
    fireEvent.click(within(row("moss")).getByRole("button", { name: /Select different/ }));
    const dialog = await screen.findByRole("dialog", { name: "Design for Moss" });
    fireEvent.click(await within(dialog).findByRole("button", { name: /moss-special/ }));

    expect(onUpdate).toHaveBeenCalledWith({
      design: { "on-light": DARK_INK, "on-dark": LIGHT_INK, moss: MOSS_SPECIAL },
    });
    expect(screen.queryByRole("dialog")).toBeNull();
    expect(row("moss")).toHaveClass("color-row--selected");
  });

  it("offers Select different design on the card of an automatic colour", async () => {
    const { container } = renderTab();
    await screen.findByText("black");
    fireEvent.click(
      within(card(container)).getByRole("button", { name: "Select different design" }),
    );
    expect(await screen.findByRole("dialog", { name: "Design for Black" })).toBeInTheDocument();
  });

  it("offers an empty slot's colour its own design beside filling the slot", async () => {
    const { container } = renderTab({ design: { "on-light": null, "on-dark": LIGHT_INK } });
    fireEvent.click(await screen.findByRole("button", { name: "Preview ivory" }));
    fireEvent.click(
      within(card(container)).getByRole("button", { name: "Select different design for Ivory" }),
    );
    expect(await screen.findByRole("dialog", { name: "Design for Ivory" })).toBeInTheDocument();
  });

  it("explains a colour's own design and what automatic would print", async () => {
    const { container } = renderTab({
      design: { "on-light": DARK_INK, "on-dark": LIGHT_INK, moss: MOSS_SPECIAL },
    });
    fireEvent.click(await screen.findByRole("button", { name: "Preview moss" }));
    expect(card(container)).toHaveTextContent("Moss prints moss-special");
    expect(card(container)).toHaveTextContent(
      "Its own design, for Moss only. Back on automatic it would print take-a-hike-light-ink, the design for dark shirts.",
    );
    fireEvent.click(within(card(container)).getByRole("button", { name: "Change" }));
    expect(await screen.findByRole("dialog", { name: "Design for Moss" })).toBeInTheDocument();
  });

  it("says what automatic would print while linked", async () => {
    const { container } = renderTab({ design: { default: DARK_INK, moss: MOSS_SPECIAL } });
    fireEvent.click(await screen.findByRole("button", { name: "Preview moss" }));
    expect(card(container)).toHaveTextContent(
      "Its own design, for Moss only. Back on automatic it would print take-a-hike-dark-ink.",
    );
  });

  it("returns a colour to automatic by removing its key, in either mode", async () => {
    const pair = renderTab({
      design: { "on-light": DARK_INK, "on-dark": null, moss: MOSS_SPECIAL },
    });
    fireEvent.click(await screen.findByRole("button", { name: "Preview moss" }));
    fireEvent.click(
      within(card(pair.container)).getByRole("button", { name: "Use automatic design" }),
    );
    expect(pair.onUpdate).toHaveBeenCalledWith({
      design: { "on-light": DARK_INK, "on-dark": null },
    });
    pair.unmount();

    const one = renderTab({ design: { default: DARK_INK, moss: MOSS_SPECIAL } });
    fireEvent.click(await screen.findByRole("button", { name: "Preview moss" }));
    fireEvent.click(
      within(card(one.container)).getByRole("button", { name: "Use automatic design" }),
    );
    expect(one.onUpdate).toHaveBeenCalledWith({ design: { default: DARK_INK } });
  });
});

import { useEffect, useMemo, useState } from "react";
import { getTemplateSwatch, listTemplates } from "../../api/calibrator";
import {
  listGarmentProfiles,
  listingDesignThumbnailUrl,
  listListingDesigns,
} from "../../api/listings";
import { type Artwork, refName, sceneSource, templatePicture } from "../../media";
import type {
  DesignMap,
  GarmentProfileSummary,
  ListingDesignSummary,
  ListingDetail,
  TemplateSummary,
} from "../../types";
import { ArtworkPicker } from "./ArtworkPicker";
import {
  automatic,
  canHaveOwnDesign,
  cap,
  clothFor,
  isLinked,
  listNames,
  pickForColour,
  resolve,
  toneLabel,
  type Tone,
} from "./artwork";
import { mediaLostBy, selectColours, selectGarmentProfile } from "./colourSelection";
import { PrintsCard } from "./PrintsCard";

/**
 * Garment dropdown, sizes, colour list, and a preview of the colour under the
 * cursor (phase 5).
 *
 * A swatch dot next to each name is the listing's *real* garment colour, not
 * an invented hex value -- sampled off the garment profile's
 * `preview_template` (`render/swatch.py`'s `sample_swatch`, via
 * `GET.../swatch`). It answers "roughly what colour is this" for scanning
 * the whole list; "does this colour suit the design" is still the big
 * preview stage beside it, which renders the colour with the file it
 * resolves to in the saved listing (`GET .../scene-preview`, A35) rather
 * than a bare photo -- and is rendered large, because that judgement is about
 * the ink on the cloth and a postage stamp cannot carry it. The preview
 * template is a colour-matrix on the garment, not a `media:` entry, so a new
 * listing can judge colours before it has picked listing images (A13). The
 * card under it says which file that is and why (`PrintsCard`). A listing
 * template has no artwork, so it previews through the design its editor
 * picked to preview with (`artwork`), and has no file to explain.
 *
 * Two different states, deliberately distinguished, because conflating them
 * painted every enabled row in the selected-row highlight:
 *
 * * **enabled** -- the colour is in `colors:` and will be sold. The switch.
 * * **previewed** -- the colour on the stage right now. Exactly one, and
 * `.color-row--selected` means *this*, not "enabled".
 *
 * A disabled colour is dimmed (`--off`) rather than hidden, so turning one
 * back on does not require remembering it existed.
 *
 * Which colour is previewed is the shell's state, not this tab's: the design
 * strip's "Also printing their own design" names preview a colour too.
 *
 * Each enabled row carries a chip of the file it prints, on its own cloth,
 * which opens that colour's picker (interactions Part 1 §6, Part 2 §5). A
 * pick is the colour's own design -- `design.<colour>` -- written through
 * `onUpdate` rather than the strip's design change, because a colour's own
 * design is print treatment and never arms AI (spec: *Representative
 * artwork*).
 *
 * Every change to which colours are sold goes through `selectColours`, never
 * through a bare `{ colors }` patch -- see that module for the three fields
 * keyed by colour that have to move with it.
 */

interface Props {
  detail: ListingDetail;
  onUpdate: (patch: Record<string, unknown>) => void;
  /** The colour the seller last asked to preview; `null` until they do. */
  previewed: string | null;
  onPreview: (colour: string) => void;
  /** Opens a base slot's Recent designs panel in the strip above the tabs --
   * the card under the stage's fix for a colour whose slot is empty. */
  onChooseSlot?: (tone: Tone) => void;
  /** What the preview composites, when it is not the listing's own design:
   * the listing-template editor's preview design (UI doc §3). A listing
   * template has no artwork, so with this set nothing per-colour is offered. */
  artwork?: Artwork | null;
}

/** The garment profile's colour-matrix, used to judge colours before the
 * listing has picked its Etsy images. Not a `media:` default. The
 * templates list is only consulted to refuse a name we *know* is not
 * colour-matrix -- a new listing must not wait on GET /api/templates
 * (or on a colour-matrix entry in `media:`) before the stage can render. */
function previewTemplate(
  profile: GarmentProfileSummary | undefined,
  templates: TemplateSummary[],
): string | null {
  const name = profile?.preview_template;
  if (!name) return null;
  const known = templates.find((t) => t.name === name);
  if (known !== undefined && known.kind !== "colour-matrix") return null;
  return name;
}

export function VariantsTab({
  detail,
  onUpdate,
  previewed,
  onPreview,
  onChooseSlot = () => undefined,
  artwork,
}: Props) {
  const [profiles, setProfiles] = useState<GarmentProfileSummary[]>([]);
  const [templates, setTemplates] = useState<TemplateSummary[]>([]);
  const [library, setLibrary] = useState<ListingDesignSummary[]>([]);
  const [swatches, setSwatches] = useState<Record<string, string>>({});
  const [status, setStatus] = useState("");
  /** The colour whose own-design picker is open. */
  const [picking, setPicking] = useState<string | null>(null);

  useEffect(() => {
    listListingDesigns()
      .then(setLibrary)
      .catch(() => setLibrary([]));
    listGarmentProfiles()
      .then(setProfiles)
      .catch(() => setStatus("failed to load garment profiles"));
    listTemplates()
      .then(setTemplates)
      .catch(() => setStatus("failed to load templates"));
  }, []);

  const profile = profiles.find((p) => p.name === detail.garment_profile);
  // Every colour the profile classifies, plus any the listing already enables
  // that the profile doesn't (so toggling one off never makes it vanish from
  // the list before the edit is saved).
  const colourNames = useMemo(
    () =>
      Array.from(
        new Set([...(profile ? Object.keys(profile.colors) : []), ...detail.colors]),
      ).sort(),
    [profile, detail.colors],
  );

  // Falls back rather than holding state the listing may have moved past: a
  // colour switched off, or renamed, should not leave the stage pointing at
  // something this listing no longer sells.
  const shown =
    previewed !== null && colourNames.includes(previewed)
      ? previewed
      : (detail.colors[0] ?? colourNames[0] ?? null);

  const template = previewTemplate(profile, templates);
  const ownArtwork = artwork === undefined;
  const scene = ownArtwork ? sceneSource(detail.name, detail.design_content_hash) : artwork;
  const tones: Record<string, Tone> = profile?.colors ?? {};

  // One request per colour, fired once the preview template and colour list
  // are known -- not per row-render, so scrolling or re-toggling a switch
  // never refetches a dot this effect has already resolved. Routed through
  // `Promise.all` even for "no template" so `setSwatches` is always called
  // from a `.then()`, never synchronously in the effect body.
  useEffect(() => {
    let current = true;
    const fetches =
      template === null
        ? []
        : colourNames.map((colour) =>
            getTemplateSwatch(template, colour)
              .then((hex) => [colour, hex] as const)
              .catch(() => null),
          );
    Promise.all(fetches).then((results) => {
      if (!current) return;
      setSwatches(Object.fromEntries(results.filter((r) => r !== null)));
    });
    return () => {
      current = false;
    };
  }, [template, colourNames]);

  /** The one write path for `colors:`. Reports what else the edit took with
   * it, since a bulk switch can drop a reel somebody spent a while building
   * and the reel is on a different tab. */
  function setColours(next: string[]) {
    const lost = mediaLostBy(detail, next);
    onUpdate(selectColours(detail, next));
    setStatus(
      lost === 0
        ? ""
        : `Removed ${lost} listing ${lost === 1 ? "image" : "images"} for colours no longer sold.`,
    );
  }

  /** A colour's own design: written straight into `design`, then previewed,
   * so the seller sees it on the stage (interactions Part 1 §6). */
  function pickOwn(colour: string, ref: string) {
    onUpdate({ design: pickForColour(detail.design, colour, ref) });
    setPicking(null);
    onPreview(colour);
  }

  function toggleColour(colour: string, enabled: boolean) {
    setColours(enabled ? [...detail.colors, colour] : detail.colors.filter((c) => c !== colour));
  }

  /** Every colour the newly chosen profile classifies, replacing whatever
   * was selected -- a new listing has none yet, and a switch between
   * garments would otherwise keep colours the new one does not sell. */
  function pickProfile(name: string) {
    const chosen = profiles.find((p) => p.name === name);
    const colours = chosen === undefined ? [] : Object.keys(chosen.colors).sort();
    const lost = mediaLostBy(detail, colours);
    onUpdate(selectGarmentProfile(detail, name, colours));
    setStatus(
      lost === 0
        ? ""
        : `Removed ${lost} listing ${lost === 1 ? "image" : "images"} for colours no longer sold.`,
    );
  }

  /** Every colour the garment profile classifies as ``shade``, and nothing
   * else -- the two bulk buttons are exact opposites, so "Dark" turning the
   * light ones *off* is the half that makes them worth having. Driven by the
   * profile, so a colour it does not classify is left out of both. */
  function onlyShade(shade: "dark" | "light") {
    if (!profile) return;
    setColours(colourNames.filter((colour) => profile.colors[colour] === shade));
  }

  // Offered only when there is something for them to act on: a garment
  // profile that classifies no colours (`colors: {}`) would give two buttons
  // that clear the list and call it a shade.
  const hasShades = profile !== undefined && Object.keys(profile.colors).length > 0;
  // A colour key needs a base key beside it; an empty draft picks that first.
  const ownable = ownArtwork && canHaveOwnDesign(detail.design);

  return (
    <div className="layout--variants">
      <fieldset>
        <legend>Variants</legend>

        <div className="field">
          <label htmlFor="variants-garment">Garment profile</label>
          <select
            id="variants-garment"
            value={detail.garment_profile}
            onChange={(event) => pickProfile(event.target.value)}
          >
            {/* A new listing starts with none chosen, so the unselected case
                needs words rather than the blank, unlabelled option an empty
                value would otherwise render. */}
            {!profile && (
              <option value={detail.garment_profile}>
                {detail.garment_profile || "Select a garment profile…"}
              </option>
            )}
            {profiles.map((p) => (
              <option key={p.name} value={p.name}>
                {p.name}
              </option>
            ))}
          </select>
        </div>

        {profile && (
          <div className="field">
            <label>Sizes</label>
            <div className="garment-card__sizes">
              {profile.sizes.map((size) => (
                <span key={size} className="size-pill">
                  {size}
                </span>
              ))}
            </div>
          </div>
        )}

        <div className="field">
          <div className="colors-panel__head">
            <label style={{ margin: 0 }}>Colours</label>
            <span className="colors-panel__count">
              {detail.colors.length} of {colourNames.length} included
            </span>
          </div>

          {/* Above the swatches, because they act on all of them: a design
              drawn for dark garments sells on the dark half of the profile
              and nothing else, and setting that one switch at a time is the
              most tedious thing this tab asks for. */}
          {hasShades && (
            <div className="shade-picker">
              <button type="button" className="btn-like btn-sm" onClick={() => onlyShade("dark")}>
                Dark
              </button>
              <button type="button" className="btn-like btn-sm" onClick={() => onlyShade("light")}>
                Light
              </button>
              <span className="shade-picker__hint">only these shades</span>
            </div>
          )}

          {colourNames.map((colour) => {
            const enabled = detail.colors.includes(colour);
            const classification = profile?.colors[colour];
            const file = resolvedFile(detail.design, colour, tones);
            const own = (detail.design[colour] ?? null) !== null;
            const rowClass = [
              "color-row",
              colour === shown ? "color-row--selected" : "",
              enabled ? "" : "color-row--off",
            ]
              .filter(Boolean)
              .join(" ");
            return (
              <div key={colour} className={rowClass}>
                <button
                  type="button"
                  className="color-row__text"
                  aria-label={`Preview ${colour}`}
                  onClick={() => onPreview(colour)}
                >
                  {swatches[colour] && (
                    <span
                      className="color-row__swatch"
                      style={{ background: swatches[colour] }}
                      aria-hidden="true"
                    />
                  )}
                  <span className="color-row__name">{colour}</span>
                  {own && enabled && (
                    <span className="tag tag-accent-2 color-row__own">own design</span>
                  )}
                </button>
                {/* Only rows that are sold print anything, so only they
                    have a file to show or to change. */}
                {enabled && ownable && profile !== undefined && (
                  <button
                    type="button"
                    className={[
                      "color-row__chip",
                      own ? "color-row__chip--own" : "",
                      file === null ? "color-row__chip--empty" : "",
                    ]
                      .filter(Boolean)
                      .join(" ")}
                    style={
                      file !== null
                        ? { background: clothFor(colour, swatches[colour], detail.design, tones) }
                        : undefined
                    }
                    aria-label={`Select different design for ${cap(colour)}`}
                    title="Select different design"
                    onClick={() => {
                      onPreview(colour);
                      setPicking(colour);
                    }}
                  >
                    {file !== null && <img src={listingDesignThumbnailUrl(refName(file))} alt="" />}
                  </button>
                )}
                {/* Beside the switch, not beside the name: the shade is what
                    the two bulk buttons above act on, so it reads as a
                    property of the decision rather than of the label. */}
                {classification ? (
                  <span
                    className={classification === "dark" ? "tag tag-neutral" : "tag tag-accent"}
                  >
                    {classification}
                  </span>
                ) : (
                  // Shared garment data the listing cannot supply: which base
                  // design it prints depends on it (spec, *Artwork resolution*).
                  profile !== undefined && <span className="tag tag-dirty">no tone</span>
                )}
                <button
                  type="button"
                  role="switch"
                  aria-checked={enabled}
                  aria-label={colour}
                  className={enabled ? "switch switch--on" : "switch"}
                  onClick={() => toggleColour(colour, !enabled)}
                >
                  <span className="switch__knob" />
                </button>
              </div>
            );
          })}
        </div>
      </fieldset>

      <div className="variants-preview">
        <div className="preview-stage preview-stage--large">
          {template !== null && shown !== null ? (
            <img src={templatePicture(template, shown, scene)} alt={`${shown} on ${template}`} />
          ) : (
            <div className="image-placeholder">
              <span>Set preview_template on the garment profile to a colour-matrix mockup.</span>
            </div>
          )}
        </div>
        {/* Once the profile has loaded: before then every colour of a
            light/dark listing would read as having no tone. */}
        {ownArtwork && shown !== null && profile !== undefined && (
          <PrintsCard
            colour={shown}
            enabled={detail.colors.includes(shown)}
            design={detail.design}
            profile={detail.garment_profile}
            tones={tones}
            swatch={swatches[shown]}
            onChooseSlot={onChooseSlot}
            onPickColour={() => setPicking(shown)}
            onAutomatic={() => onUpdate({ design: automatic(detail.design, shown) })}
          />
        )}
        <p className="variants-preview__hint">
          Click a colour to preview it — helps judge whether it suits the design.
        </p>
        <p role="status" className="app__status">
          {status}
        </p>
      </div>

      {picking !== null && (
        <ArtworkPicker
          title={`Design for ${cap(picking)}`}
          hint={ownDesignHint(detail.design, picking, detail.colors, tones)}
          tile={clothFor(picking, swatches[picking], detail.design, tones)}
          current={resolvedFile(detail.design, picking, tones)}
          library={library}
          onPick={(ref) => pickOwn(picking, ref)}
          onClose={() => setPicking(null)}
        />
      )}
    </div>
  );
}

/** The file a colour prints, or `null` when it resolves to nothing. */
function resolvedFile(
  design: DesignMap,
  colour: string,
  tones: Readonly<Record<string, Tone>>,
): string | null {
  const resolution = resolve(design, colour, tones);
  return resolution.kind === "resolved" ? resolution.ref : null;
}

/** "Only Moss changes. Black and Navy keep the design for dark shirts." --
 * who else prints what this colour prints now, so a colour's own design is
 * not mistaken for a change to every dark shirt (interactions Part 1 §6).
 * The siblings are the other automatic colours sold that share its source:
 * every one while linked, those of its tone while unlinked. */
function ownDesignHint(
  design: DesignMap,
  colour: string,
  enabled: readonly string[],
  tones: Readonly<Record<string, Tone>>,
): string {
  const linked = isLinked(design);
  const tone = tones[colour];
  const siblings = enabled.filter(
    (c) => c !== colour && (design[c] ?? null) === null && (linked || tones[c] === tone),
  );
  const only = `Only ${cap(colour)} changes.`;
  if (siblings.length === 0) return only;
  const what = linked
    ? "the design for all shirts"
    : tone === undefined
      ? "their design"
      : `the design for ${toneLabel(tone)}`;
  return `${only} ${listNames(siblings)} keep${siblings.length === 1 ? "s" : ""} ${what}.`;
}

import { useEffect, useState, type Ref } from "react";
import type { AiSeoMode } from "./useAiSeoMode";

/** The sparkle **AI Mode** control and its hover card.
 * It remains visible while prerequisites are missing, but cannot start a request.
 * While a request runs, the button glows. The timer and Cancel sit under the
 * brief, aligned to its right edge, and the generating card appears only
 * while the button is hovered.
 *
 * The same click handler starts the first request and regenerates a stale
 * one (`useAiSeoMode.generate`'s own docstring): the v3 mockup's "not
 * disabled while stale" button is the one place this control's behaviour
 * changes by state, so there is no separate "Regenerate" button to build. */
export function AiSeoControl({
  mode,
  buttonRef,
}: {
  mode: AiSeoMode;
  buttonRef?: Ref<HTMLButtonElement>;
}) {
  const loading = mode.phase === "loading";
  const elapsed = useElapsed(loading ? mode.startedAt : null);
  const failure = mode.phase === "failed" ? failureMessage(mode.failure) : null;
  const [dismissed, setDismissed] = useState<string | null>(null);
  if (failure === null && dismissed !== null) setDismissed(null);
  return (
    <>
      <div
        className="seo-ai-mode-anchor"
        tabIndex={!mode.available ? 0 : undefined}
        role="group"
        aria-label="AI Mode requirements"
        aria-describedby="seo-ai-mode-tip"
      >
        <button
          ref={buttonRef}
          className={
            loading
              ? "btn btn-secondary seo-ai-mode seo-ai-mode--busy"
              : "btn btn-secondary seo-ai-mode"
          }
          type="button"
          disabled={!mode.available || loading}
          onClick={mode.generate}
          aria-describedby="seo-ai-mode-tip"
        >
          <SparkleIcon /> AI Mode
        </button>

        <div id="seo-ai-mode-tip" className="seo-ai-mode-tip" role="tooltip">
          {loading ? (
            <p className="seo-ai-mode-tip__note">
              Generating title, description and tag recommendations for your review
            </p>
          ) : mode.available ? (
            <p className="seo-ai-mode-tip__note">
              {mode.draftsBrief
                ? "Writes a brief from this design, then generates title, description and tag recommendations"
                : "Generates SEO fields using AI (title, description lead and tags)"}
            </p>
          ) : (
            <>
              <strong>Ready to use AI Mode?</strong>
              <ul>
                {mode.requirements.map((requirement) => (
                  <li
                    key={requirement.label}
                    className={requirement.ready ? "is-ready" : "is-missing"}
                  >
                    {requirement.label}
                  </li>
                ))}
              </ul>
              {mode.reason && <p>{mode.reason}</p>}
            </>
          )}
        </div>
      </div>

      {loading && (
        <div className="seo-ai-mode-progress">
          <span className="seo-ai-mode-elapsed">
            Generating for {formatElapsed(elapsed)} seconds
          </span>
          {mode.run.origin === "batch" ? (
            // No per-row cancel (spec, *Cancellation and deletion*): the
            // batch summary's Cancel batch stops it.
            <span className="seo-ai-mode-elapsed">Drafting as part of a batch</span>
          ) : (
            <button type="button" onClick={mode.cancel}>
              Cancel
            </button>
          )}
        </div>
      )}

      {mode.phase === "failed" && (
        <div className="seo-ai-mode-progress">
          <button type="button" onClick={mode.generate}>
            Try again
          </button>
        </div>
      )}

      {failure !== null && failure !== dismissed && (
        <div className="ai-failure-toast" role="alert">
          <p>{failure}</p>
          <button type="button" aria-label="Dismiss" onClick={() => setDismissed(failure)}>
            ×
          </button>
        </div>
      )}
    </>
  );
}

/** The sentence the toast says. The timer row keeps only **Try again**. */
function failureMessage(failure: string | null): string {
  return failure
    ? `AI Mode couldn’t finish: ${failure}`
    : "AI Mode couldn’t generate valid suggestions. Nothing changed.";
}

/** Whole seconds since `startedAt` (the run's own start, from the server,
 * so a reload mid-run keeps counting rather than starting again at 0:00);
 * 0 while there is no running run. */
function useElapsed(startedAt: number | null): number {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    if (startedAt === null) return;
    const id = window.setInterval(() => setNow(Date.now()), 250);
    return () => window.clearInterval(id);
  }, [startedAt]);
  if (startedAt === null) return 0;
  return Math.max(0, Math.floor((now - startedAt) / 1000));
}

function formatElapsed(seconds: number): string {
  const minutes = Math.floor(seconds / 60);
  return `${minutes}:${String(seconds % 60).padStart(2, "0")}`;
}

function SparkleIcon() {
  return (
    <svg aria-hidden="true" viewBox="0 0 20 20" width="14" height="14">
      <path
        className="seo-sparkle-primary"
        d="M8.2 2.2c.5 3.1 1.5 4.1 4.6 4.6-3.1.5-4.1 1.5-4.6 4.6-.5-3.1-1.5-4.1-4.6-4.6 3.1-.5 4.1-1.5 4.6-4.6Z"
      />
      <path
        className="seo-sparkle-secondary"
        d="M14.5 11.2c.3 2 1 2.7 3 3-2 .3-2.7 1-3 3-.3-2-1-2.7-3-3 2-.3 2.7-1 3-3Z"
      />
    </svg>
  );
}

