import { useCallback, useEffect, useRef, useState } from "react";
import type { SaveState } from "../../../hooks/useAutosave";
import { getSeoReadiness } from "../../../api/seo";
import type { ListingDetail, ListingProposal } from "../../../types";
import { representative } from "../artwork";
import { useProposalReview } from "./useProposalReview";
import { type AiRun, useAiRun } from "./useAiRun";
import type { MarketPanelState } from "../market/MarketListingsPanel";
import { useMarketPanel } from "../market/useMarketPanel";

/**
 * Listing Details' **AI Mode** (AI SEO implementation plan, PR7): readiness,
 * the AI run behind the button (`useAiRun`; features/market-seo-20260924/spec.md, *AI runs*), the
 * listing's cached proposal, and the three independent per-field acceptance
 * actions. `ListingEditorPageContent` owns it, above the tabs, because a run
 * outlives the tab it was started from; `DetailsTab` renders it.
 *
 * The run is exposed whole as `run`: its `steps` drive the page head's
 * indicator, and `market` is the top listings panel's state, built from the
 * run's market node and events and the listing's saved snapshot
 * (`useMarketPanel`). What this hook adds is what AI Mode does with a run's two actionable
 * events: a drafted brief goes into the field through `onAdopt` (the server
 * already wrote it, so it is not autosaved again), and a proposal opens the
 * drawers.
 *
 * ## The proposal lives on the server
 *
 * The run caches its proposal before announcing it, so the editor reads it
 * with `GET …/proposal` on open and again after every save, and records a
 * choice or a dismissal with `PATCH …/resolution`. The server also decides
 * whether it is stale, against the *saved* listing, so the batch summary and
 * this editor agree; an edit shows up as stale once autosave lands it. A
 * stale proposal stays usable: the drawer heading names what changed
 * (ADR-0047; UI doc §8).
 *
 * ## A batch's run
 *
 * While a batch row owns the listing, readiness says `batch_pending`: the
 * control stays disabled with the server's hint, and every
 * {@link BATCH_POLL_MS} this asks again and follows the listing's run once
 * the row's turn comes, so the editor shows the batch run live and opens
 * its drawers as a manual run's would.
 *
 * ## A deploy
 *
 * While a plan or apply holds the listing, readiness says `deploying`:
 * deploying takes precedence over AI (UI doc §8), so the control stays
 * disabled with the server's hint and asks again every {@link BATCH_POLL_MS}
 * until the deploy lets the listing go.
 *
 * useProposalReview owns cached/live proposal reconciliation and resolutions;
 * this module supplies readiness, run tracking and brief adoption.
 */

export type AiSeoPhase = "idle" | "loading" | "failed";

export interface AiSeoMode {
  /** Whether the AI Mode control can start a request. The button stays
   * visible and is disabled while this is false. */
  available: boolean;
  requirements: { label: string; ready: boolean }[];
  reason: string | null;
  phase: AiSeoPhase;
  /** The listing's cached proposal while any of its sections is still
   * pending, else `null` -- none was ever made, or every drawer has been
   * resolved (the server keeps the record either way). */
  proposal: ListingProposal | null;
  /** What changed since `proposal` was generated, from the server, or
   * `null` while it still describes the saved listing. Its choices stay
   * usable either way. */
  staleReason: string | null;
  /** Starts a run from the button, drafting the brief when the field is
   * empty, or replaces the current proposal with a fresh one (this is also
   * what a seller's "Regenerate" click on a stale proposal calls -- one
   * control, since a run always produces one complete proposal for all
   * three fields). */
  generate: () => void;
  /** The click will draft the brief, because the field is empty. A brief
   * the seller wrote is left alone. */
  draftsBrief: boolean;
  /** Cancels the run. A brief or snapshot it already wrote stays. */
  cancel: () => void;
  /** Why the last run failed or was refused, while `phase` is `"failed"`. */
  failure: string | null;
  /** When the current run started (ms since the epoch). *Generating for…*
   * counts from here, so a reload mid-run keeps counting. */
  startedAt: number | null;
  /** The run itself, for the page head's indicator. */
  run: AiRun;
  /** The top listings panel beside the fields, or `null` for none: what the
   * run is researching or found, else the listing's saved snapshot. */
  market: MarketPanelState | null;
  chooseTitle: (value: string) => void;
  rejectTitle: () => void;
  chooseLead: (value: string) => void;
  rejectLead: () => void;
  toggleTag: (tag: string) => void;
  acceptBestTags: () => void;
  closeTags: () => void;
}

/** How often the editor looks again while batch work owns the listing. */
export const BATCH_POLL_MS = 3000;

export function useAiSeoMode(
  detail: ListingDetail,
  onUpdate: (patch: Record<string, unknown>) => void,
  onFlush: () => void,
  save?: SaveState,
  /** Puts a value the server already wrote into the editor without saving
   * it again (`useAutosave`'s `adopt`). The drafted brief arrives this way. */
  onAdopt?: (patch: Record<string, unknown>) => void,
): AiSeoMode {
  // Only what the readiness *endpoint* answered -- whether the control is
  // enabled also requires the client-observable prerequisites below,
  // computed straight from `detail` rather than mirrored into more state, so
  // an edit the server has not seen yet disables the control immediately
  // without waiting on another round trip (or a synchronous `setState`
  // inside the effect below, which `react-hooks/set-state-in-effect` flags
  // for good reason: nothing here needs the extra render that resetting
  // this to `false` would cost).
  const [remoteReady, setRemoteReady] = useState(false);
  const [remoteReason, setRemoteReason] = useState<string | null>(null);
  const [batchPending, setBatchPending] = useState(false);
  const [deploying, setDeploying] = useState(false);
  /** Bumped by the batch poll, to ask readiness again. */
  const [poll, setPoll] = useState(0);
  const review = useProposalReview(detail, onUpdate, onFlush, save);
  // A run outlives edits; brief adoption must see the current field and callback.
  const latestDetail = useRef(detail);
  const latestOnAdopt = useRef(onAdopt);
  useEffect(() => {
    latestDetail.current = detail;
    latestOnAdopt.current = onAdopt;
  });
  // Only into an empty field: the seller may have started typing their own
  // brief while it was drafted, and their text wins. (The server made the
  // same check before it wrote, but the editor can be ahead of the disk.)
  const onBrief = useCallback((text: string) => {
    if (latestDetail.current.brief.trim() !== "") return;
    latestOnAdopt.current?.({ brief: text });
  }, []);

  const run = useAiRun(detail, save, { onBrief, onProposal: review.onProposal });
  const market = useMarketPanel(detail.name, run);

  // The representative artwork, not any key: it is the one image a run
  // sends, and the server refuses a map without one (spec, *Representative
  // artwork*).
  const hasDesign = representative(detail.design) !== null;
  const hasBrief = detail.brief.trim() !== "";
  const name = detail.name;
  // The client-observable prerequisites, checked before any network call.
  // An empty brief is not one of them: the button drafts it. A listing with
  // no name or no design still never asks the network -- it cannot have had
  // a run, so it has no proposal either -- which is what keeps an ordinary
  // editor test whose fixture has neither from firing a `fetch` it never
  // mocked.
  const prerequisitesMet = name !== "" && hasDesign;
  const saved = save === undefined || save.kind === "saved";
  const canCheck = prerequisitesMet && saved;

  // A check after an edit can read the old file. Recheck when autosave
  // succeeds, even if modified_at is unchanged. Proposal review observes
  // the same saves to refresh server-computed staleness.
  useEffect(() => {
    if (!canCheck) return;
    let current = true;
    getSeoReadiness(name)
      .then((response) => {
        if (current) {
          setRemoteReady(response.ready);
          setRemoteReason(response.reason ?? null);
          setBatchPending(response.batch_pending);
          setDeploying(response.deploying);
        }
      })
      .catch(() => {
        if (current) {
          setRemoteReady(false);
          setRemoteReason("Could not check AI setup.");
          setBatchPending(false);
          setDeploying(false);
        }
      });
    return () => {
      current = false;
    };
  }, [canCheck, name, detail.modified_at, save, poll]);

  const follow = run.follow;
  const refreshProposal = review.refresh;
  useEffect(() => {
    if (!batchPending && !deploying) return;
    const timer = setInterval(() => {
      if (batchPending) follow();
      setPoll((n) => n + 1);
      refreshProposal();
    }, BATCH_POLL_MS);
    return () => clearInterval(timer);
  }, [batchPending, deploying, follow, refreshProposal]);

  const ready = canCheck && remoteReady;
  const reason = canCheck && !ready ? (remoteReason ?? "Checking AI setup...") : null;
  const requirements = [
    { label: "Saved listing", ready: name !== "" && saved },
    { label: "Design selected", ready: hasDesign },
    { label: "SEO prompt and AI provider ready", ready },
  ];

  const startRun = run.start;
  const generate = useCallback(
    () => startRun({ draftBrief: latestDetail.current.brief.trim() === "" }),
    [startRun],
  );
  const phase: AiSeoPhase = run.busy ? "loading" : run.phase === "failed" ? "failed" : "idle";

  return {
    available: ready,
    requirements,
    reason,
    phase,
    proposal: review.proposal,
    staleReason: review.staleReason,
    generate,
    draftsBrief: !hasBrief,
    cancel: run.cancel,
    failure: run.phase === "failed" ? run.message : null,
    startedAt: run.startedAt,
    run,
    market,
    ...review.actions,
  };
}

import { useCallback, useEffect, useRef, useState } from "react";
import { getListingProposal, resolveListingProposal } from "../../../api/seo";
import type { SaveState } from "../../../hooks/useAutosave";
import type {
  AiRunEvent,
  AiRunSummary,
  ListingDetail,
  ListingProposal,
  ProposalResolution,
} from "../../../types";
import { canToggleTag } from "./aiSeoTags";

type Section = keyof ProposalResolution;
type Choice = "accepted" | "dismissed";
interface ResolutionJob {
  generation: string;
  section: Section;
  state: Choice;
  token: number;
}
interface ReviewSession {
  name: string;
  record: ListingProposal | null;
  pending: Partial<Record<Section, ResolutionJob | undefined>>;
  queue: ResolutionJob[];
  active: boolean;
  version: number;
  disposed: boolean;
}

function settleResolution(current: ReviewSession, job: ResolutionJob): boolean {
  if (current.disposed || current.record?.generated_at !== job.generation) return false;
  if (current.pending[job.section]?.token === job.token) current.pending[job.section] = undefined;
  return true;
}

/**
 * One owner for proposal identity, live-event/cache precedence and
 * optimistic drawer resolutions. Resolution writes are serial; pending
 * choices overlay reads until acknowledged, so autosave cannot reopen a
 * drawer while its resolution is still in flight. Accepted content keeps
 * travelling through ordinary autosave, independently of these cache writes.
 */
export function useProposalReview(
  detail: ListingDetail,
  onUpdate: (patch: Record<string, unknown>) => void,
  onFlush: () => void,
  save?: SaveState,
) {
  const session = useRef<ReviewSession | null>(null);
  const editor = useRef({ detail, onUpdate, onFlush });
  const [view, setView] = useState<{ name: string; record: ListingProposal | null }>({
    name: detail.name,
    record: null,
  });
  useEffect(() => {
    editor.current = { detail, onUpdate, onFlush };
  });
  useEffect(() => {
    const current: ReviewSession = {
      name: detail.name,
      record: null,
      pending: {},
      queue: [],
      active: false,
      version: 0,
      disposed: false,
    };
    session.current = current;
    return () => {
      current.disposed = true;
    };
  }, [detail.name]);

  const commit = useCallback((current: ReviewSession, next: ListingProposal | null) => {
    if (current.disposed) return;
    if (next?.generated_at !== current.record?.generated_at) {
      current.pending = {};
      current.queue = [];
    }
    if (next !== null) {
      const resolution = { ...next.resolution };
      for (const job of Object.values(current.pending)) {
        if (job !== undefined) resolution[job.section] = job.state;
      }
      next = { ...next, resolution };
    }
    current.record = next;
    setView({ name: current.name, record: next });
  }, []);

  const read = useCallback(
    (current: ReviewSession) => {
      const version = ++current.version;
      getListingProposal(current.name)
        .then((next) => {
          if (!current.disposed && version === current.version) commit(current, next);
        })
        .catch(() => {});
    },
    [commit],
  );
  const refresh = useCallback(() => {
    const current = session.current;
    if (current !== null && !current.disposed) read(current);
  }, [read]);

  const saved = save === undefined || save.kind === "saved";
  const canRead = detail.name !== "" && Object.keys(detail.design).length > 0 && saved;
  useEffect(() => {
    if (canRead) refresh();
  }, [canRead, detail.name, detail.modified_at, save, refresh]);

  const onProposal = useCallback(
    (event: Extract<AiRunEvent, { type: "proposal" }>, source: AiRunSummary) => {
      const current = session.current;
      // Finished-run replay is history. The server record owns resolutions.
      if (current === null || source.listing !== current.name || source.phase !== "running") return;
      ++current.version;
      const { type, seq, ...record } = event;
      void type;
      void seq;
      commit(current, record);
    },
    [commit],
  );

  const drain = useCallback(
    function send(current: ReviewSession): void {
      // Navigation stops observations, but already-chosen resolutions still persist.
      if (current.active) return;
      const job = current.queue.shift();
      if (job === undefined) return;
      current.active = true;
      const version = ++current.version;
      resolveListingProposal(current.name, {
        generated_at: job.generation,
        [job.section]: job.state,
      })
        .then((next) => {
          if (!settleResolution(current, job)) return;
          const changedWhileSaving = version !== current.version;
          ++current.version;
          if (next === null) read(current);
          else if (changedWhileSaving && current.record !== null) {
            // A later read may have judged this proposal stale. Acknowledge
            // the section without replacing that newer comparison, then
            // reread in case a save's request was still in flight.
            commit(current, {
              ...current.record,
              resolution: { ...current.record.resolution, [job.section]: job.state },
            });
            read(current);
          } else commit(current, next);
        })
        .catch(() => {
          if (settleResolution(current, job)) read(current);
        })
        .finally(() => {
          current.active = false;
          send(current);
        });
    },
    [commit, read],
  );

  const resolve = useCallback(
    (section: Section, state: Choice) => {
      const current = session.current;
      if (current === null || current.disposed || current.record === null) return;
      const job = {
        generation: current.record.generated_at,
        section,
        state,
        token: ++current.version,
      };
      current.pending[section] = job;
      current.queue.push(job);
      commit(current, current.record);
      drain(current);
    },
    [commit, drain],
  );

  const chooseTitle = useCallback(
    (value: string) => {
      editor.current.onUpdate({ etsy: { title: value } });
      editor.current.onFlush();
      resolve("title", "accepted");
    },
    [resolve],
  );
  const chooseLead = useCallback(
    (value: string) => {
      editor.current.onUpdate({
        etsy: { description: { ...editor.current.detail.etsy.description, lead: value } },
      });
      editor.current.onFlush();
      resolve("lead", "accepted");
    },
    [resolve],
  );
  const toggleTag = useCallback((tag: string) => {
    const tags = editor.current.detail.etsy.tags;
    if (!canToggleTag(tags, tag)) return;
    editor.current.onUpdate({
      etsy: { tags: tags.includes(tag) ? tags.filter((t) => t !== tag) : [...tags, tag] },
    });
    editor.current.onFlush();
  }, []);
  const acceptBestTags = useCallback(() => {
    const record = session.current?.record;
    if (record === null || record === undefined) return;
    editor.current.onUpdate({ etsy: { tags: record.proposal.tags.slice(0, 13) } });
    editor.current.onFlush();
    resolve("tags", "accepted");
  }, [resolve]);

  const record = view.name === detail.name ? view.record : null;
  const proposal =
    record !== null && Object.values(record.resolution).some((state) => state === "pending")
      ? record
      : null;
  return {
    proposal,
    staleReason: proposal?.stale.is_stale ? proposal.stale.reasons.join(", ") : null,
    onProposal,
    refresh,
    actions: {
      chooseTitle,
      chooseLead,
      toggleTag,
      acceptBestTags,
      rejectTitle: () => resolve("title", "dismissed"),
      rejectLead: () => resolve("lead", "dismissed"),
      closeTags: () => resolve("tags", "dismissed"),
    },
  };
}

import { describe, expect, it } from "vitest";
import {
  automatic,
  canHaveOwnDesign,
  isLinked,
  keepOne,
  linking,
  listNames,
  pickFor,
  pickForColour,
  representative,
  resolve,
  slotFile,
  slotUsers,
  unlinked,
  wouldPrintAutomatically,
} from "./artwork";

const A = "designs/take-a-hike-dark-ink.png";
const B = "designs/take-a-hike-light-ink.png";
const MOSS = "designs/take-a-hike-moss-special.png";

const TONES = { black: "dark", ivory: "light", moss: "dark", natural: "light" } as const;

/** Interactions Part 2 §3: every Link / Unlink / pick transition, `design`
 * before → after. Colour keys ride along untouched. */
describe("the §3 transitions", () => {
  it("unlinks one design into both slots", () => {
    expect(unlinked({ default: A })).toEqual({ "on-light": A, "on-dark": A });
  });

  it("unlinks an empty draft into two null slots", () => {
    expect(unlinked({})).toEqual({ "on-light": null, "on-dark": null });
  });

  it("keeps colour keys when unlinking", () => {
    expect(unlinked({ default: A, moss: MOSS })).toEqual({
      "on-light": A,
      "on-dark": A,
      moss: MOSS,
    });
  });

  it("picking for dark while linked splits the pair, light keeping the old file", () => {
    expect(pickFor({ default: A }, { kind: "slot", tone: "dark" }, B)).toEqual({
      "on-light": A,
      "on-dark": B,
    });
  });

  it("picking for dark on an empty linked draft leaves light empty", () => {
    expect(pickFor({}, { kind: "slot", tone: "dark" }, B)).toEqual({
      "on-light": null,
      "on-dark": B,
    });
  });

  it("picking for one slot sets only that slot", () => {
    expect(pickFor({ "on-light": null, "on-dark": B }, { kind: "slot", tone: "light" }, A)).toEqual(
      { "on-light": A, "on-dark": B },
    );
  });

  it("picking for all shirts sets default", () => {
    expect(pickFor({ default: A, moss: MOSS }, { kind: "one" }, B)).toEqual({
      default: B,
      moss: MOSS,
    });
  });

  it("links one distinct file straight away", () => {
    expect(linking({ "on-light": A, "on-dark": A })).toEqual({
      kind: "linked",
      design: { default: A },
    });
    expect(linking({ "on-light": null, "on-dark": B, moss: MOSS })).toEqual({
      kind: "linked",
      design: { default: B, moss: MOSS },
    });
  });

  it("links two empty slots to no design", () => {
    expect(linking({ "on-light": null, "on-dark": null })).toEqual({ kind: "linked", design: {} });
  });

  it("asks which to keep when the slots hold two files", () => {
    expect(linking({ "on-light": A, "on-dark": B })).toEqual({ kind: "choose", light: A, dark: B });
  });

  it("keeps the chosen file as default, with the colour keys", () => {
    expect(keepOne({ "on-light": A, "on-dark": B, moss: MOSS }, B)).toEqual({
      default: B,
      moss: MOSS,
    });
  });
});

describe("reading the map", () => {
  it("is linked unless a tone key is present, null included", () => {
    expect(isLinked({})).toBe(true);
    expect(isLinked({ default: A })).toBe(true);
    expect(isLinked({ "on-light": null, "on-dark": null })).toBe(false);
  });

  it("names the file a slot card shows", () => {
    expect(slotFile({ default: A }, { kind: "one" })).toBe(A);
    expect(slotFile({ default: A }, { kind: "slot", tone: "dark" })).toBe(A);
    expect(slotFile({ "on-light": null, "on-dark": B }, { kind: "slot", tone: "light" })).toBe(
      null,
    );
  });

  it("resolves a colour the way config/artwork.py does", () => {
    const pair = { "on-light": A, "on-dark": null, moss: MOSS };
    expect(resolve(pair, "moss", TONES)).toEqual({ kind: "resolved", ref: MOSS, source: "colour" });
    expect(resolve(pair, "ivory", TONES)).toEqual({
      kind: "resolved",
      ref: A,
      source: "on-light",
    });
    expect(resolve(pair, "black", TONES)).toEqual({ kind: "slot-empty", tone: "dark" });
    expect(resolve(pair, "heather", TONES)).toEqual({ kind: "unclassified" });
    expect(resolve({ default: A }, "heather", TONES)).toEqual({
      kind: "resolved",
      ref: A,
      source: "default",
    });
    expect(resolve({}, "black", TONES)).toEqual({ kind: "no-design" });
  });

  it("counts only enabled automatic colours as slot users", () => {
    expect(slotUsers({ "on-dark": B, moss: MOSS }, ["black", "moss", "ivory"], TONES)).toEqual({
      light: ["ivory"],
      dark: ["black"],
    });
  });

  it("represents the listing by default, then on-light, then on-dark", () => {
    expect(representative({ default: A })).toBe(A);
    expect(representative({ "on-light": null, "on-dark": B })).toBe(B);
    expect(representative({ "on-light": A, "on-dark": B })).toBe(A);
    expect(representative({ moss: MOSS })).toBe(null);
  });

  it("lists names the way the banner does", () => {
    expect(listNames([])).toBe("");
    expect(listNames(["ivory"])).toBe("Ivory");
    expect(listNames(["black", "moss", "navy"])).toBe("Black, Moss and Navy");
  });
});

/** Interactions Part 1 §6-§7: a colour's own design, and back. Written
 * straight into `design.<colour>` and removed from it, in either mode, with
 * the base keys untouched. */
describe("a colour's own design", () => {
  it("is written as the colour's key while linked", () => {
    expect(pickForColour({ default: A }, "moss", MOSS)).toEqual({ default: A, moss: MOSS });
  });

  it("is written as the colour's key while unlinked, empty slots kept", () => {
    expect(pickForColour({ "on-light": null, "on-dark": B }, "moss", MOSS)).toEqual({
      "on-light": null,
      "on-dark": B,
      moss: MOSS,
    });
  });

  it("replaces a colour's existing own design", () => {
    expect(pickForColour({ default: A, moss: MOSS }, "moss", B)).toEqual({ default: A, moss: B });
  });

  it("goes back to automatic by removing the key, in either mode", () => {
    expect(automatic({ default: A, moss: MOSS }, "moss")).toEqual({ default: A });
    expect(automatic({ "on-light": A, "on-dark": null, moss: MOSS }, "moss")).toEqual({
      "on-light": A,
      "on-dark": null,
    });
  });

  it("never removes a base key", () => {
    expect(automatic({ default: A }, "default")).toEqual({ default: A });
  });

  it("needs a base key to sit beside: a colour key alone is malformed", () => {
    expect(canHaveOwnDesign({})).toBe(false);
    expect(canHaveOwnDesign({ default: A })).toBe(true);
    expect(canHaveOwnDesign({ "on-light": null, "on-dark": null })).toBe(true);
  });

  it("says what automatic would print, before it is pressed", () => {
    expect(wouldPrintAutomatically({ default: A, moss: MOSS }, "moss", TONES)).toEqual({
      kind: "resolved",
      ref: A,
      source: "default",
    });
    expect(
      wouldPrintAutomatically({ "on-light": A, "on-dark": B, moss: MOSS }, "moss", TONES),
    ).toEqual({ kind: "resolved", ref: B, source: "on-dark" });
    expect(
      wouldPrintAutomatically({ "on-light": A, "on-dark": null, moss: MOSS }, "moss", TONES),
    ).toEqual({ kind: "slot-empty", tone: "dark" });
  });
});

import { act } from "@testing-library/react";
import { type MockInstance, vi } from "vitest";
import * as aiRunsApi from "../api/aiRuns";
import * as marketApi from "../api/market";
import * as seoApi from "../api/seo";
import type { AiRunStreamOptions } from "../api/aiRuns";
import type { AiRun } from "../pages/editor/aiSeo/useAiRun";
import type {
  AiRunEvent,
  AiRunSummary,
  ListingProposal,
  MarketSnapshot,
  WorkflowStep,
} from "../types";

/**
 * A stand-in for the AI runs server, at `api/aiRuns.ts`'s seam: no run is
 * remembered, a start is accepted, a cancel succeeds, and every event
 * stream opened is kept so a test can push events down it. What a test
 * pushes is what the editor sees -- the same `step`/`brief`/`proposal`/
 * `phase` sequence `core/application/ai/runner.py` writes.
 *
 * It also stands in for the listing's cached proposal at `api/seo.ts`:
 * a `proposal` event pushed down a stream is cached first, exactly as the
 * runner writes the record before it announces it, and a resolution is
 * recorded on it -- or refused, as the server refuses one for a proposal
 * that has since been replaced.
 */

/** When {@link aiRunSummary}'s run was created, unless a test says otherwise:
 * fixed, so a start time read from it is a value a test can name. */
export const AI_RUN_CREATED_AT = "2026-09-25T10:00:00Z";

export function aiRunSummary(over: Partial<AiRunSummary> = {}): AiRunSummary {
  return {
    id: "run-1",
    listing: "take-a-hike",
    draft_brief: false,
    origin: "manual",
    phase: "running",
    steps: [
      { id: "brief", state: "skipped", detail: "You wrote the brief, so it was kept" },
      { id: "market", state: "pending", detail: null },
      { id: "seo", state: "pending", detail: null },
    ],
    created_at: AI_RUN_CREATED_AT,
    finished_at: null,
    ...over,
  };
}

export interface FakeStream {
  runId: string;
  options: AiRunStreamOptions;
  closed: boolean;
}

export interface FakeAiRuns {
  streams: FakeStream[];
  /** The most recently opened stream. */
  stream: () => FakeStream;
  /** Pushes events down the most recent stream, inside `act`. */
  emit: (...events: AiRunEvent[]) => void;
  /** Ends the most recent stream, as the server does after `phase`. */
  end: () => void;
  find: MockInstance<typeof aiRunsApi.findAiRun>;
  start: MockInstance<typeof aiRunsApi.startAiRun>;
  cancel: MockInstance<typeof aiRunsApi.cancelAiRun>;
  /** `GET …/market`: no snapshot unless a test gives one. */
  market: MockInstance<typeof marketApi.getMarketSnapshot>;
  /** The server's cached proposal: none unless a test or a `proposal` event
   * puts one there. */
  cached: { proposal: ListingProposal | null };
  /** `GET …/proposal`, answering {@link FakeAiRuns.cached}. */
  loadProposal: MockInstance<typeof seoApi.getListingProposal>;
  /** `PATCH …/proposal/resolution`, recorded on {@link FakeAiRuns.cached}. */
  resolveProposal: MockInstance<typeof seoApi.resolveListingProposal>;
}

export function fakeAiRuns(): FakeAiRuns {
  const streams: FakeStream[] = [];
  const find = vi.spyOn(aiRunsApi, "findAiRun").mockResolvedValue(null);
  const start = vi
    .spyOn(aiRunsApi, "startAiRun")
    .mockImplementation(async (listing, { draftBrief }) => ({
      kind: "started",
      run: aiRunSummary({
        listing,
        draft_brief: draftBrief,
        steps: [
          draftBrief
            ? { id: "brief", state: "pending", detail: null }
            : { id: "brief", state: "skipped", detail: "You wrote the brief, so it was kept" },
          { id: "market", state: "pending", detail: null },
          { id: "seo", state: "pending", detail: null },
        ],
      }),
    }));
  const cancel = vi.spyOn(aiRunsApi, "cancelAiRun").mockResolvedValue(true);
  const market = vi.spyOn(marketApi, "getMarketSnapshot").mockResolvedValue(null);
  const cached: FakeAiRuns["cached"] = { proposal: null };
  const loadProposal = vi
    .spyOn(seoApi, "getListingProposal")
    .mockImplementation(async () => cached.proposal);
  const resolveProposal = vi
    .spyOn(seoApi, "resolveListingProposal")
    .mockImplementation(async (_name, { generated_at, ...sections }) => {
      const current = cached.proposal;
      if (current === null || current.generated_at !== generated_at) return null;
      const resolution = { ...current.resolution };
      for (const [key, value] of Object.entries(sections)) {
        if (value !== null && value !== undefined) {
          resolution[key as keyof typeof resolution] = value;
        }
      }
      cached.proposal = { ...current, resolution };
      return cached.proposal;
    });
  vi.spyOn(aiRunsApi, "openAiRunStream").mockImplementation((runId, options) => {
    const stream: FakeStream = { runId, options, closed: false };
    streams.push(stream);
    return {
      close: () => {
        stream.closed = true;
      },
    };
  });

  function stream(): FakeStream {
    const latest = streams.at(-1);
    if (latest === undefined) throw new Error("no AI run stream was opened");
    return latest;
  }

  return {
    streams,
    stream,
    emit: (...events) =>
      act(() => {
        for (const event of events) {
          if (event.type === "proposal") cached.proposal = proposalOf(event);
          stream().options.onEvent(event);
        }
      }),
    end: () => act(() => stream().options.onDone?.()),
    find,
    start,
    cancel,
    market,
    cached,
    loadProposal,
    resolveProposal,
  };
}

function proposalOf(event: Extract<AiRunEvent, { type: "proposal" }>): ListingProposal {
  const { type, seq, ...proposal } = event;
  void type;
  void seq;
  return proposal;
}

/** A current proposal, every section still open. */
export function listingProposal(over: Partial<ListingProposal> = {}): ListingProposal {
  return {
    proposal: {
      titles: ["Title A", "Title B", "Title C"],
      tags: Array.from({ length: 20 }, (_, i) => `tag-${i}`),
      description_leads: ["Lead A", "Lead B", "Lead C"],
      rationale: [],
      warnings: [],
      observed_text: "",
    },
    snapshot: {
      brief: "A relaxed hiking tee.",
      product_type: "tee",
      etsy_category: "Graphic Tees",
      materials: ["ring-spun cotton"],
      colors: ["black"],
      garment_brand: "Comfort Colors",
      garment_model: "1717",
      garment_profile: "comfort-colors-1717",
      design: { default: "designs/take-a-hike.png" },
